(function(root){
  root.TF_FORECAST_PACKS = root.TF_FORECAST_PACKS || Object.create(null);
  root.TF_FORECAST_PACKS["2026-09-12"] = {"schemaVersion":1,"id":"2026-09-12","title":"Gói TaylorFlow","label":"Sep–Dec 2026","validFrom":"2026-09-01","validTo":"2026-12-31","updated":"2026-11-19","sourceLabel":"đề luyện tập theo chủ đề — do TaylorFlow soạn","part1Topics":[{"id":"daily-routines","title":"Daily routines","reviewed":false,"questions":[{"id":"daily-routines-01","type":"part1-question","part":1,"q":"What time do you usually start your day?","reviewed":false,"aid":{"idea":["Nêu giờ thức dậy thường lệ","Thêm một lý do ngắn cho giờ đó"],"vocab":[{"en":"get up","vi":"thức dậy"},{"en":"set an alarm","vi":"đặt báo thức"},{"en":"ease into the day","vi":"bắt đầu ngày mới từ tốn"},{"en":"morning routine","vi":"thói quen buổi sáng"},{"en":"feel refreshed","vi":"cảm thấy tỉnh táo"},{"en":"on weekdays","vi":"vào các ngày trong tuần"}],"grammar":"Dùng hiện tại đơn để nói về thói quen; dùng usually hoặc around để câu trả lời tự nhiên.","sample":"I usually get up at about seven on weekdays. I set an alarm, but I rarely need a second one because I have a fairly regular routine. After washing up, I make a quick breakfast and check my schedule. Starting at that time gives me enough space to ease into the day without rushing.","reviewed":false}},{"id":"daily-routines-02","type":"part1-question","part":1,"q":"Is your morning routine different at weekends?","reviewed":false,"aid":{"idea":["So sánh giờ thức dậy ngày thường và cuối tuần","Nêu một hoạt động được thêm hoặc bỏ"],"vocab":[{"en":"sleep in","vi":"ngủ nướng"},{"en":"take it easy","vi":"thư thả"},{"en":"have a lie-in","vi":"ngủ thêm vào buổi sáng"},{"en":"weekday schedule","vi":"lịch ngày thường"},{"en":"catch up on sleep","vi":"ngủ bù"},{"en":"without an alarm","vi":"không cần báo thức"}],"grammar":"Dùng cấu trúc used to nếu muốn so sánh với thói quen cũ; hiện tại đơn phù hợp với lịch cuối tuần hiện nay.","sample":"Yes, it is more relaxed at weekends. I often sleep in for an extra hour and have breakfast later than usual. I do not check my messages straight away, either. During the week, I follow a fixed schedule because of classes, so a slower morning at the weekend helps me feel rested.","reviewed":false}},{"id":"daily-routines-03","type":"part1-question","part":1,"q":"Which part of the day do you enjoy most?","reviewed":false,"aid":{"idea":["Chọn một thời điểm cụ thể","Liên hệ với năng lượng hoặc hoạt động yêu thích"],"vocab":[{"en":"early evening","vi":"đầu buổi tối"},{"en":"wind down","vi":"thư giãn sau một ngày"},{"en":"wrap up work","vi":"kết thúc công việc"},{"en":"a quiet moment","vi":"khoảnh khắc yên tĩnh"},{"en":"spend quality time","vi":"dành thời gian ý nghĩa"},{"en":"clear my mind","vi":"giải tỏa đầu óc"}],"grammar":"Dùng because để giải thích lựa chọn, rồi nối thêm một ví dụ bằng when hoặc after.","sample":"I enjoy the early evening most because my main tasks are usually finished by then. I can have a proper meal, talk with my family, or take a short walk nearby. That quiet period helps me wind down and clear my mind before I prepare for the next day.","reviewed":false}},{"id":"daily-routines-04","type":"part1-question","part":1,"q":"Do you prefer planning your day or being spontaneous?","reviewed":false,"aid":{"idea":["Nêu sở thích chính","Thêm cách bạn xử lý việc bất ngờ"],"vocab":[{"en":"make a short plan","vi":"lập kế hoạch ngắn"},{"en":"keep track of","vi":"theo dõi"},{"en":"leave room for","vi":"để chỗ cho"},{"en":"last-minute change","vi":"thay đổi phút chót"},{"en":"stay flexible","vi":"giữ sự linh hoạt"},{"en":"to-do list","vi":"danh sách việc cần làm"}],"grammar":"Dùng would rather hoặc prefer to để nêu lựa chọn; thêm but để thể hiện sự linh hoạt.","sample":"I prefer making a short plan, especially when I have several things to do. I write down the two or three most important tasks, but I do not schedule every minute. Leaving some room for a last-minute change keeps the plan useful instead of stressful.","reviewed":false}},{"id":"daily-routines-05","type":"part1-question","part":1,"q":"Has your daily routine changed recently?","reviewed":false,"aid":{"idea":["Nêu thay đổi gần đây","Giải thích nguyên nhân và cảm nhận"],"vocab":[{"en":"recently","vi":"gần đây"},{"en":"build a habit","vi":"hình thành thói quen"},{"en":"cut down on","vi":"cắt giảm"},{"en":"screen time","vi":"thời gian nhìn màn hình"},{"en":"stick to a routine","vi":"duy trì nề nếp"},{"en":"more consistent","vi":"đều đặn hơn"}],"grammar":"Dùng hiện tại hoàn thành với recently để nói về thay đổi có liên hệ tới hiện tại.","sample":"Yes, it has become more regular over the last few months. I have started preparing my clothes and books the night before, so mornings feel less rushed. I have also cut down on screen time before bed. These small changes make it easier to stick to a routine.","reviewed":false}}]},{"id":"learning-english","title":"Learning English","reviewed":false,"questions":[{"id":"learning-english-01","type":"part1-question","part":1,"q":"Why are you learning English?","reviewed":false,"aid":{"idea":["Nêu mục tiêu gần gũi","Thêm một cơ hội hoặc tình huống cụ thể"],"vocab":[{"en":"communicate with","vi":"giao tiếp với"},{"en":"study materials","vi":"tài liệu học tập"},{"en":"future opportunities","vi":"cơ hội trong tương lai"},{"en":"feel more confident","vi":"cảm thấy tự tin hơn"},{"en":"international content","vi":"nội dung quốc tế"},{"en":"use it in practice","vi":"áp dụng vào thực tế"}],"grammar":"Dùng because để nêu động lực và can để nói về khả năng hoặc lợi ích.","sample":"I am learning English because it gives me access to more study materials and international content. I also want to communicate more confidently when I travel or meet people from other countries. I try to use the language in practical situations, not just memorise rules for a test.","reviewed":false}},{"id":"learning-english-02","type":"part1-question","part":1,"q":"What do you find most challenging about learning English?","reviewed":false,"aid":{"idea":["Chọn một kỹ năng khó","Nêu cách bạn đang cải thiện"],"vocab":[{"en":"follow a conversation","vi":"theo kịp cuộc trò chuyện"},{"en":"connected speech","vi":"lối nói nối âm"},{"en":"pick out key words","vi":"nhận ra từ khóa"},{"en":"at natural speed","vi":"ở tốc độ tự nhiên"},{"en":"listen more actively","vi":"nghe chủ động hơn"},{"en":"with regular practice","vi":"nhờ luyện tập đều"}],"grammar":"Dùng find it + adjective + to-infinitive để diễn đạt điều bạn thấy khó.","sample":"Following fast conversations is the most challenging part for me. Speakers often connect words, so I sometimes miss a key phrase even when I know the vocabulary. I have been listening to short clips more actively and replaying difficult sections. With regular practice, I am beginning to understand natural speech better.","reviewed":false}},{"id":"learning-english-03","type":"part1-question","part":1,"q":"How do you practise English outside class?","reviewed":false,"aid":{"idea":["Nêu một hoặc hai hoạt động thường làm","Mô tả cách biến chúng thành bài luyện"],"vocab":[{"en":"listen to a podcast","vi":"nghe podcast"},{"en":"shadow a speaker","vi":"nói đuổi theo người nói"},{"en":"keep a vocabulary note","vi":"ghi chú từ vựng"},{"en":"read out loud","vi":"đọc thành tiếng"},{"en":"short daily session","vi":"buổi luyện ngắn mỗi ngày"},{"en":"review new phrases","vi":"ôn lại cụm từ mới"}],"grammar":"Dùng hiện tại đơn cho thói quen và after để nối hoạt động trước với hoạt động tiếp theo.","sample":"I practise by listening to a short podcast during my commute. If I hear a useful expression, I write it in a vocabulary note and try to use it in my own sentence later. I also read a few paragraphs out loud. Short daily sessions are easier for me to maintain.","reviewed":false}},{"id":"learning-english-04","type":"part1-question","part":1,"q":"Do you prefer studying English alone or with other people?","reviewed":false,"aid":{"idea":["Chọn cách học hợp với bạn","Nêu một lợi ích của cách còn lại"],"vocab":[{"en":"study at my own pace","vi":"học theo tốc độ riêng"},{"en":"compare ideas","vi":"so sánh ý tưởng"},{"en":"give each other feedback","vi":"góp ý cho nhau"},{"en":"stay focused","vi":"giữ tập trung"},{"en":"a study partner","vi":"bạn học cùng"},{"en":"switch between both","vi":"luân phiên cả hai cách"}],"grammar":"Dùng prefer A to B hoặc prefer to V; thêm when để nêu hoàn cảnh phù hợp.","sample":"I usually prefer studying alone because I can work at my own pace and stay focused on a difficult point. However, practising with a study partner is useful for speaking. We can compare ideas and give each other feedback, so I switch between both methods depending on the skill.","reviewed":false}},{"id":"learning-english-05","type":"part1-question","part":1,"q":"Which English skill would you most like to improve?","reviewed":false,"aid":{"idea":["Chọn một kỹ năng cụ thể","Nêu mục tiêu có thể quan sát được"],"vocab":[{"en":"speak more smoothly","vi":"nói trôi chảy hơn"},{"en":"organise my thoughts","vi":"sắp xếp ý tưởng"},{"en":"use precise vocabulary","vi":"dùng từ chính xác"},{"en":"pause less often","vi":"ngập ngừng ít hơn"},{"en":"sound more natural","vi":"nghe tự nhiên hơn"},{"en":"build speaking confidence","vi":"tăng tự tin khi nói"}],"grammar":"Dùng would like to để nói về mục tiêu và so that để giải thích mục đích.","sample":"I would most like to improve my speaking fluency. I can usually think of an answer, but I sometimes pause while searching for the right words. I want to organise my thoughts more quickly and use precise vocabulary, so that I can express an idea clearly without sounding memorised.","reviewed":false}}]},{"id":"food","title":"Food","reviewed":false,"questions":[{"id":"food-01","type":"part1-question","part":1,"q":"What kind of food do you enjoy eating most?","reviewed":false,"aid":{"idea":["Chọn một món cụ thể và miêu tả hương vị","Nêu lúc bạn thường ăn món đó"],"vocab":[{"en":"a comforting meal","vi":"một bữa ăn dễ chịu"},{"en":"a rich broth","vi":"nước dùng đậm đà"},{"en":"fresh herbs","vi":"rau thơm tươi"},{"en":"a savoury flavour","vi":"hương vị mặn đậm"},{"en":"a local speciality","vi":"đặc sản địa phương"},{"en":"a small treat","vi":"món ngon tự thưởng"}],"grammar":"Dùng hiện tại đơn để nêu sở thích; thêm especially để đưa ra món cụ thể.","sample":"I enjoy noodle dishes most, especially a bowl of beef noodle soup at the weekend. The broth is warm and filling, and I can add herbs to suit my taste. I do not eat it every day, so it still feels like a small treat.","reviewed":false}},{"id":"food-02","type":"part1-question","part":1,"q":"Do you often cook at home?","reviewed":false,"aid":{"idea":["Nêu tần suất nấu ăn","Cho một ví dụ về món đơn giản và lý do"],"vocab":[{"en":"prepare a quick meal","vi":"chuẩn bị bữa ăn nhanh"},{"en":"fresh ingredients","vi":"nguyên liệu tươi"},{"en":"cook from scratch","vi":"tự nấu từ nguyên liệu ban đầu"},{"en":"save money","vi":"tiết kiệm tiền"},{"en":"a simple recipe","vi":"công thức đơn giản"},{"en":"share the cooking","vi":"cùng nhau nấu ăn"}],"grammar":"Dùng hiện tại đơn với once or twice a week để nói tần suất và because để giải thích.","sample":"Yes, I cook at home a few times a week, usually simple meals such as eggs, vegetables and rice. Cooking saves money and lets me choose the ingredients. I am not very adventurous yet, but I have learned to prepare several quick dishes on my own.","reviewed":false}},{"id":"food-03","type":"part1-question","part":1,"q":"Is there a food you disliked as a child but enjoy now?","reviewed":false,"aid":{"idea":["Kể tên món ăn từng không thích","Nêu trải nghiệm khiến bạn đổi ý"],"vocab":[{"en":"an acquired taste","vi":"vị cần thời gian để quen"},{"en":"a strange texture","vi":"kết cấu lạ"},{"en":"grow to like","vi":"dần trở nên yêu thích"},{"en":"try something again","vi":"thử lại món gì đó"},{"en":"absorb the flavour","vi":"thấm hương vị"},{"en":"change my mind","vi":"đổi ý"}],"grammar":"Dùng used to để nói về sở thích cũ, rồi nối với now để so sánh hiện tại.","sample":"I disliked mushrooms when I was younger because their texture seemed strange. I started eating them in a noodle soup a few years ago, and now I like how they absorb the flavour of the broth. I still avoid them when they are cooked in large pieces.","reviewed":false}},{"id":"food-04","type":"part1-question","part":1,"q":"When do you usually have your main meal?","reviewed":false,"aid":{"idea":["Nêu thời điểm ăn bữa chính","Liên hệ với lịch học, làm hoặc sinh hoạt gia đình"],"vocab":[{"en":"sit down together","vi":"ngồi ăn cùng nhau"},{"en":"a proper meal","vi":"một bữa ăn đầy đủ"},{"en":"after a busy day","vi":"sau một ngày bận rộn"},{"en":"eat at a regular time","vi":"ăn vào giờ cố định"},{"en":"keep the meal simple","vi":"giữ bữa ăn đơn giản"},{"en":"a relaxing dinner","vi":"bữa tối thư giãn"}],"grammar":"Dùng hiện tại đơn cho lịch thường lệ và after để nối thời điểm với hoạt động trước đó.","sample":"I usually have my main meal in the evening, after I finish my classes or other tasks. My family can sit down together at that time, which makes dinner more relaxing. If the day is busy, I eat earlier and keep the meal simple.","reviewed":false}},{"id":"food-05","type":"part1-question","part":1,"q":"Have you tried any new dishes recently?","reviewed":false,"aid":{"idea":["Kể tên món mới và nơi bạn thử","Mô tả điều bất ngờ về vị hoặc kết cấu"],"vocab":[{"en":"a steamed rice cake","vi":"bánh gạo hấp"},{"en":"a savoury filling","vi":"nhân mặn"},{"en":"a soft texture","vi":"kết cấu mềm"},{"en":"order a dish","vi":"gọi một món ăn"},{"en":"a street-food stall","vi":"quầy hàng ăn đường phố"},{"en":"give it another try","vi":"thử lại món đó"}],"grammar":"Dùng hiện tại hoàn thành với recently cho trải nghiệm gần đây, sau đó dùng quá khứ đơn để kể chi tiết.","sample":"Recently I tried a steamed rice cake with a savoury filling at a small local shop. I had seen it before but had never ordered it. The texture was softer than I expected, and the herbs gave it a fresh taste. I would buy it again as a snack.","reviewed":false}}]},{"id":"weather","title":"Weather","reviewed":false,"questions":[{"id":"weather-01","type":"part1-question","part":1,"q":"What kind of weather do you like best?","reviewed":false,"aid":{"idea":["Chọn kiểu thời tiết bạn thích","Nêu một hoạt động hợp với thời tiết đó"],"vocab":[{"en":"mild weather","vi":"thời tiết ôn hòa"},{"en":"a light breeze","vi":"làn gió nhẹ"},{"en":"clear skies","vi":"trời quang"},{"en":"go for a walk","vi":"đi dạo"},{"en":"feel comfortable","vi":"cảm thấy thoải mái"},{"en":"lift my mood","vi":"cải thiện tâm trạng"}],"grammar":"Dùng hiện tại đơn để nêu sở thích và because để giải thích bằng cảm nhận hoặc hoạt động.","sample":"I like mild, sunny weather with a light breeze. It is comfortable enough for a walk and does not feel too hot. I also find that a bright day improves my mood, although I am happy to stay indoors if it rains heavily.","reviewed":false}},{"id":"weather-02","type":"part1-question","part":1,"q":"Does the weather affect what you do each day?","reviewed":false,"aid":{"idea":["Nêu thời tiết làm thay đổi kế hoạch ra sao","Cho ví dụ về mưa hoặc ngày mát"],"vocab":[{"en":"adjust my schedule","vi":"điều chỉnh lịch trình"},{"en":"heavy rain","vi":"mưa lớn"},{"en":"take an umbrella","vi":"mang ô"},{"en":"covered transport","vi":"phương tiện có mái che"},{"en":"outdoor exercise","vi":"tập thể dục ngoài trời"},{"en":"check the forecast","vi":"kiểm tra dự báo"}],"grammar":"Dùng câu điều kiện loại một với if để nêu cách bạn ứng phó khi thời tiết thay đổi.","sample":"Yes, it can change my plans quite a bit. When rain is expected, I take an umbrella and use covered transport instead of walking. On cooler days, I am more willing to exercise outside. I check the forecast so I can adjust my schedule without much trouble.","reviewed":false}},{"id":"weather-03","type":"part1-question","part":1,"q":"What is the weather usually like where you live?","reviewed":false,"aid":{"idea":["Mô tả nhiệt độ và mùa mưa hoặc mùa khô","Nêu thời điểm trong ngày dễ chịu hơn"],"vocab":[{"en":"a rainy season","vi":"mùa mưa"},{"en":"a dry period","vi":"giai đoạn khô ráo"},{"en":"high humidity","vi":"độ ẩm cao"},{"en":"a sudden shower","vi":"cơn mưa rào bất chợt"},{"en":"around midday","vi":"khoảng giữa trưa"},{"en":"in the early evening","vi":"vào đầu buổi tối"}],"grammar":"Dùng hiện tại đơn với usually để mô tả đặc điểm khí hậu thường gặp.","sample":"Where I live, the weather is warm for much of the year, with a rainy season and a drier period. Temperatures can feel high around midday, so people often go out in the early morning or evening. A sudden shower is common, especially during the wet months.","reviewed":false}},{"id":"weather-04","type":"part1-question","part":1,"q":"Do you check the weather forecast often?","reviewed":false,"aid":{"idea":["Nêu thời điểm bạn kiểm tra dự báo","Giải thích dự báo giúp chuẩn bị việc gì"],"vocab":[{"en":"check it in the morning","vi":"kiểm tra vào buổi sáng"},{"en":"a detailed report","vi":"bản tin chi tiết"},{"en":"rain is expected","vi":"dự kiến có mưa"},{"en":"make outdoor plans","vi":"lên kế hoạch ngoài trời"},{"en":"carry a small umbrella","vi":"mang theo ô nhỏ"},{"en":"change during the day","vi":"thay đổi trong ngày"}],"grammar":"Dùng hiện tại đơn cho thói quen và enough to để diễn tả mức thông tin cần thiết.","sample":"I check it most mornings, particularly when I have plans outdoors. I do not need a detailed report; knowing whether it will rain is usually enough. I still carry a small umbrella in the wet season because forecasts can change during the day.","reviewed":false}},{"id":"weather-05","type":"part1-question","part":1,"q":"Have you experienced unusual weather recently?","reviewed":false,"aid":{"idea":["Kể một đợt thời tiết khác thường","Nêu ảnh hưởng tới đi lại hoặc lịch sinh hoạt"],"vocab":[{"en":"several days in a row","vi":"nhiều ngày liên tiếp"},{"en":"flood briefly","vi":"ngập trong thời gian ngắn"},{"en":"take longer than usual","vi":"mất nhiều thời gian hơn thường lệ"},{"en":"follow local updates","vi":"theo dõi tin địa phương"},{"en":"basic supplies","vi":"đồ dùng thiết yếu"},{"en":"a rainy season","vi":"mùa mưa"}],"grammar":"Dùng hiện tại hoàn thành trong câu hỏi trải nghiệm và quá khứ đơn để kể sự việc cụ thể.","sample":"A few months ago, we had several days of heavy rain in a row. The streets near my area flooded briefly, and travelling took longer than usual. I stayed home more and followed local updates. It was a reminder to keep basic supplies ready during the rainy season.","reviewed":false}}]},{"id":"travel","title":"Travel","reviewed":false,"questions":[{"id":"travel-01","type":"part1-question","part":1,"q":"Do you enjoy travelling to new places?","reviewed":false,"aid":{"idea":["Nêu điều bạn thích khi khám phá nơi mới","Cho biết bạn thích lịch trình thoải mái hay dày đặc"],"vocab":[{"en":"a new destination","vi":"điểm đến mới"},{"en":"local customs","vi":"phong tục địa phương"},{"en":"try regional food","vi":"thử món ăn vùng miền"},{"en":"a packed schedule","vi":"lịch trình dày đặc"},{"en":"a couple of stops","vi":"một vài điểm dừng"},{"en":"notice everyday life","vi":"để ý cuộc sống thường ngày"}],"grammar":"Dùng hiện tại đơn để nêu sở thích và enough to để nói lịch trình phù hợp.","sample":"Yes, I enjoy visiting places I have not seen before. I like noticing how local people spend their day and trying food that is different from what I eat at home. I do not need a packed schedule; one or two interesting stops are enough for me.","reviewed":false}},{"id":"travel-02","type":"part1-question","part":1,"q":"How do you usually plan a trip?","reviewed":false,"aid":{"idea":["Nêu các bước chuẩn bị chính","Cho biết bạn chừa thời gian tự do hay không"],"vocab":[{"en":"check transport options","vi":"kiểm tra phương tiện đi lại"},{"en":"look up opening hours","vi":"tra cứu giờ mở cửa"},{"en":"save a place on a map","vi":"lưu địa điểm trên bản đồ"},{"en":"leave free time","vi":"chừa thời gian tự do"},{"en":"a flexible plan","vi":"kế hoạch linh hoạt"},{"en":"feel prepared","vi":"cảm thấy đã chuẩn bị"}],"grammar":"Dùng first, then để sắp xếp các bước và but để bổ sung tính linh hoạt.","sample":"I usually choose the destination first, then check transport, the weather and opening hours. I save a few places on a map, but I leave some free time in case I find something unexpected. Planning the main details helps me feel relaxed without making the trip too rigid.","reviewed":false}},{"id":"travel-03","type":"part1-question","part":1,"q":"What kind of transport do you prefer for short journeys?","reviewed":false,"aid":{"idea":["Chọn đi bộ hoặc một phương tiện quen thuộc","Nêu trường hợp bạn sẽ chọn phương tiện khác"],"vocab":[{"en":"a reasonable distance","vi":"khoảng cách vừa phải"},{"en":"avoid traffic","vi":"tránh tắc đường"},{"en":"notice things along the way","vi":"để ý cảnh vật trên đường"},{"en":"a ride service","vi":"dịch vụ gọi xe"},{"en":"the weather is bad","vi":"thời tiết xấu"},{"en":"decide case by case","vi":"quyết định tùy từng trường hợp"}],"grammar":"Dùng prefer + danh từ hoặc V-ing để nêu lựa chọn; dùng if để nêu ngoại lệ.","sample":"For short journeys, I prefer walking if the distance is reasonable. It gives me a chance to notice things along the way and avoids waiting in traffic. If it is too hot or raining, I take a bus or a ride service instead, so I decide based on the weather.","reviewed":false}},{"id":"travel-04","type":"part1-question","part":1,"q":"Do you prefer travelling alone or with other people?","reviewed":false,"aid":{"idea":["Chọn đi cùng một nhóm nhỏ hoặc đi một mình","Nêu lợi ích và hoàn cảnh phù hợp"],"vocab":[{"en":"share the cost","vi":"chia sẻ chi phí"},{"en":"make decisions easily","vi":"dễ đưa ra quyết định"},{"en":"a small group","vi":"một nhóm nhỏ"},{"en":"feel safe","vi":"cảm thấy an toàn"},{"en":"know the area","vi":"quen thuộc khu vực"},{"en":"talk about what we see","vi":"trò chuyện về điều cùng nhìn thấy"}],"grammar":"Dùng generally prefer để nêu xu hướng và whereas để đối chiếu lựa chọn còn lại.","sample":"I generally prefer travelling with one or two people I know well. We can share the cost and talk about what we see, but the group is still small enough to make decisions easily. I would travel alone for a short city visit if I felt safe and knew the area.","reviewed":false}},{"id":"travel-05","type":"part1-question","part":1,"q":"Where would you like to go on your next holiday?","reviewed":false,"aid":{"idea":["Chọn một điểm đến mong muốn","Nêu hai hoạt động và thời điểm bạn muốn đi"],"vocab":[{"en":"a coastal town","vi":"thị trấn ven biển"},{"en":"explore the local market","vi":"khám phá chợ địa phương"},{"en":"fresh seafood","vi":"hải sản tươi"},{"en":"a quiet period","vi":"thời điểm yên tĩnh"},{"en":"fewer crowds","vi":"ít đám đông hơn"},{"en":"a slower trip","vi":"chuyến đi thong thả"}],"grammar":"Dùng would like to cho mong muốn và because để giải thích lựa chọn điểm đến.","sample":"I would like to visit a coastal town for my next holiday. I could spend time by the water, try fresh seafood and explore the local market. I would choose a quiet period rather than a public holiday, because I prefer a slower trip with fewer crowds.","reviewed":false}}]},{"id":"hometown","title":"Hometown","reviewed":false,"questions":[{"id":"hometown-01","type":"part1-question","part":1,"q":"What do you like most about your hometown?","reviewed":false,"aid":{"idea":["Chọn một nét sinh hoạt hoặc cảnh quan bạn quý","Nêu lý do khiến nơi đó đáng nhớ"],"vocab":[{"en":"a familiar corner","vi":"một góc quen thuộc"},{"en":"a lively street","vi":"con phố nhộn nhịp"},{"en":"green public spaces","vi":"không gian công cộng xanh"},{"en":"a strong sense of community","vi":"cảm giác cộng đồng gắn bó"},{"en":"within walking distance","vi":"trong khoảng cách đi bộ"},{"en":"feel at home","vi":"cảm thấy thân thuộc"}],"grammar":"Dùng what I like most is để nhấn vào đặc điểm bạn chọn.","sample":"What I like most is the sense of community. People in my neighbourhood greet one another, and local shopkeepers often remember regular customers. There are also a few green spaces within walking distance, so I can take a quiet break without travelling far. That familiar atmosphere makes me feel at home.","reviewed":false}},{"id":"hometown-02","type":"part1-question","part":1,"q":"Has your hometown changed much in recent years?","reviewed":false,"aid":{"idea":["Nêu một thay đổi dễ quan sát","Đánh giá tác động tích cực hoặc bất tiện"],"vocab":[{"en":"new residential blocks","vi":"các khu chung cư mới"},{"en":"improved public transport","vi":"giao thông công cộng được cải thiện"},{"en":"a busier centre","vi":"khu trung tâm đông đúc hơn"},{"en":"construction work","vi":"công trình xây dựng"},{"en":"daily convenience","vi":"sự tiện lợi hằng ngày"},{"en":"grow at a steady pace","vi":"phát triển với tốc độ ổn định"}],"grammar":"Dùng hiện tại hoàn thành với over the past few years rồi nêu kết quả hiện tại.","sample":"Yes, it has changed quite a bit over the past few years. Several new residential blocks have appeared, and public transport is more convenient than before. The town centre is busier now, so getting around at peak times can be difficult. Overall, the changes have made daily life easier, although traffic needs more attention.","reviewed":false}},{"id":"hometown-03","type":"part1-question","part":1,"q":"Is your hometown a good place for young people?","reviewed":false,"aid":{"idea":["Nêu cơ hội học tập, làm việc hoặc giải trí","Thêm một điều người trẻ có thể còn thiếu"],"vocab":[{"en":"entry-level jobs","vi":"công việc cho người mới bắt đầu"},{"en":"affordable activities","vi":"hoạt động có chi phí vừa phải"},{"en":"training opportunities","vi":"cơ hội đào tạo"},{"en":"a lively social scene","vi":"đời sống giao lưu sôi nổi"},{"en":"career options","vi":"lựa chọn nghề nghiệp"},{"en":"a manageable cost of living","vi":"chi phí sinh hoạt dễ xoay xở"}],"grammar":"Dùng there are để nêu lợi thế và would benefit from để nói đề xuất.","sample":"I think it is a comfortable place for young people who value a manageable cost of living. There are colleges, cafés and some affordable activities, while entry-level jobs are available in several fields. However, the social scene is quieter than in a large city. More evening events would make it appealing to a wider range of young residents.","reviewed":false}},{"id":"hometown-04","type":"part1-question","part":1,"q":"What would you recommend a visitor do in your hometown?","reviewed":false,"aid":{"idea":["Gợi ý một nơi hoặc hoạt động địa phương","Nêu thời điểm hay món ăn phù hợp để trải nghiệm"],"vocab":[{"en":"a neighbourhood market","vi":"khu chợ trong khu phố"},{"en":"sample local dishes","vi":"thử món ăn địa phương"},{"en":"take a riverside walk","vi":"đi dạo ven sông"},{"en":"avoid the midday heat","vi":"tránh cái nóng giữa trưa"},{"en":"observe everyday life","vi":"quan sát nhịp sống thường ngày"},{"en":"a relaxed pace","vi":"nhịp điệu thư thả"}],"grammar":"Dùng I would suggest + V-ing để đưa ra lời giới thiệu tự nhiên.","sample":"I would suggest visiting the neighbourhood market in the morning. Visitors can sample local dishes, browse small stalls and see how people shop for the day. Later, they could take a riverside walk when the weather is cooler. It is a simple plan, but it gives them a feel for everyday life at a relaxed pace.","reviewed":false}},{"id":"hometown-05","type":"part1-question","part":1,"q":"Do you think you will live in your hometown in the future?","reviewed":false,"aid":{"idea":["Nêu dự định hiện tại nhưng giữ câu trả lời linh hoạt","So sánh cơ hội với sự thân thuộc"],"vocab":[{"en":"put down roots","vi":"ổn định lâu dài"},{"en":"stay close to family","vi":"ở gần gia đình"},{"en":"broader opportunities","vi":"cơ hội đa dạng hơn"},{"en":"see how things develop","vi":"chờ xem mọi việc tiến triển thế nào"},{"en":"a practical choice","vi":"lựa chọn thực tế"},{"en":"remain connected","vi":"duy trì sự gắn bó"}],"grammar":"Dùng may hoặc might thay will nếu kế hoạch tương lai còn tùy thuộc hoàn cảnh.","sample":"I may live there again, but I have not made a firm decision. Staying close to my family and friends would be a real advantage. On the other hand, I might move elsewhere for broader career opportunities. For now, I would like to gain experience in a larger city and see how things develop before choosing a place to put down roots.","reviewed":false}}]},{"id":"work-study","title":"Work and study","reviewed":false,"questions":[{"id":"work-study-01","type":"part1-question","part":1,"q":"What subject or kind of work are you involved in?","reviewed":false,"aid":{"idea":["Nêu ngành học hoặc công việc hiện tại","Thêm một nhiệm vụ hay nội dung bạn thường làm"],"vocab":[{"en":"focus on a subject","vi":"tập trung vào một môn học"},{"en":"handle daily tasks","vi":"phụ trách việc hằng ngày"},{"en":"build practical skills","vi":"xây dựng kỹ năng thực tế"},{"en":"a typical assignment","vi":"bài tập thường gặp"},{"en":"work with a team","vi":"làm việc cùng nhóm"},{"en":"learn on the job","vi":"học hỏi ngay trong công việc"}],"grammar":"Dùng hiện tại đơn cho vai trò hiện tại, rồi thêm which involves để giải thích nhiệm vụ.","sample":"I am studying business, with a focus on how organisations work. A typical assignment involves reading a short case and explaining what a company could improve. I enjoy connecting ideas from class with practical situations. It is helping me build useful skills, especially when I have to present a clear argument to my classmates.","reviewed":false}},{"id":"work-study-02","type":"part1-question","part":1,"q":"What do you like most about your studies or work?","reviewed":false,"aid":{"idea":["Chọn một hoạt động khiến bạn thấy hứng thú","Nêu lý do hoặc kết quả bạn nhận được"],"vocab":[{"en":"solve a practical problem","vi":"giải quyết vấn đề thực tế"},{"en":"make steady progress","vi":"tiến bộ đều đặn"},{"en":"a sense of purpose","vi":"cảm giác có mục tiêu"},{"en":"learn from feedback","vi":"học từ góp ý"},{"en":"a supportive group","vi":"nhóm hỗ trợ lẫn nhau"},{"en":"see a clear result","vi":"nhìn thấy kết quả rõ ràng"}],"grammar":"Dùng what I enjoy most is + V-ing để giới thiệu điểm yêu thích.","sample":"What I enjoy most is solving practical problems with other people. We share different ideas, choose the most realistic option and then explain our reasoning. I like being able to see a clear result instead of only memorising information. Feedback from my group also helps me notice small gaps and make steady progress.","reviewed":false}},{"id":"work-study-03","type":"part1-question","part":1,"q":"Do you work or study better in the morning or afternoon?","reviewed":false,"aid":{"idea":["Chọn buổi bạn thường tập trung tốt hơn","Nêu loại việc phù hợp với buổi còn lại"],"vocab":[{"en":"feel mentally fresh","vi":"cảm thấy đầu óc tỉnh táo"},{"en":"tackle a demanding task","vi":"xử lý việc đòi hỏi nhiều tập trung"},{"en":"an energy dip","vi":"lúc năng lượng giảm"},{"en":"review my notes","vi":"xem lại ghi chú"},{"en":"work at a steady pace","vi":"làm việc với nhịp độ ổn định"},{"en":"take a short break","vi":"nghỉ giải lao ngắn"}],"grammar":"Dùng while để đối chiếu thời điểm học sâu với thời điểm làm việc nhẹ hơn.","sample":"I study best in the morning because I feel mentally fresh and can tackle a demanding task before messages start coming in. In the afternoon, I prefer reviewing notes or completing simpler work. My concentration sometimes dips after lunch, so a short walk helps me return to the task and work at a steadier pace.","reviewed":false}},{"id":"work-study-04","type":"part1-question","part":1,"q":"What skill would you most like to develop for work or study?","reviewed":false,"aid":{"idea":["Chọn một kỹ năng cụ thể","Liên hệ kỹ năng đó với mục tiêu sắp tới"],"vocab":[{"en":"speak with confidence","vi":"nói với sự tự tin"},{"en":"organise my thoughts","vi":"sắp xếp ý tưởng"},{"en":"explain a complex point","vi":"giải thích ý phức tạp"},{"en":"take part in a discussion","vi":"tham gia thảo luận"},{"en":"practise in small steps","vi":"luyện từng bước nhỏ"},{"en":"use constructive feedback","vi":"áp dụng góp ý mang tính xây dựng"}],"grammar":"Dùng would like to improve để nói mục tiêu; theo sau bằng so that để nêu mục đích.","sample":"I would most like to improve my presentation skills so I can explain ideas clearly in front of a group. I sometimes know what I want to say but need a moment to organise my thoughts. I am practising in small steps by speaking for a minute on familiar subjects and using feedback to improve my structure.","reviewed":false}},{"id":"work-study-05","type":"part1-question","part":1,"q":"Is it easy for you to concentrate where you work or study?","reviewed":false,"aid":{"idea":["Mô tả mức độ yên tĩnh của không gian","Nêu cách bạn hạn chế xao nhãng"],"vocab":[{"en":"a quiet corner","vi":"góc yên tĩnh"},{"en":"background noise","vi":"tiếng ồn xung quanh"},{"en":"put my phone away","vi":"cất điện thoại đi"},{"en":"stay on task","vi":"duy trì đúng việc đang làm"},{"en":"a focused session","vi":"phiên làm việc tập trung"},{"en":"change locations","vi":"đổi địa điểm"}],"grammar":"Dùng it is easier to concentrate when để gắn điều kiện với mức độ tập trung.","sample":"It is usually easy when I sit at the quieter end of the library. At home, background noise can be distracting, so I put my phone away and work in a focused session of about forty minutes. If other people are busy nearby, I change locations rather than spend too long trying to ignore the noise.","reviewed":false}}]},{"id":"hobbies","title":"Hobbies","reviewed":false,"questions":[{"id":"hobbies-01","type":"part1-question","part":1,"q":"What do you like doing in your free time?","reviewed":false,"aid":{"idea":["Nêu một hoạt động bạn hay chọn","Mô tả cảm giác hoặc lợi ích sau khi làm"],"vocab":[{"en":"a creative outlet","vi":"cách giải tỏa sáng tạo"},{"en":"spare time","vi":"thời gian rảnh"},{"en":"work on a small project","vi":"làm một dự án nhỏ"},{"en":"lose track of time","vi":"mải mê quên thời gian"},{"en":"switch off from work","vi":"tạm quên công việc"},{"en":"make something by hand","vi":"tự tay làm ra một món đồ"}],"grammar":"Dùng enjoy + V-ing để nói sở thích, rồi giải thích bằng it helps me to.","sample":"In my free time, I enjoy sketching simple scenes in a notebook. It gives me a creative outlet and helps me switch off from study. I am not especially skilled, but I like noticing small details in everyday places. Sometimes I lose track of time while trying different shapes and colours.","reviewed":false}},{"id":"hobbies-02","type":"part1-question","part":1,"q":"When did you start this hobby?","reviewed":false,"aid":{"idea":["Nêu thời điểm bắt đầu và người hoặc dịp gợi ý","Giải thích điều khiến bạn tiếp tục"],"vocab":[{"en":"give it a try","vi":"thử làm xem sao"},{"en":"a few years ago","vi":"vài năm trước"},{"en":"pick up a hobby","vi":"bắt đầu một sở thích"},{"en":"a simple starter kit","vi":"bộ dụng cụ cơ bản"},{"en":"keep practising","vi":"tiếp tục luyện tập"},{"en":"improve little by little","vi":"tiến bộ dần dần"}],"grammar":"Dùng quá khứ đơn cho thời điểm bắt đầu, rồi hiện tại hoàn thành để nói bạn vẫn duy trì.","sample":"I started sketching a few years ago when a friend showed me a simple drawing exercise. I gave it a try during a quiet weekend and enjoyed the process more than I expected. Since then, I have kept a small notebook with me. Practising for a few minutes at a time has helped me improve little by little.","reviewed":false}},{"id":"hobbies-03","type":"part1-question","part":1,"q":"Do you share your hobbies with friends?","reviewed":false,"aid":{"idea":["Nêu bạn thường làm một mình hay cùng bạn bè","Cho một ví dụ về cách chia sẻ sở thích"],"vocab":[{"en":"compare our progress","vi":"so sánh tiến độ"},{"en":"swap recommendations","vi":"trao đổi gợi ý"},{"en":"join a casual session","vi":"tham gia buổi sinh hoạt thoải mái"},{"en":"have different tastes","vi":"có sở thích khác nhau"},{"en":"keep it low-pressure","vi":"giữ không khí thoải mái"},{"en":"enjoy it together","vi":"cùng nhau tận hưởng"}],"grammar":"Dùng sometimes để diễn tả mức độ chia sẻ; dùng even though để nhượng bộ một khác biệt.","sample":"Sometimes I show my sketches to a couple of friends, and they share music or photos they like in return. We have different tastes, so the conversation is usually more interesting than trying to do exactly the same activity. I enjoy sharing ideas, but I also keep some hobby time to myself when I need a quiet break.","reviewed":false}},{"id":"hobbies-04","type":"part1-question","part":1,"q":"Is there a hobby you would like to try in the future?","reviewed":false,"aid":{"idea":["Chọn hoạt động mới và nói vì sao tò mò","Nêu bước đầu tiên để thử"],"vocab":[{"en":"take a beginner class","vi":"tham gia lớp cho người mới"},{"en":"learn the basic techniques","vi":"học kỹ thuật cơ bản"},{"en":"borrow some equipment","vi":"mượn một ít dụng cụ"},{"en":"give it a proper try","vi":"thử một cách nghiêm túc"},{"en":"a hands-on activity","vi":"hoạt động thực hành"},{"en":"fit it into my schedule","vi":"xếp vào lịch của mình"}],"grammar":"Dùng would like to try và could để nói mong muốn cùng bước thực hiện khả thi.","sample":"I would like to try pottery because I enjoy hands-on activities and would like to learn how everyday objects are made. I could take a beginner class before buying any equipment. That would let me learn the basic techniques and see whether I enjoy working with clay. I would start with one weekend session to fit it into my schedule.","reviewed":false}},{"id":"hobbies-05","type":"part1-question","part":1,"q":"Have your interests changed since you were a child?","reviewed":false,"aid":{"idea":["Đối chiếu hoạt động khi nhỏ với hiện tại","Nêu sở thích cũ nào vẫn còn hoặc vì sao đã đổi"],"vocab":[{"en":"be keen on","vi":"rất thích"},{"en":"spend hours on","vi":"dành hàng giờ cho"},{"en":"outdoor games","vi":"trò chơi ngoài trời"},{"en":"a more relaxed pace","vi":"nhịp độ thư giãn hơn"},{"en":"discover a new interest","vi":"khám phá sở thích mới"},{"en":"still enjoy the occasional game","vi":"vẫn thỉnh thoảng thích chơi"}],"grammar":"Dùng used to cho sở thích cũ và now để chuyển sang thói quen hiện tại.","sample":"Yes, my interests have changed quite a lot. I used to be keen on outdoor games and could spend hours cycling with neighbours. These days, I prefer quieter activities such as drawing or listening to music. I still enjoy the occasional game with friends, but my free time now has a more relaxed pace.","reviewed":false}}]},{"id":"technology","title":"Technology","reviewed":false,"questions":[{"id":"technology-01","type":"part1-question","part":1,"q":"Which piece of technology do you use most every day?","reviewed":false,"aid":{"idea":["Nêu một thiết bị bạn thường dùng","Liệt kê hai việc thiết bị giúp bạn hoàn thành"],"vocab":[{"en":"a reliable device","vi":"thiết bị đáng tin cậy"},{"en":"check messages","vi":"kiểm tra tin nhắn"},{"en":"keep in touch","vi":"giữ liên lạc"},{"en":"look up information","vi":"tra cứu thông tin"},{"en":"battery life","vi":"thời lượng pin"},{"en":"daily essential","vi":"vật dụng thiết yếu hằng ngày"}],"grammar":"Dùng hiện tại đơn cho thói quen và because để nêu ích lợi chính.","sample":"I use my smartphone more than any other device. It helps me check messages, look up directions and keep in touch with my family. I also use it to read class notes while travelling. I try not to keep every notification on, because that can interrupt my attention during study time.","reviewed":false}},{"id":"technology-02","type":"part1-question","part":1,"q":"Do you enjoy learning how to use new technology?","reviewed":false,"aid":{"idea":["Nêu mức độ tò mò khi có ứng dụng hoặc thiết bị mới","Cho ví dụ về cách bạn tự học"],"vocab":[{"en":"explore the features","vi":"khám phá các tính năng"},{"en":"a user-friendly guide","vi":"hướng dẫn dễ dùng"},{"en":"figure it out","vi":"tự tìm cách hiểu"},{"en":"test it safely","vi":"thử một cách an toàn"},{"en":"a useful shortcut","vi":"phím tắt hữu ích"},{"en":"learn at my own pace","vi":"học theo tốc độ của mình"}],"grammar":"Dùng enjoy + V-ing và thêm unless để nêu giới hạn khi công nghệ phức tạp.","sample":"Yes, I enjoy exploring new features when they seem useful. I usually start with a short guide and then test the basic functions at my own pace. If I get stuck, I ask someone or look for a clear explanation. I am less interested in complicated gadgets unless they solve a real problem for me.","reviewed":false}},{"id":"technology-03","type":"part1-question","part":1,"q":"Has technology changed the way you communicate with people?","reviewed":false,"aid":{"idea":["So sánh liên lạc trực tiếp và qua ứng dụng","Nêu tình huống công nghệ đặc biệt tiện lợi"],"vocab":[{"en":"send a quick update","vi":"gửi tin cập nhật nhanh"},{"en":"video call","vi":"gọi video"},{"en":"stay in regular contact","vi":"giữ liên lạc thường xuyên"},{"en":"share a useful link","vi":"chia sẻ đường dẫn hữu ích"},{"en":"face-to-face conversation","vi":"cuộc trò chuyện trực tiếp"},{"en":"bridge the distance","vi":"thu hẹp khoảng cách"}],"grammar":"Dùng hiện tại hoàn thành với has changed và đối chiếu bằng while.","sample":"Yes, it has made everyday communication much quicker. I can send a short update or arrange a video call in a few seconds, even when relatives live far away. Still, I prefer face-to-face conversations for important topics. Technology helps us bridge the distance, but it does not replace the warmth of meeting in person.","reviewed":false}},{"id":"technology-04","type":"part1-question","part":1,"q":"Do you prefer reading news on a screen or on paper?","reviewed":false,"aid":{"idea":["Chọn định dạng thường dùng","Nêu một ưu điểm và một hạn chế"],"vocab":[{"en":"scroll through headlines","vi":"lướt qua tiêu đề"},{"en":"a printed edition","vi":"bản in"},{"en":"adjust the text size","vi":"điều chỉnh cỡ chữ"},{"en":"read without distractions","vi":"đọc không bị xao nhãng"},{"en":"save an article","vi":"lưu bài viết"},{"en":"a clearer reading habit","vi":"thói quen đọc tập trung hơn"}],"grammar":"Dùng prefer A to B khi so sánh hai định dạng.","sample":"I prefer reading news on a screen because I can check several sources and save an article for later. It is also easy to adjust the text size. However, I sometimes read a printed magazine when I want fewer distractions. For quick updates I choose my phone, while paper works better for a slower reading session.","reviewed":false}},{"id":"technology-05","type":"part1-question","part":1,"q":"Is there any technology you would like to use less?","reviewed":false,"aid":{"idea":["Nêu ứng dụng hoặc thiết bị chiếm nhiều thời gian","Mô tả một giới hạn bạn đang đặt ra"],"vocab":[{"en":"limit screen time","vi":"giới hạn thời gian màn hình"},{"en":"constant notifications","vi":"thông báo liên tục"},{"en":"set a time limit","vi":"đặt giới hạn thời gian"},{"en":"stay focused","vi":"giữ tập trung"},{"en":"put the phone aside","vi":"để điện thoại sang một bên"},{"en":"use it with intention","vi":"sử dụng có chủ đích"}],"grammar":"Dùng would like to spend less time on và hiện tại tiếp diễn để nêu thay đổi đang thử.","sample":"I would like to spend less time scrolling through short videos. They are entertaining, but it is easy to lose track of time. I am trying to set a limit in the evening and put my phone aside while I study. That small change helps me stay focused and use the device more intentionally.","reviewed":false}}]},{"id":"reading","title":"Books and reading","reviewed":false,"questions":[{"id":"reading-01","type":"part1-question","part":1,"q":"Do you enjoy reading books?","reviewed":false,"aid":{"idea":["Nêu thể loại hoặc định dạng bạn thích","Mô tả thời điểm đọc phù hợp"],"vocab":[{"en":"a short chapter","vi":"một chương ngắn"},{"en":"read for pleasure","vi":"đọc để giải trí"},{"en":"a light novel","vi":"tiểu thuyết nhẹ nhàng"},{"en":"build a reading habit","vi":"xây dựng thói quen đọc"},{"en":"fit into my routine","vi":"phù hợp với lịch sinh hoạt"},{"en":"a quiet evening","vi":"buổi tối yên tĩnh"}],"grammar":"Dùng enjoy + V-ing, sau đó thêm especially when để nêu hoàn cảnh.","sample":"Yes, I enjoy reading, especially short novels that are easy to follow after a busy day. I usually read for pleasure in the evening rather than set a strict target. A chapter or two fits into my routine, and I find that putting a book beside my bed makes it easier to build a regular habit.","reviewed":false}},{"id":"reading-02","type":"part1-question","part":1,"q":"What kind of books do you like to read?","reviewed":false,"aid":{"idea":["Chọn một thể loại cụ thể","Nêu yếu tố nội dung khiến bạn muốn đọc tiếp"],"vocab":[{"en":"character-driven story","vi":"câu chuyện tập trung vào nhân vật"},{"en":"unexpected twist","vi":"tình tiết bất ngờ"},{"en":"clear writing style","vi":"lối viết mạch lạc"},{"en":"learn something new","vi":"học thêm điều mới"},{"en":"turn the next page","vi":"lật sang trang kế tiếp"},{"en":"a believable character","vi":"nhân vật đáng tin"}],"grammar":"Dùng books that + mệnh đề quan hệ để mô tả thể loại bạn tìm đọc.","sample":"I tend to choose mysteries with believable characters and a clear writing style. I like trying to work out what happened before the final chapter reveals it. I also read non-fiction if it explains a topic in an accessible way. A book that teaches me something while keeping the story engaging is ideal.","reviewed":false}},{"id":"reading-03","type":"part1-question","part":1,"q":"Where do you usually read?","reviewed":false,"aid":{"idea":["Nêu nơi yên tĩnh bạn thường ngồi đọc","Giải thích ánh sáng hoặc sự thoải mái có quan trọng không"],"vocab":[{"en":"a comfortable chair","vi":"chiếc ghế thoải mái"},{"en":"natural light","vi":"ánh sáng tự nhiên"},{"en":"a quiet corner","vi":"góc yên tĩnh"},{"en":"avoid interruptions","vi":"tránh bị gián đoạn"},{"en":"settle down with a book","vi":"ngồi đọc sách thư thả"},{"en":"a nearby library","vi":"thư viện gần đó"}],"grammar":"Dùng where để nối địa điểm với lý do bạn chọn nơi đó.","sample":"I usually read at my desk or in a quiet corner of the living room. I prefer a comfortable chair and natural light, so I can settle down without feeling tired. When home is noisy, I go to a nearby library. The quiet atmosphere makes it easier to avoid interruptions and finish a chapter.","reviewed":false}},{"id":"reading-04","type":"part1-question","part":1,"q":"Did you read more when you were younger?","reviewed":false,"aid":{"idea":["So sánh lượng đọc hồi nhỏ và hiện nay","Nêu lý do lịch đọc thay đổi"],"vocab":[{"en":"borrow books from","vi":"mượn sách từ"},{"en":"school reading time","vi":"giờ đọc sách ở trường"},{"en":"a growing collection","vi":"bộ sưu tập ngày càng nhiều"},{"en":"a packed schedule","vi":"lịch trình dày đặc"},{"en":"return to a book","vi":"quay lại đọc sách"},{"en":"read in short bursts","vi":"đọc thành những khoảng ngắn"}],"grammar":"Dùng used to cho thói quen cũ và now để đặt cạnh tình hình hiện tại.","sample":"I probably read more when I was at school because we had regular reading periods and I borrowed books from the library. These days, my schedule is busier, so I read in shorter sessions. I still enjoy stories, though, and I often return to a book when I have a quiet weekend.","reviewed":false}},{"id":"reading-05","type":"part1-question","part":1,"q":"Do you prefer printed books or e-books?","reviewed":false,"aid":{"idea":["Chọn định dạng chính và lý do","Nêu trường hợp bạn vẫn dùng định dạng kia"],"vocab":[{"en":"turn a physical page","vi":"lật một trang sách giấy"},{"en":"carry a whole library","vi":"mang theo cả thư viện"},{"en":"a screen-free break","vi":"khoảng nghỉ không màn hình"},{"en":"search for a phrase","vi":"tìm một cụm từ"},{"en":"adjust the brightness","vi":"điều chỉnh độ sáng"},{"en":"make a personal choice","vi":"lựa chọn theo sở thích cá nhân"}],"grammar":"Dùng prefer A to B và nhượng bộ bằng although để câu trả lời cân bằng.","sample":"I prefer printed books for novels because I enjoy turning physical pages and taking a screen-free break. However, e-books are practical when I travel or need to search for a phrase. I use both depending on the situation. If I am reading for a long time at home, paper is usually more comfortable for me.","reviewed":false}}]},{"id":"health-exercise","title":"Health and exercise","reviewed":false,"questions":[{"id":"health-exercise-01","type":"part1-question","part":1,"q":"What do you do to stay healthy?","reviewed":false,"aid":{"idea":["Nêu một thói quen dễ duy trì","Mô tả cách thói quen đó phù hợp với lịch của bạn"],"vocab":[{"en":"keep a regular routine","vi":"duy trì lịch sinh hoạt đều"},{"en":"take a brisk walk","vi":"đi bộ nhanh"},{"en":"drink enough water","vi":"uống đủ nước"},{"en":"get enough rest","vi":"nghỉ ngơi đầy đủ"},{"en":"make a small change","vi":"thực hiện thay đổi nhỏ"},{"en":"feel more energetic","vi":"cảm thấy nhiều năng lượng hơn"}],"grammar":"Dùng hiện tại đơn cho thói quen và after để nối hoạt động với cảm nhận.","sample":"I try to keep a regular routine rather than make dramatic changes. I take a brisk walk several times a week, drink water during the day and aim to get enough rest. Walking is easy to fit around my schedule. After a short session outside, I usually feel more energetic and ready to concentrate.","reviewed":false}},{"id":"health-exercise-02","type":"part1-question","part":1,"q":"Do you enjoy exercising outdoors?","reviewed":false,"aid":{"idea":["Nêu hoạt động ngoài trời bạn thích","So sánh không khí ngoài trời với tập trong nhà"],"vocab":[{"en":"fresh air","vi":"không khí trong lành"},{"en":"a shaded route","vi":"lộ trình có bóng mát"},{"en":"stretch my legs","vi":"duỗi chân vận động"},{"en":"a change of scenery","vi":"đổi khung cảnh"},{"en":"avoid the hottest hours","vi":"tránh giờ nóng nhất"},{"en":"an outdoor routine","vi":"thói quen vận động ngoài trời"}],"grammar":"Dùng prefer V-ing outdoors because để nêu hoạt động và lý do.","sample":"Yes, I enjoy walking outdoors because fresh air and a change of scenery make exercise feel less repetitive. I choose a shaded route and avoid the hottest hours. I sometimes work out indoors when it rains, but a short outdoor walk is my favourite way to stretch my legs after sitting for a long time.","reviewed":false}},{"id":"health-exercise-03","type":"part1-question","part":1,"q":"How often do you take a break when you are busy?","reviewed":false,"aid":{"idea":["Nêu tần suất nghỉ ngắn","Mô tả một việc giúp bạn hồi sức nhanh"],"vocab":[{"en":"step away from my desk","vi":"rời khỏi bàn làm việc"},{"en":"a short reset","vi":"khoảng nghỉ ngắn để lấy lại tập trung"},{"en":"refill my water bottle","vi":"rót thêm nước vào chai"},{"en":"look away from the screen","vi":"nhìn khỏi màn hình"},{"en":"return with a clearer mind","vi":"quay lại với đầu óc tỉnh táo hơn"},{"en":"work in blocks","vi":"làm việc theo từng phiên"}],"grammar":"Dùng every so often hoặc after a block of work để mô tả lịch nghỉ không quá máy móc.","sample":"When I am busy, I try to take a brief break every so often, usually after a block of focused work. I stand up, refill my water bottle and look away from the screen. It only takes a few minutes, but I return with a clearer mind and find it easier to continue the next task.","reviewed":false}},{"id":"health-exercise-04","type":"part1-question","part":1,"q":"Is there a sport you would like to learn?","reviewed":false,"aid":{"idea":["Chọn môn thể thao và lý do bạn muốn thử","Nêu một cách bắt đầu phù hợp cho người mới"],"vocab":[{"en":"learn the basic strokes","vi":"học các động tác cơ bản"},{"en":"a beginner-friendly class","vi":"lớp phù hợp với người mới"},{"en":"build up confidence","vi":"tăng sự tự tin"},{"en":"borrow the equipment","vi":"mượn dụng cụ"},{"en":"practise with a partner","vi":"luyện cùng bạn tập"},{"en":"start at a gentle pace","vi":"bắt đầu với nhịp độ nhẹ"}],"grammar":"Dùng would like to learn và because để nêu mong muốn cùng động lực.","sample":"I would like to learn badminton properly. I play casually, but I have never had coaching on footwork or technique. A beginner-friendly class would help me build confidence without putting too much pressure on myself. I could borrow a racket at first and practise with a partner once I understand the basic strokes.","reviewed":false}},{"id":"health-exercise-05","type":"part1-question","part":1,"q":"Has the way you look after your health changed?","reviewed":false,"aid":{"idea":["Nêu một thói quen bạn mới điều chỉnh","Giải thích vì sao cách nhỏ và đều đặn phù hợp"],"vocab":[{"en":"pay more attention to","vi":"chú ý hơn đến"},{"en":"daily movement","vi":"việc vận động hằng ngày"},{"en":"cut back on late nights","vi":"hạn chế thức khuya"},{"en":"notice a difference","vi":"nhận thấy khác biệt"},{"en":"a manageable goal","vi":"mục tiêu vừa sức"},{"en":"keep it consistent","vi":"duy trì đều đặn"}],"grammar":"Dùng hiện tại hoàn thành với lately và kết quả hiện tại để mô tả sự thay đổi.","sample":"Yes. Lately I have paid more attention to daily movement and regular sleep instead of only thinking about exercise. I now take the stairs when it is practical and try to cut back on late nights. These are manageable goals, and keeping them consistent has made me feel less tired during the day.","reviewed":false}}]},{"id":"home","title":"Home","reviewed":false,"questions":[{"id":"home-01","type":"part1-question","part":1,"q":"What is your favourite room at home?","reviewed":false,"aid":{"idea":["Chọn căn phòng bạn dành nhiều thời gian","Mô tả một chi tiết tạo cảm giác thoải mái"],"vocab":[{"en":"a well-lit room","vi":"căn phòng đủ ánh sáng"},{"en":"a quiet place to focus","vi":"nơi yên tĩnh để tập trung"},{"en":"keep things organised","vi":"giữ đồ đạc ngăn nắp"},{"en":"a comfortable spot","vi":"chỗ ngồi thoải mái"},{"en":"personal touches","vi":"chi tiết mang dấu ấn cá nhân"},{"en":"feel relaxed","vi":"cảm thấy thư giãn"}],"grammar":"Dùng my favourite room is và because để nối đặc điểm với cảm giác.","sample":"My favourite room is the small study area near a window. It is well lit in the afternoon and quiet enough for me to focus. I keep my books and notebooks organised on one shelf, with a comfortable chair beside the desk. A few personal touches make the space feel relaxed rather than like a classroom.","reviewed":false}},{"id":"home-02","type":"part1-question","part":1,"q":"Do you prefer living in a house or an apartment?","reviewed":false,"aid":{"idea":["Chọn kiểu nhà hợp với lối sống","Nêu một tiện ích hoặc bất tiện bạn cân nhắc"],"vocab":[{"en":"a manageable space","vi":"không gian vừa phải"},{"en":"shared facilities","vi":"tiện ích dùng chung"},{"en":"a private outdoor area","vi":"khu vực ngoài trời riêng"},{"en":"easy to maintain","vi":"dễ giữ gìn"},{"en":"close to public transport","vi":"gần giao thông công cộng"},{"en":"suit my current needs","vi":"phù hợp nhu cầu hiện tại"}],"grammar":"Dùng would rather để nói lựa chọn hiện tại và although để nhắc tới mặt hạn chế.","sample":"At the moment, I would rather live in an apartment close to public transport. It is easy to maintain and usually near shops or services. A house with a private garden would be attractive later, although it might take more time to look after. For now, an apartment suits my routine and current needs better.","reviewed":false}},{"id":"home-03","type":"part1-question","part":1,"q":"What do you usually do to make your home comfortable?","reviewed":false,"aid":{"idea":["Nêu một việc chăm sóc nhà cửa thường làm","Thêm thay đổi nhỏ về ánh sáng, nhiệt độ hoặc đồ đạc"],"vocab":[{"en":"let in fresh air","vi":"đón không khí trong lành vào nhà"},{"en":"clear away clutter","vi":"dọn đồ bừa bộn"},{"en":"soft lighting","vi":"ánh sáng dịu"},{"en":"a cool indoor space","vi":"không gian trong nhà mát mẻ"},{"en":"put things back","vi":"cất đồ về chỗ cũ"},{"en":"a welcoming feeling","vi":"cảm giác thân thiện"}],"grammar":"Dùng make + tân ngữ + tính từ, ví dụ make the room feel calmer.","sample":"I open the windows when the weather is pleasant and clear away clutter from the main table. Soft lighting in the evening makes the living room feel calmer. I also put things back after using them, which saves time later. These small habits create a welcoming feeling without needing expensive changes.","reviewed":false}},{"id":"home-04","type":"part1-question","part":1,"q":"Would you like to move to a different home in the future?","reviewed":false,"aid":{"idea":["Nêu mong muốn chuyển hay ở lại","Chọn một điều kiện khiến bạn cân nhắc chuyển nhà"],"vocab":[{"en":"more natural light","vi":"nhiều ánh sáng tự nhiên hơn"},{"en":"a quieter neighbourhood","vi":"khu dân cư yên tĩnh hơn"},{"en":"a spare room","vi":"phòng trống dự phòng"},{"en":"weigh the cost","vi":"cân nhắc chi phí"},{"en":"a longer commute","vi":"quãng đường đi lại dài hơn"},{"en":"make a careful decision","vi":"đưa ra quyết định thận trọng"}],"grammar":"Dùng I might move if để đưa ra dự định có điều kiện.","sample":"I might move in the future if I needed more space or found a quieter neighbourhood. A spare room could be useful for study or guests, but I would weigh the cost and commute carefully. I am comfortable where I live now, so there is no reason to rush. I would move only if the change improved everyday life.","reviewed":false}},{"id":"home-05","type":"part1-question","part":1,"q":"Do you spend much time at home?","reviewed":false,"aid":{"idea":["Ước lượng thời gian ở nhà trong ngày thường","Phân biệt thời gian học, nghỉ và hoạt động bên ngoài"],"vocab":[{"en":"spend most evenings at home","vi":"dành hầu hết buổi tối ở nhà"},{"en":"run errands","vi":"đi giải quyết việc vặt"},{"en":"have a home-cooked meal","vi":"ăn bữa cơm tự nấu"},{"en":"a change of scenery","vi":"đổi khung cảnh"},{"en":"balance indoor and outdoor time","vi":"cân bằng thời gian trong nhà và ngoài trời"},{"en":"feel settled","vi":"cảm thấy ổn định, thư thái"}],"grammar":"Dùng spend time + V-ing và usually để mô tả lịch sinh hoạt.","sample":"I spend most evenings at home because it is where I can relax and prepare for the next day. During the week, I study, have a home-cooked meal and sometimes watch a programme. At weekends I go out for errands or meet friends, so I still get a change of scenery and keep a balance.","reviewed":false}}]}],"part2CueCards":[{"id":"hometown-place-card","type":"part2-cue-card","part":2,"topic":"Hometown and public places","title":"A place you enjoy","task":"Describe a place in your hometown where you enjoy spending time.","bullets":["where it is","what the place looks like","what you usually do there","who you usually go there with"],"conclusion":"and explain why this place matters to you.","reviewed":false,"aid":{"idea":["Chọn công viên hoặc quảng trường dễ mô tả","Kể một lần ghé thăm cụ thể","Kết lại bằng cảm giác nơi đó mang lại"],"vocab":[{"en":"within walking distance","vi":"cách đó một quãng đi bộ"},{"en":"a leafy path","vi":"lối đi rợp bóng cây"},{"en":"a lively atmosphere","vi":"không khí nhộn nhịp"},{"en":"take a break from","vi":"tạm rời khỏi"},{"en":"meet up with friends","vi":"gặp gỡ bạn bè"},{"en":"a familiar landmark","vi":"địa điểm quen thuộc"}],"grammar":"Dùng quá khứ đơn cho kỷ niệm cụ thể, hiện tại đơn cho đặc điểm thường thấy và which để thêm mô tả.","sample":"A place I enjoy spending time in is a small public park near the centre of my hometown. It is within walking distance of a busy shopping street, but once you enter, the traffic becomes much quieter. There is a pond in the middle, a few shaded benches and a leafy path that goes around the garden. The park is not especially large, yet it feels welcoming because people of different ages use it throughout the day. I usually go there in the late afternoon, either alone or with a close friend. We might walk for half an hour, buy a cold drink nearby and talk about what has happened during the week. One visit I remember was after a demanding set of exams. We sat beside the pond and watched families feeding the fish while the sun was setting. It was a simple evening, but I felt my stress fade away. I like this place because it offers a peaceful break without requiring a long trip. It is also a familiar landmark, so meeting someone there is easy. For me, the park is part of the character of my hometown and a comfortable place to slow down.","reviewed":false},"part3Questions":[{"id":"hometown-place-part3-01","type":"part3-question","part":3,"q":"How have public spaces in towns changed in recent years?","reviewed":false,"aid":{"idea":["Nêu thay đổi về tiện ích","Cân nhắc việc thiết kế thân thiện với nhiều nhóm người"],"vocab":[{"en":"pedestrian-friendly","vi":"thân thiện với người đi bộ"},{"en":"public facilities","vi":"tiện ích công cộng"},{"en":"green space","vi":"không gian xanh"},{"en":"be redesigned for","vi":"được thiết kế lại cho"},{"en":"community events","vi":"sự kiện cộng đồng"},{"en":"accessible to everyone","vi":"mọi người đều có thể tiếp cận"}],"grammar":"Dùng hiện tại hoàn thành để mô tả xu hướng thay đổi kéo dài tới hiện tại.","sample":"Many towns have made public spaces more pedestrian-friendly in recent years. Some streets have wider pavements, better lighting and small areas where people can sit. Parks are also used for community events instead of being treated only as green spaces. The improvements are useful, although local planners still need to make these places accessible to older people and families with young children.","reviewed":false}},{"id":"hometown-place-part3-02","type":"part3-question","part":3,"q":"Why do some people prefer spending their free time outdoors?","reviewed":false,"aid":{"idea":["Liên hệ không khí và vận động","So sánh với thời gian ở trong nhà"],"vocab":[{"en":"get some fresh air","vi":"hít thở không khí trong lành"},{"en":"be physically active","vi":"vận động thể chất"},{"en":"change of scenery","vi":"sự thay đổi khung cảnh"},{"en":"spend time together","vi":"dành thời gian cùng nhau"},{"en":"reduce stress","vi":"giảm căng thẳng"},{"en":"screen-free activity","vi":"hoạt động không dùng màn hình"}],"grammar":"Dùng because để nêu nguyên nhân, còn which helps to để nối lợi ích.","sample":"People may choose outdoor activities because they provide fresh air and a change of scenery. A walk or a game in a park also gives them a chance to be physically active without joining a formal class. For families and friends, it can be an inexpensive way to spend time together. These activities reduce screen time as well, which many people find refreshing.","reviewed":false}},{"id":"hometown-place-part3-03","type":"part3-question","part":3,"q":"What should local governments consider when improving public spaces?","reviewed":false,"aid":{"idea":["Tính đến nhu cầu của cư dân","Nhắc tới an toàn, bảo trì và khả năng tiếp cận"],"vocab":[{"en":"consult local residents","vi":"tham khảo ý kiến cư dân địa phương"},{"en":"long-term maintenance","vi":"việc bảo trì lâu dài"},{"en":"safe access","vi":"lối tiếp cận an toàn"},{"en":"a range of needs","vi":"nhiều nhóm nhu cầu"},{"en":"public transport links","vi":"kết nối giao thông công cộng"},{"en":"make the most of","vi":"tận dụng tốt"}],"grammar":"Dùng should để đưa khuyến nghị; dùng not only và but also để nối hai tiêu chí.","sample":"Local governments should ask residents how they use an area before changing it. This can reveal practical needs, such as safe access, shade or places to sit. Officials should also consider long-term maintenance, because a new facility is not helpful if it quickly becomes unsafe. Good public spaces should be accessible by public transport and useful to people with a range of needs.","reviewed":false}},{"id":"hometown-place-part3-04","type":"part3-question","part":3,"q":"Do people in your country socialise in public places as much as in the past?","reviewed":false,"aid":{"idea":["Đưa ra câu trả lời cân bằng","So sánh thói quen gặp trực tiếp và giao tiếp trực tuyến"],"vocab":[{"en":"meet face to face","vi":"gặp trực tiếp"},{"en":"socialise online","vi":"giao lưu trực tuyến"},{"en":"daily routine","vi":"nếp sinh hoạt hằng ngày"},{"en":"a convenient option","vi":"lựa chọn tiện lợi"},{"en":"local gathering place","vi":"điểm tụ họp địa phương"},{"en":"depend on the area","vi":"tùy vào khu vực"}],"grammar":"Dùng used to để nói về thói quen trong quá khứ và whereas để so sánh hai xu hướng.","sample":"I think it depends on the area and the age group. People still meet face to face in cafés, parks and local food streets, particularly when those places are easy to reach. At the same time, socialising online is now a convenient option after a busy day. Some public meeting places seem less central than before, but they remain important for neighbourhood events and casual conversations.","reviewed":false}}]},{"id":"helpful-teacher","topic":"A helpful teacher","task":"Describe a teacher who helped you learn something important.","bullets":["who the teacher was","what you learned","how the teacher helped you","how you felt about the experience"],"conclusion":"and explain why you remember this teacher.","reviewed":false,"aid":{"idea":["Chọn một thầy cô có cách giải thích dễ hiểu","Kể một thời điểm bạn gặp khó và được hướng dẫn","Nêu điều bạn còn áp dụng đến nay"],"vocab":[{"en":"break an idea into steps","vi":"chia một ý thành từng bước"},{"en":"patient explanation","vi":"lời giải thích kiên nhẫn"},{"en":"constructive feedback","vi":"góp ý mang tính xây dựng"},{"en":"build my confidence","vi":"xây dựng sự tự tin"},{"en":"make steady progress","vi":"tiến bộ đều đặn"},{"en":"a lasting lesson","vi":"bài học còn giá trị lâu dài"}],"grammar":"Dùng quá khứ đơn kể trải nghiệm, would often mô tả cách dạy quen thuộc và hiện tại đơn nêu ảnh hưởng còn lại.","sample":"I would like to describe a science teacher I had in secondary school. I used to find the subject difficult because the explanations in my textbook felt very abstract. Instead of repeating the same definition, she would break an idea into small steps and use simple examples from daily life. I remember one lesson about electricity when I could not understand how a circuit worked. She drew it again, asked me a few questions and let me explain the answer in my own words. Her patient explanation made the topic much less intimidating. She also gave constructive feedback without making anyone feel embarrassed for getting something wrong. After a few weeks, I started volunteering answers and noticed that my test results were improving. More importantly, I became comfortable asking questions when I was confused. I still use her advice to deal with a difficult task: understand one part first, then connect it to the bigger picture. I remember her because she helped me build confidence as well as learn science. That lasting lesson has been useful in other subjects and in everyday problem-solving too.","reviewed":false},"part3Questions":[{"id":"helpful-teacher-part3-01","type":"part3-question","part":3,"q":"What qualities make someone an effective teacher?","reviewed":false,"aid":{"idea":["Giải thích rõ và điều chỉnh theo người học","Tạo môi trường đặt câu hỏi an toàn"],"vocab":[{"en":"clear explanations","vi":"lời giải thích rõ ràng"},{"en":"adapt to learners","vi":"điều chỉnh theo người học"},{"en":"patient guidance","vi":"sự hướng dẫn kiên nhẫn"},{"en":"encourage questions","vi":"khuyến khích đặt câu hỏi"},{"en":"give useful feedback","vi":"đưa ra góp ý hữu ích"},{"en":"set realistic goals","vi":"đặt mục tiêu thực tế"}],"grammar":"Dùng need to và not only A but also B để ghép hai phẩm chất quan trọng.","sample":"An effective teacher needs to explain ideas clearly and adapt when students learn at different speeds. Patience matters because some people need another example before a concept makes sense. Teachers should also encourage questions, so learners do not hide confusion. Useful feedback and realistic goals can help students notice progress. Strong subject knowledge is essential, but the ability to make that knowledge understandable is equally important.","reviewed":false}},{"id":"helpful-teacher-part3-02","type":"part3-question","part":3,"q":"How has the role of teachers changed with digital technology?","reviewed":false,"aid":{"idea":["Học liệu trực tuyến giúp tiếp cận thông tin nhanh","Giáo viên vẫn cần hướng dẫn chọn lọc và trao đổi"],"vocab":[{"en":"online learning materials","vi":"tài liệu học trực tuyến"},{"en":"check reliable sources","vi":"kiểm tra nguồn đáng tin"},{"en":"guide independent study","vi":"hướng dẫn tự học"},{"en":"digital platform","vi":"nền tảng số"},{"en":"personal feedback","vi":"góp ý cá nhân"},{"en":"keep learners engaged","vi":"duy trì hứng thú học"}],"grammar":"Dùng hiện tại hoàn thành để nói về thay đổi và while để đối chiếu vai trò mới với vai trò truyền thống.","sample":"Digital platforms have made information and practice materials easier to access. As a result, teachers may spend less time simply presenting facts and more time helping students check reliable sources, ask better questions and apply what they find. Online tools can support independent study, while personal feedback still helps learners understand their own mistakes. Teachers also need to keep students engaged when lessons include screens and remote activities.","reviewed":false}},{"id":"helpful-teacher-part3-03","type":"part3-question","part":3,"q":"Should schools focus more on practical skills or academic knowledge?","reviewed":false,"aid":{"idea":["Hai mục tiêu có thể hỗ trợ lẫn nhau","Nêu ví dụ áp dụng kiến thức vào việc thực tế"],"vocab":[{"en":"academic foundations","vi":"nền tảng học thuật"},{"en":"practical application","vi":"ứng dụng thực tế"},{"en":"solve everyday problems","vi":"giải quyết vấn đề hằng ngày"},{"en":"transferable skills","vi":"kỹ năng có thể áp dụng nhiều nơi"},{"en":"a balanced curriculum","vi":"chương trình học cân bằng"},{"en":"prepare for adult life","vi":"chuẩn bị cho cuộc sống trưởng thành"}],"grammar":"Dùng rather than để tránh đặt hai mục tiêu thành lựa chọn loại trừ nhau.","sample":"Schools should provide academic foundations and show students how to use them. Mathematics, for example, develops reasoning, but learners also benefit from applying it to budgets or measurements. A balanced curriculum can include communication, teamwork and practical problem-solving without reducing time for core subjects. The right combination depends on students' ages, but education should prepare them both to think carefully and to manage ordinary responsibilities.","reviewed":false}},{"id":"helpful-teacher-part3-04","type":"part3-question","part":3,"q":"Why do some students feel uncomfortable asking questions in class?","reviewed":false,"aid":{"idea":["Lo bị đánh giá trước bạn bè","Lớp đông hoặc nhịp giảng nhanh làm khó chen lời"],"vocab":[{"en":"fear of making a mistake","vi":"nỗi sợ mắc lỗi"},{"en":"speak up in class","vi":"phát biểu trong lớp"},{"en":"a supportive atmosphere","vi":"môi trường khích lệ"},{"en":"wait for the right moment","vi":"chờ đúng thời điểm"},{"en":"large class size","vi":"sĩ số lớp đông"},{"en":"ask privately afterwards","vi":"hỏi riêng sau buổi học"}],"grammar":"Dùng may feel + tính từ để nêu cảm xúc, rồi dùng because để giải thích nguyên nhân; although giúp thừa nhận lớp học khác nhau.","sample":"Some students fear making a mistake in front of classmates, especially if the class reacts unkindly. Others may need extra time to form a question or find it difficult to interrupt a fast lesson. A supportive atmosphere can make it easier to speak up. Teachers can offer short pauses, anonymous question cards or a chance to ask privately afterwards, although each class will need a different approach.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A teacher who made a difference"},{"id":"skilled-friend","topic":"A friend with a useful skill","task":"Describe a friend who is good at a practical or creative skill.","bullets":["who the friend is","what skill the friend has","how the friend developed it","how you feel about this ability"],"conclusion":"and explain whether this skill has influenced you.","reviewed":false,"aid":{"idea":["Chọn kỹ năng cụ thể như nấu ăn, sửa đồ hoặc chụp ảnh","Nêu thời gian luyện tập và cách người đó tiến bộ","Kết nối kỹ năng với một lần bạn được giúp"],"vocab":[{"en":"a natural eye for detail","vi":"con mắt tinh ý với chi tiết"},{"en":"practise consistently","vi":"luyện tập đều đặn"},{"en":"learn through trial and error","vi":"học qua thử và sai"},{"en":"share practical tips","vi":"chia sẻ mẹo thực tế"},{"en":"make it look effortless","vi":"làm việc đó trông nhẹ nhàng"},{"en":"inspire me to try","vi":"truyền cảm hứng để tôi thử"}],"grammar":"Dùng hiện tại đơn mô tả kỹ năng, quá khứ đơn kể một lần cụ thể và which để thêm kết quả.","sample":"One of my friends, Minh, is very good at taking photographs. He has a natural eye for detail and can notice interesting light or patterns in places most of us pass without looking. He became interested in photography at university, first using an ordinary phone camera. Rather than buying expensive equipment, he practised consistently and learned through trial and error. He also watches tutorials and asks other photographers for feedback. I saw how much effort he puts in when we visited a weekend market together. He took pictures of the stalls, the food and the conversations between sellers and customers. Later, he showed me how changing the angle could make a familiar scene look completely different. I was surprised by how carefully he had thought about each shot. On another occasion, he helped me take a clear photo for a project, then shared a few practical tips that I still use. I admire his patience because the final pictures look effortless even though he spends time planning them. His skill has inspired me to pay closer attention to everyday details, and it has reminded me that regular practice can develop an ability that seems natural from the outside.","reviewed":false},"part3Questions":[{"id":"skilled-friend-part3-01","type":"part3-question","part":3,"q":"Are people born talented, or can most skills be learned?","reviewed":false,"aid":{"idea":["Một số người có lợi thế ban đầu","Luyện tập và hướng dẫn giúp phần lớn kỹ năng tiến bộ"],"vocab":[{"en":"a natural advantage","vi":"lợi thế tự nhiên"},{"en":"deliberate practice","vi":"luyện tập có chủ đích"},{"en":"develop over time","vi":"phát triển theo thời gian"},{"en":"receive good coaching","vi":"được hướng dẫn tốt"},{"en":"reach a personal standard","vi":"đạt chuẩn của bản thân"},{"en":"different starting points","vi":"điểm xuất phát khác nhau"}],"grammar":"Dùng although để thừa nhận năng khiếu, rồi dùng most people can để nêu lập trường.","sample":"People may begin with different strengths, so a natural advantage can make the first steps easier. However, most useful skills develop through practice, feedback and time. Someone who learns music quickly still needs to rehearse, while a beginner can make steady progress with good coaching. The final level may differ, but many people can become capable enough to use a skill confidently in daily life.","reviewed":false}},{"id":"skilled-friend-part3-02","type":"part3-question","part":3,"q":"How can people find time to develop a new skill?","reviewed":false,"aid":{"idea":["Chia buổi luyện thành khoảng ngắn","Gắn việc luyện với một thời điểm cố định trong tuần"],"vocab":[{"en":"set aside a short slot","vi":"dành một khoảng ngắn"},{"en":"break practice into steps","vi":"chia việc luyện thành bước nhỏ"},{"en":"a realistic routine","vi":"lịch trình thực tế"},{"en":"track small improvements","vi":"theo dõi tiến bộ nhỏ"},{"en":"protect that time","vi":"giữ lại khoảng thời gian đó"},{"en":"fit around commitments","vi":"xếp quanh các cam kết khác"}],"grammar":"Dùng rather than theo sau động từ nguyên mẫu để đề xuất buổi ngắn thay cho mục tiêu quá lớn.","sample":"People can set aside a short, regular slot rather than wait for a free afternoon that may never come. Ten or twenty minutes can be enough for a focused exercise, especially if practice is broken into clear steps. Choosing a consistent time makes the routine easier to remember. Tracking small improvements can also keep motivation up when someone has to fit learning around work, school or family commitments.","reviewed":false}},{"id":"skilled-friend-part3-03","type":"part3-question","part":3,"q":"What makes a good mentor for someone learning a skill?","reviewed":false,"aid":{"idea":["Người hướng dẫn quan sát khó khăn của học viên","Góp ý rõ và giao mục tiêu vừa sức"],"vocab":[{"en":"demonstrate a technique","vi":"làm mẫu một kỹ thuật"},{"en":"notice a recurring mistake","vi":"nhận ra lỗi lặp lại"},{"en":"give specific guidance","vi":"đưa ra chỉ dẫn cụ thể"},{"en":"adjust the level of challenge","vi":"điều chỉnh độ khó"},{"en":"build independence","vi":"xây dựng khả năng tự lập"},{"en":"praise genuine progress","vi":"ghi nhận tiến bộ thật"}],"grammar":"Dùng who để mô tả người hướng dẫn và so that để nêu mục đích của phản hồi.","sample":"A good mentor demonstrates a technique and then watches how the learner tries it. Instead of giving vague praise, they notice a recurring mistake and offer specific guidance so the next attempt is clearer. They should adjust the challenge to the learner's level and praise genuine progress. Over time, a mentor should also build independence, helping the learner make decisions without needing constant supervision.","reviewed":false}},{"id":"skilled-friend-part3-04","type":"part3-question","part":3,"q":"Do adults and children learn skills in the same way?","reviewed":false,"aid":{"idea":["Trẻ em có thể thử nghiệm thoải mái","Người lớn liên hệ kiến thức mới với kinh nghiệm và mục tiêu"],"vocab":[{"en":"learn by experimenting","vi":"học bằng cách thử nghiệm"},{"en":"connect new ideas","vi":"kết nối ý tưởng mới"},{"en":"prior experience","vi":"kinh nghiệm trước đây"},{"en":"fear of failure","vi":"nỗi sợ thất bại"},{"en":"a clear purpose","vi":"mục đích rõ ràng"},{"en":"learn at different speeds","vi":"học với tốc độ khác nhau"}],"grammar":"Dùng whereas để đối chiếu xu hướng, tránh khẳng định tuyệt đối bằng tend to.","sample":"They can learn in similar ways, but their circumstances often differ. Children may learn by experimenting and repeating an activity without needing to understand its long-term value. Adults tend to connect new ideas with prior experience and may have a clear purpose, although work and family responsibilities can limit practice time. Neither group learns in exactly the same way; confidence, interest and teaching methods also matter.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A skill I admire"},{"id":"family-celebration","topic":"A family celebration","task":"Describe a family celebration that you remember well.","bullets":["what was being celebrated","where and when it happened","what people did","why it was memorable"],"conclusion":"and explain how you felt during the celebration.","reviewed":false,"aid":{"idea":["Chọn dịp gia đình có thể cùng chuẩn bị","Kể vài hoạt động hoặc món ăn","Nêu một khoảnh khắc nhỏ làm bạn nhớ lâu"],"vocab":[{"en":"get together as a family","vi":"sum họp gia đình"},{"en":"prepare a shared meal","vi":"chuẩn bị bữa ăn chung"},{"en":"a warm atmosphere","vi":"không khí ấm cúng"},{"en":"catch up with relatives","vi":"hỏi thăm người thân"},{"en":"a small tradition","vi":"truyền thống nhỏ"},{"en":"feel included","vi":"cảm thấy được hòa vào cuộc vui"}],"grammar":"Dùng quá khứ đơn cho trình tự sự kiện, while để mô tả hoạt động diễn ra cùng lúc.","sample":"A family celebration I remember clearly was my grandmother's birthday last year. We gathered at my aunt's home because it had enough space for everyone. A few relatives prepared a shared meal, while the younger members arranged flowers and helped set the table. It was not a formal party, but the warm atmosphere made it feel special. After dinner, we brought out a cake and asked my grandmother to tell us stories from when she was young. Some of the details were new to me, and everyone listened carefully. Later, we looked at old photographs and tried to guess the year each one had been taken. I particularly remember my cousins laughing when they saw their parents' old hairstyles. The celebration was memorable because people from different generations had time to catch up instead of rushing through a meal. I also liked that everyone contributed something small, whether it was food, decorations or a story. I felt included and relaxed throughout the evening. It reminded me that a family event does not need expensive entertainment; sharing a meal and paying attention to one another can be enough to make the occasion meaningful.","reviewed":false},"part3Questions":[{"id":"family-celebration-part3-01","type":"part3-question","part":3,"q":"Why are family celebrations important to many people?","reviewed":false,"aid":{"idea":["Tạo dịp gặp người thân ít gặp","Duy trì cảm giác thuộc về gia đình"],"vocab":[{"en":"mark an important occasion","vi":"đánh dấu dịp quan trọng"},{"en":"strengthen family ties","vi":"thắt chặt tình cảm gia đình"},{"en":"share memories","vi":"chia sẻ kỷ niệm"},{"en":"bring generations together","vi":"kết nối các thế hệ"},{"en":"a sense of belonging","vi":"cảm giác thuộc về"},{"en":"make time for relatives","vi":"dành thời gian cho người thân"}],"grammar":"Dùng can để nêu lợi ích phổ biến mà không khẳng định mọi gia đình giống nhau.","sample":"Family celebrations can give relatives a reason to make time for one another, especially when they live in different places. Sharing a meal or marking an important occasion helps people exchange news and memories. These events may strengthen family ties and give younger members a sense of belonging. The form of a celebration varies, but the opportunity to reconnect is often what people value most.","reviewed":false}},{"id":"family-celebration-part3-02","type":"part3-question","part":3,"q":"How have family celebrations changed in modern life?","reviewed":false,"aid":{"idea":["Lịch bận và khoảng cách ảnh hưởng cách tổ chức","Cuộc gọi trực tuyến giúp người ở xa tham gia"],"vocab":[{"en":"coordinate busy schedules","vi":"sắp xếp lịch bận"},{"en":"celebrate on a different date","vi":"tổ chức vào ngày khác"},{"en":"join by video call","vi":"tham gia qua cuộc gọi video"},{"en":"a smaller gathering","vi":"buổi tụ họp nhỏ hơn"},{"en":"keep a tradition alive","vi":"duy trì truyền thống"},{"en":"make plans in advance","vi":"lên kế hoạch trước"}],"grammar":"Dùng hiện tại hoàn thành để khái quát thay đổi gần đây rồi nêu ví dụ bằng for example.","sample":"Family celebrations have become more flexible in many households. Relatives may coordinate busy schedules and celebrate on a different date, or someone living far away can join by video call. Some families choose a smaller gathering rather than invite a large group. Even so, people often keep a tradition alive, such as sharing a certain dish. The way they meet has changed more than the reason for celebrating.","reviewed":false}},{"id":"family-celebration-part3-03","type":"part3-question","part":3,"q":"Is it better to celebrate at home or in a public venue?","reviewed":false,"aid":{"idea":["Cân nhắc sự thoải mái và công sức dọn dẹp","Lựa chọn tùy quy mô và nhu cầu gia đình"],"vocab":[{"en":"host people at home","vi":"đón khách tại nhà"},{"en":"avoid the preparation work","vi":"tránh việc chuẩn bị"},{"en":"a hired venue","vi":"địa điểm thuê"},{"en":"control the atmosphere","vi":"chủ động không khí"},{"en":"suit the group size","vi":"phù hợp quy mô nhóm"},{"en":"share the practical tasks","vi":"chia sẻ việc thực tế"}],"grammar":"Dùng it depends on để mở câu trả lời cân bằng và whereas để so sánh.","sample":"It depends on the size and purpose of the celebration. Home gatherings feel personal and let the family control the atmosphere, but someone has to prepare food and clean afterwards. A hired venue can reduce that work and may suit a large group, although it costs more. Families should choose the setting that fits their needs and share the practical tasks fairly.","reviewed":false}},{"id":"family-celebration-part3-04","type":"part3-question","part":3,"q":"Should children be involved in planning family events?","reviewed":false,"aid":{"idea":["Trẻ có thể đề xuất hoạt động hợp tuổi","Giao nhiệm vụ nhỏ giúp trẻ hiểu công sức tổ chức"],"vocab":[{"en":"suggest an activity","vi":"đề xuất một hoạt động"},{"en":"take responsibility for","vi":"chịu trách nhiệm về"},{"en":"age-appropriate task","vi":"nhiệm vụ phù hợp lứa tuổi"},{"en":"feel part of the plan","vi":"cảm thấy mình là một phần của kế hoạch"},{"en":"learn to cooperate","vi":"học cách hợp tác"},{"en":"keep the event manageable","vi":"giữ sự kiện trong khả năng"}],"grammar":"Dùng should be invited to để nêu sự tham gia có giới hạn và phù hợp.","sample":"Children should be invited to suggest an activity or help with an age-appropriate task. That can make them feel part of the plan and teach them to cooperate. Adults still need to manage the budget, timing and safety, so the event remains manageable. Giving children a small responsibility is usually more helpful than expecting them to organise the entire celebration.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A family occasion"},{"id":"useful-object","topic":"A useful everyday object","task":"Describe an object that you use regularly and find useful.","bullets":["what the object is","when you got it","how you use it","why it is useful to you"],"conclusion":"and explain what you would do if you no longer had it.","reviewed":false,"aid":{"idea":["Chọn vật dụng dùng thật thường xuyên","Nêu lúc bạn nhận hoặc mua nó","Giải thích lợi ích và cách bạn bảo quản"],"vocab":[{"en":"a reusable water bottle","vi":"chai nước có thể dùng lại"},{"en":"carry it everywhere","vi":"mang theo khắp nơi"},{"en":"keep a drink cool","vi":"giữ đồ uống mát"},{"en":"easy to refill","vi":"dễ châm thêm nước"},{"en":"reduce single-use plastic","vi":"giảm nhựa dùng một lần"},{"en":"a small daily convenience","vi":"tiện ích nhỏ hằng ngày"}],"grammar":"Dùng hiện tại đơn mô tả công dụng và quá khứ đơn nói thời điểm bạn có món đồ.","sample":"An object I use almost every day is a reusable water bottle. I got it as a practical gift from my sister when I started commuting longer distances. It is made of metal, has a secure lid and keeps my drink cool for several hours. I carry it to class, to the library and on short walks. Because it is easy to refill, I do not have to buy a new drink whenever I feel thirsty. It has also helped me reduce single-use plastic, which is a benefit I did not think much about at first. I wash it each evening and leave it open to dry, so it stays fresh. The bottle is not expensive or especially attractive, but it has become a small daily convenience that I rely on. If I forgot it, I would probably buy water once, but I would bring it back the next day. I like useful objects that solve an ordinary problem without needing much attention, and this bottle does exactly that. It reminds me that a simple change in routine can be both practical and a little better for the environment.","reviewed":false},"part3Questions":[{"id":"useful-object-part3-01","type":"part3-question","part":3,"q":"Why do people keep using objects that are familiar to them?","reviewed":false,"aid":{"idea":["Đồ quen thuộc tiết kiệm thời gian học cách dùng","Sự tin cậy làm giảm bất tiện"],"vocab":[{"en":"know how it works","vi":"biết nó hoạt động thế nào"},{"en":"reliable in daily use","vi":"đáng tin trong sử dụng hằng ngày"},{"en":"avoid unnecessary hassle","vi":"tránh phiền toái không cần thiết"},{"en":"fit an existing routine","vi":"hợp với nếp sinh hoạt sẵn có"},{"en":"replace it only when needed","vi":"chỉ thay khi cần thiết"},{"en":"a familiar design","vi":"thiết kế quen thuộc"}],"grammar":"Dùng because để nêu nguyên nhân và even if để thừa nhận có lựa chọn mới hơn.","sample":"People often keep familiar objects because they know how they work and can rely on them. Replacing something requires time, money and sometimes learning a new design. Even if a newer model has extra features, those may not solve a real problem. People are more likely to replace an object when it no longer fits their routine or becomes unreliable in daily use.","reviewed":false}},{"id":"useful-object-part3-02","type":"part3-question","part":3,"q":"How can product design reduce waste?","reviewed":false,"aid":{"idea":["Thiết kế bền và sửa được kéo dài tuổi thọ","Linh kiện thay thế giúp tránh bỏ toàn bộ sản phẩm"],"vocab":[{"en":"built to last","vi":"được làm để dùng lâu"},{"en":"repairable parts","vi":"bộ phận có thể sửa chữa"},{"en":"replaceable components","vi":"linh kiện có thể thay"},{"en":"use recycled materials","vi":"dùng vật liệu tái chế"},{"en":"extend a product's life","vi":"kéo dài tuổi thọ sản phẩm"},{"en":"reduce packaging","vi":"giảm bao bì"}],"grammar":"Dùng can be designed to để nêu cách nhà sản xuất có thể chủ động thay đổi.","sample":"Products can be designed to last longer and be repaired instead of discarded. Replaceable components let consumers fix one damaged part without throwing away the whole item. Manufacturers can also use recycled materials and reduce unnecessary packaging. These choices may involve planning at the design stage, but they can extend a product's life and reduce the amount of waste created after purchase.","reviewed":false}},{"id":"useful-object-part3-03","type":"part3-question","part":3,"q":"Do advertisements influence what household products people buy?","reviewed":false,"aid":{"idea":["Quảng cáo làm người mua chú ý sản phẩm mới","Đánh giá và nhu cầu thực tế vẫn quan trọng"],"vocab":[{"en":"draw attention to","vi":"thu hút sự chú ý tới"},{"en":"a persuasive message","vi":"thông điệp thuyết phục"},{"en":"compare product features","vi":"so sánh tính năng sản phẩm"},{"en":"read customer reviews","vi":"đọc nhận xét khách hàng"},{"en":"buy on impulse","vi":"mua theo cảm hứng nhất thời"},{"en":"a practical need","vi":"nhu cầu thực tế"}],"grammar":"Dùng can influence nhưng thêm whether để nhấn rằng quyết định còn tùy người mua.","sample":"Advertisements can influence which products people notice, especially when a message is repeated or uses a familiar public figure. However, household purchases also depend on price, durability and practical need. Some buyers compare features and read customer reviews before deciding, while others may buy on impulse. Clear product information can help people judge an advertisement rather than accept every claim at face value.","reviewed":false}},{"id":"useful-object-part3-04","type":"part3-question","part":3,"q":"Is it better to repair an object or replace it?","reviewed":false,"aid":{"idea":["Cân nhắc giá sửa, độ an toàn và tuổi thọ còn lại","Sửa chữa thường hợp với vật chất lượng tốt"],"vocab":[{"en":"cost of repair","vi":"chi phí sửa chữa"},{"en":"in safe working order","vi":"hoạt động an toàn"},{"en":"a skilled repair service","vi":"dịch vụ sửa chữa có tay nghề"},{"en":"be worth fixing","vi":"đáng để sửa"},{"en":"a more efficient model","vi":"mẫu tiết kiệm năng lượng hơn"},{"en":"make an informed choice","vi":"đưa ra lựa chọn có đủ thông tin"}],"grammar":"Dùng depends on whether để liệt kê điều kiện ảnh hưởng đến quyết định.","sample":"The better choice depends on the object's age, repair cost and safety. A well-made item is often worth fixing if a skilled service can restore it at a reasonable price. On the other hand, replacing an unsafe appliance with a more efficient model may be sensible. People should compare the likely lifespan and total cost rather than assume that repair or replacement is always best.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"An object I use often"},{"id":"book-that-stayed-with-me","topic":"A book you found meaningful","task":"Describe a book that you found interesting or meaningful.","bullets":["what the book is about","when you read it","which part you found interesting","who you might recommend it to"],"conclusion":"and explain why the book stayed in your memory.","reviewed":false,"aid":{"idea":["Chọn sách bạn đã đọc đủ để kể cụ thể","Nhắc một nhân vật hoặc ý tưởng làm bạn suy nghĩ","Nêu người có thể thấy cuốn sách hữu ích"],"vocab":[{"en":"an engaging story","vi":"câu chuyện cuốn hút"},{"en":"a believable character","vi":"nhân vật đáng tin"},{"en":"raise an important question","vi":"đặt ra câu hỏi quan trọng"},{"en":"read at my own pace","vi":"đọc theo nhịp độ của mình"},{"en":"recommend it to","vi":"giới thiệu cho ai đó"},{"en":"stay in my memory","vi":"còn đọng lại trong trí nhớ"}],"grammar":"Dùng quá khứ đơn kể lần đọc, còn hiện tại đơn trình bày thông điệp hoặc giá trị bạn rút ra.","sample":"A book that stayed in my memory is a short novel about a young person moving to a new city. I read it during a school break after a friend recommended it. The story follows the main character as she learns to manage unfamiliar routines and gradually makes friends. I liked that the character was not instantly confident; she made mistakes and sometimes missed home. One scene I remember is when she calls her family after getting lost on the way to a new class. The conversation is brief, but it shows how a small amount of support can help someone feel less alone. The writing is clear, and each chapter adds a detail about the city or the people around her. I finished the book over a few evenings because I wanted to know how she would adapt. I would recommend it to someone who is about to start university or move somewhere unfamiliar. It is not a guidebook, but it raises an important question about independence and belonging. I appreciated its gentle ending, which felt realistic rather than perfect. The book stayed with me because it made an ordinary transition feel worth understanding.","reviewed":false},"part3Questions":[{"id":"book-that-stayed-with-me-part3-01","type":"part3-question","part":3,"q":"Why do some readers prefer stories to factual books?","reviewed":false,"aid":{"idea":["Nhân vật giúp người đọc hình dung tình huống","Cốt truyện tạo hứng thú để tiếp tục đọc"],"vocab":[{"en":"follow a character's journey","vi":"theo hành trình của nhân vật"},{"en":"be drawn into a story","vi":"bị cuốn vào câu chuyện"},{"en":"explore human emotions","vi":"khám phá cảm xúc con người"},{"en":"learn through examples","vi":"học qua ví dụ"},{"en":"a vivid setting","vi":"bối cảnh sống động"},{"en":"hold someone's attention","vi":"giữ sự chú ý của ai đó"}],"grammar":"Dùng whereas để so sánh trải nghiệm đọc truyện với đọc sách thông tin.","sample":"Stories can draw readers into a character's journey and help them explore emotions through events rather than explanations. A vivid setting or an unexpected problem can hold someone's attention for several chapters. Factual books serve a different purpose: they organise information and may answer a practical question more directly. Some readers move between both forms, choosing a story for relaxation and non-fiction when they want to learn about a topic.","reviewed":false}},{"id":"book-that-stayed-with-me-part3-02","type":"part3-question","part":3,"q":"What can families and schools do to encourage children to read?","reviewed":false,"aid":{"idea":["Cho trẻ quyền chọn sách hợp sở thích","Người lớn làm gương và dành thời gian đọc cùng trẻ"],"vocab":[{"en":"a wide choice of books","vi":"nhiều lựa chọn sách"},{"en":"read together regularly","vi":"đọc cùng nhau đều đặn"},{"en":"let children choose","vi":"để trẻ tự chọn"},{"en":"visit a local library","vi":"ghé thư viện địa phương"},{"en":"a relaxed reading time","vi":"khoảng thời gian đọc thoải mái"},{"en":"connect a story to life","vi":"liên hệ câu chuyện với đời sống"}],"grammar":"Dùng can để nêu gợi ý thực tế và instead of để tránh biến việc đọc thành áp lực.","sample":"Families and schools can make books easy to reach and give children some choice over what they read. A parent or teacher might read together regularly, visit a local library or talk about a story without testing every detail. A relaxed reading time can help children associate books with curiosity. It is usually more effective to connect a story to life than to treat reading only as a school task.","reviewed":false}},{"id":"book-that-stayed-with-me-part3-03","type":"part3-question","part":3,"q":"Will printed books remain popular as digital media grows?","reviewed":false,"aid":{"idea":["Mỗi định dạng đáp ứng hoàn cảnh khác nhau","Sách giấy có cảm giác đọc riêng, bản số tiện mang theo"],"vocab":[{"en":"digital reading format","vi":"định dạng đọc số"},{"en":"carry several titles","vi":"mang theo nhiều đầu sách"},{"en":"a physical collection","vi":"bộ sưu tập sách giấy"},{"en":"reduce screen fatigue","vi":"giảm mỏi mắt do màn hình"},{"en":"easy access to titles","vi":"dễ tiếp cận đầu sách"},{"en":"coexist with technology","vi":"cùng tồn tại với công nghệ"}],"grammar":"Dùng are likely to để dự báo thận trọng và as để chỉ bối cảnh thay đổi.","sample":"Printed books are likely to remain popular even as digital formats become more common. E-books let people carry several titles and search for a passage quickly, which is useful when travelling. Paper books provide a different reading experience and can reduce screen fatigue for some readers. Libraries and shops may adapt their services, while both formats continue to coexist because readers' needs are varied.","reviewed":false}},{"id":"book-that-stayed-with-me-part3-04","type":"part3-question","part":3,"q":"How can libraries stay useful to communities today?","reviewed":false,"aid":{"idea":["Kết hợp sách, tài nguyên số và không gian học","Tổ chức hoạt động để nhiều nhóm cư dân gặp nhau"],"vocab":[{"en":"a shared learning space","vi":"không gian học tập chung"},{"en":"digital resources","vi":"tài nguyên số"},{"en":"community workshops","vi":"buổi sinh hoạt cộng đồng"},{"en":"quiet study areas","vi":"khu học tập yên tĩnh"},{"en":"help people access information","vi":"giúp mọi người tiếp cận thông tin"},{"en":"adapt to local needs","vi":"điều chỉnh theo nhu cầu địa phương"}],"grammar":"Dùng can continue to và bằng cách + V-ing để mô tả vai trò mới của thư viện.","sample":"Libraries can continue to offer quiet study areas while adding digital resources and practical support. Staff may help visitors access information, use public computers or find material in another format. Community workshops can bring different age groups together. The most useful mix will depend on local needs, but libraries are more than shelves of books: they can be safe shared places for learning and participation.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A book I would recommend"},{"id":"memorable-film","topic":"A memorable film","task":"Describe a film that you watched and remember well.","bullets":["what the film was about","when and where you watched it","which part you remember most","what you thought of the film"],"conclusion":"and explain why you would or would not watch it again.","reviewed":false,"aid":{"idea":["Chọn phim có một cảnh hoặc nhân vật đáng nhớ","Kể hoàn cảnh bạn xem và phản ứng của mình","Đánh giá nhịp phim hay cách kể chuyện"],"vocab":[{"en":"a thoughtful storyline","vi":"cốt truyện nhiều suy ngẫm"},{"en":"a quiet turning point","vi":"bước ngoặt nhẹ nhàng"},{"en":"strong performances","vi":"diễn xuất thuyết phục"},{"en":"build up to a scene","vi":"dẫn dắt tới một cảnh"},{"en":"the ending felt earned","vi":"cái kết tạo cảm giác hợp lý"},{"en":"watch it a second time","vi":"xem lại lần thứ hai"}],"grammar":"Dùng quá khứ đơn kể lần xem và would watch again để nêu dự định kèm lý do.","sample":"A film I remember well is a family drama about two siblings who return to their coastal hometown after many years away. I watched it at home one rainy evening with my cousin. At first, the story seemed slow because the characters avoided talking about an old disagreement. The scene I remember most takes place at a small train station. One sibling is about to leave again, but the other finally admits that they both misunderstood what happened in the past. The acting was quiet and natural, so the moment did not feel exaggerated. I also liked the sound design: the wind and distant trains gave the scene a sense of change. The film gradually built up to that turning point rather than explaining everything at once. Its ending was hopeful, but it did not solve every family problem in a perfect way. I thought that made it believable. I would watch it a second time because I might notice early clues in the conversations that I missed at first. I would also recommend it to people who enjoy character-focused films more than action. What made it memorable for me was its gentle reminder that honest communication can arrive later than expected.","reviewed":false},"part3Questions":[{"id":"memorable-film-part3-01","type":"part3-question","part":3,"q":"Can films influence the way people think about social issues?","reviewed":false,"aid":{"idea":["Phim làm một chủ đề dễ hình dung qua nhân vật","Người xem vẫn nên đối chiếu với thông tin khác"],"vocab":[{"en":"raise public awareness","vi":"nâng cao nhận thức cộng đồng"},{"en":"present a human perspective","vi":"đưa ra góc nhìn con người"},{"en":"shape public discussion","vi":"định hình thảo luận công chúng"},{"en":"compare different sources","vi":"so sánh nhiều nguồn"},{"en":"a simplified portrayal","vi":"cách mô tả đơn giản hóa"},{"en":"encourage reflection","vi":"khuyến khích suy ngẫm"}],"grammar":"Dùng can influence nhưng thêm although để giới hạn mức tác động của phim.","sample":"Films can raise awareness by presenting a social issue through the experience of a character, which may feel more immediate than a list of facts. A strong story can encourage viewers to discuss a topic afterwards. However, films may use a simplified portrayal or focus on one perspective. Viewers should treat them as a starting point for reflection and compare different sources before forming a broad opinion.","reviewed":false}},{"id":"memorable-film-part3-02","type":"part3-question","part":3,"q":"Do people prefer watching films at home or in cinemas?","reviewed":false,"aid":{"idea":["Rạp chiếu tạo trải nghiệm màn ảnh và âm thanh lớn","Ở nhà linh hoạt, tiện và thường ít tốn kém"],"vocab":[{"en":"a large screen","vi":"màn hình lớn"},{"en":"cinema sound system","vi":"hệ thống âm thanh rạp"},{"en":"pause whenever needed","vi":"tạm dừng khi cần"},{"en":"watch on demand","vi":"xem theo nhu cầu"},{"en":"a shared atmosphere","vi":"không khí cùng xem"},{"en":"the price of a ticket","vi":"giá vé"}],"grammar":"Dùng while để đối chiếu tính linh hoạt ở nhà với trải nghiệm tại rạp.","sample":"Many people enjoy cinemas for the large screen, sound system and shared atmosphere, especially for a new release. Home viewing is more flexible: people can pause a film, choose from a wider catalogue and avoid travel or ticket costs. Preferences can also depend on the film and household. A visual spectacle may feel more impressive in a cinema, while a quiet drama is easy to enjoy at home.","reviewed":false}},{"id":"memorable-film-part3-03","type":"part3-question","part":3,"q":"What makes a film review useful to potential viewers?","reviewed":false,"aid":{"idea":["Nêu thể loại và điểm mạnh mà không tiết lộ nút thắt","Giải thích đối tượng khán giả phù hợp"],"vocab":[{"en":"avoid major spoilers","vi":"tránh tiết lộ tình tiết chính"},{"en":"describe the tone","vi":"mô tả sắc thái"},{"en":"give specific reasons","vi":"đưa ra lý do cụ thể"},{"en":"set realistic expectations","vi":"đặt kỳ vọng thực tế"},{"en":"suit a particular audience","vi":"hợp với nhóm khán giả nhất định"},{"en":"separate fact from opinion","vi":"phân biệt sự thật và ý kiến"}],"grammar":"Dùng a review is most useful when để nêu tiêu chí, rồi nối bằng if.","sample":"A review is most useful when it explains the film's tone, pacing and main strengths without revealing major spoilers. Specific reasons help readers decide whether it suits their taste. For example, someone who dislikes slow stories should know if a film takes time to develop. A balanced review should separate fact from personal opinion and set realistic expectations instead of claiming that everyone will enjoy it.","reviewed":false}},{"id":"memorable-film-part3-04","type":"part3-question","part":3,"q":"How has online streaming changed film viewing habits?","reviewed":false,"aid":{"idea":["Khán giả chọn thời gian và nội dung dễ hơn","Nhiều lựa chọn có thể khiến việc chọn phim lâu hơn"],"vocab":[{"en":"a subscription service","vi":"dịch vụ thuê bao"},{"en":"watch at a convenient time","vi":"xem vào thời gian thuận tiện"},{"en":"a broad catalogue","vi":"danh mục nội dung rộng"},{"en":"release directly online","vi":"phát hành trực tiếp trực tuyến"},{"en":"browse recommendations","vi":"lướt qua gợi ý"},{"en":"change viewing habits","vi":"thay đổi thói quen xem"}],"grammar":"Dùng hiện tại hoàn thành để nêu tác động đến thói quen và instead of để đối chiếu lịch phát cố định.","sample":"Streaming has made it easier to watch a film at a convenient time instead of following a fixed television schedule. Subscription services offer a broad catalogue, and some productions now release directly online. This gives viewers more choice, though browsing recommendations can take longer than expected. The change has also encouraged people to watch in shorter sessions or across several evenings rather than always seeing a film in one sitting.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A film I remember"},{"id":"helpful-app","topic":"An app that helps with daily life","task":"Describe a mobile app that you find useful.","bullets":["what the app is","how you learned to use it","what you use it for","how it helps you"],"conclusion":"and explain whether you would recommend it to others.","reviewed":false,"aid":{"idea":["Chọn ứng dụng thật sự giúp bạn giải quyết một việc","Nêu tần suất và tình huống sử dụng","Nhắc một giới hạn hoặc lưu ý về quyền riêng tư"],"vocab":[{"en":"keep track of tasks","vi":"theo dõi công việc"},{"en":"set a reminder","vi":"đặt lời nhắc"},{"en":"a simple interface","vi":"giao diện đơn giản"},{"en":"sync across devices","vi":"đồng bộ giữa các thiết bị"},{"en":"save a little time","vi":"tiết kiệm một chút thời gian"},{"en":"check privacy settings","vi":"kiểm tra cài đặt riêng tư"}],"grammar":"Dùng hiện tại đơn mô tả công dụng và present perfect để nêu điều bạn đã thay đổi sau khi dùng.","sample":"A mobile app I find useful is a simple calendar and task planner. I started using it after I forgot a few deadlines during a particularly busy month. A friend showed me how to add a task, choose a date and set a reminder. Now I use it most days to keep track of assignments, appointments and small errands. The interface is straightforward, and it syncs across my phone and laptop, so I can check my schedule wherever I am. I do not add every tiny activity because that would make the list overwhelming. Instead, I record the things I am likely to forget and review them in the morning. The reminders have helped me start work earlier and avoid last-minute rushing. I would recommend the app to someone who wants a basic planning tool, although I would also tell them to check privacy settings before adding personal details. It is not a complete productivity system, and it cannot decide what should be a priority. Still, it saves a little time and gives me a clearer picture of the week. I prefer it to keeping separate notes in several places.","reviewed":false},"part3Questions":[{"id":"helpful-app-part3-01","type":"part3-question","part":3,"q":"Why do some people spend a lot of time on mobile apps?","reviewed":false,"aid":{"idea":["Ứng dụng gộp giao tiếp, giải trí và tiện ích","Thông báo và nội dung đề xuất khuyến khích dùng tiếp"],"vocab":[{"en":"serve several purposes","vi":"đáp ứng nhiều mục đích"},{"en":"personalised recommendations","vi":"gợi ý được cá nhân hóa"},{"en":"check out of habit","vi":"kiểm tra theo thói quen"},{"en":"a constant stream of updates","vi":"luồng cập nhật liên tục"},{"en":"lose track of time","vi":"mải mê quên thời gian"},{"en":"set healthy boundaries","vi":"đặt giới hạn lành mạnh"}],"grammar":"Dùng because và which can make để giải thích cách tính năng tác động tới hành vi.","sample":"Apps serve several purposes, from messages and maps to entertainment, so people may keep returning to the same device. Personalised recommendations and notifications can create a constant stream of updates. Some users open an app automatically whenever they have a spare moment and then lose track of time. Setting healthy boundaries, such as turning off non-essential alerts, can help people stay in control.","reviewed":false}},{"id":"helpful-app-part3-02","type":"part3-question","part":3,"q":"What should app developers consider when collecting user data?","reviewed":false,"aid":{"idea":["Thu thập lượng dữ liệu cần thiết cho chức năng","Giải thích rõ mục đích và cách xóa dữ liệu"],"vocab":[{"en":"collect only necessary data","vi":"chỉ thu thập dữ liệu cần thiết"},{"en":"explain the purpose","vi":"giải thích mục đích"},{"en":"obtain informed consent","vi":"xin sự đồng ý sau khi giải thích"},{"en":"protect personal information","vi":"bảo vệ thông tin cá nhân"},{"en":"a clear privacy notice","vi":"thông báo quyền riêng tư rõ ràng"},{"en":"delete an account easily","vi":"dễ dàng xóa tài khoản"}],"grammar":"Dùng should để nêu nguyên tắc và so that để giải thích lợi ích cho người dùng.","sample":"Developers should collect only the data needed for an app's main function and explain the purpose in plain language. A clear privacy notice helps users make an informed choice before they sign up. Companies also need to protect stored information and make it possible to delete an account easily. These steps can build trust, especially when an app handles location, payment or personal messages.","reviewed":false}},{"id":"helpful-app-part3-03","type":"part3-question","part":3,"q":"How can apps be made easier for older people to use?","reviewed":false,"aid":{"idea":["Chữ dễ đọc và thao tác có nhãn rõ","Thử nghiệm với người dùng có mức tự tin công nghệ khác nhau"],"vocab":[{"en":"readable text size","vi":"cỡ chữ dễ đọc"},{"en":"clearly labelled buttons","vi":"nút có nhãn rõ ràng"},{"en":"simple navigation","vi":"điều hướng đơn giản"},{"en":"avoid hidden gestures","vi":"tránh thao tác ẩn khó nhận ra"},{"en":"test with real users","vi":"thử nghiệm với người dùng thật"},{"en":"offer step-by-step help","vi":"cung cấp hướng dẫn từng bước"}],"grammar":"Dùng could be improved by + V-ing để đưa đề xuất thiết kế.","sample":"Apps could be improved by using readable text, clearly labelled buttons and simple navigation. Designers should avoid relying on hidden gestures that are difficult to discover. It is also useful to test an app with people who have different levels of digital confidence, rather than assume everyone will understand the same layout. Step-by-step help can make the first use less stressful without limiting experienced users.","reviewed":false}},{"id":"helpful-app-part3-04","type":"part3-question","part":3,"q":"Can mobile apps replace face-to-face services completely?","reviewed":false,"aid":{"idea":["Ứng dụng làm giao dịch đơn giản nhanh hơn","Tư vấn phức tạp vẫn cần hỗ trợ trực tiếp"],"vocab":[{"en":"handle routine transactions","vi":"xử lý giao dịch thường ngày"},{"en":"need personal assistance","vi":"cần hỗ trợ trực tiếp"},{"en":"a human point of contact","vi":"đầu mối hỗ trợ là con người"},{"en":"resolve a complex issue","vi":"giải quyết vấn đề phức tạp"},{"en":"offer more than one channel","vi":"cung cấp nhiều kênh hỗ trợ"},{"en":"access services remotely","vi":"tiếp cận dịch vụ từ xa"}],"grammar":"Dùng can replace some tasks, but not all để trả lời có điều kiện.","sample":"Mobile apps can replace some routine transactions, such as booking an appointment or checking a balance. They also let people access services remotely. However, a complex problem may require explanation and personal assistance from a trained staff member. Organisations should offer more than one channel, so users can choose digital convenience or a human point of contact when the situation calls for it.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"An app that is part of my routine"},{"id":"useful-learning-website","topic":"A useful website","task":"Describe a website that you often use for learning or information.","bullets":["what the website is","how you found it","what information you use it for","why you find it useful"],"conclusion":"and explain whether you trust the information it provides.","reviewed":false,"aid":{"idea":["Nêu loại nguồn học hoặc tra cứu trực tuyến","Cho ví dụ lần bạn dùng để giải quyết câu hỏi","Giải thích cách bạn kiểm tra độ tin cậy"],"vocab":[{"en":"search for a topic","vi":"tìm kiếm chủ đề"},{"en":"an organised explanation","vi":"lời giải thích có hệ thống"},{"en":"compare several sources","vi":"so sánh nhiều nguồn"},{"en":"check the publication date","vi":"kiểm tra ngày đăng"},{"en":"save a useful page","vi":"lưu trang hữu ích"},{"en":"a convenient starting point","vi":"điểm khởi đầu thuận tiện"}],"grammar":"Dùng hiện tại đơn mô tả cách dùng; thêm if để nêu bước kiểm tra khi thông tin quan trọng.","sample":"A website I use regularly is an online encyclopedia with short articles on history, science and places around the world. I first found it while looking for background information for a class presentation. Now I use it as a convenient starting point when I need to understand a new topic or check a basic definition. The pages are organised with headings, so I can find the section I need without reading everything. I also like that many articles include references and links to related subjects. I do not treat one webpage as final proof, especially for health, law or current events. If a detail matters, I check the publication date and compare several reliable sources. That habit helps me distinguish a useful overview from information that needs closer verification. I have saved a few pages that explain difficult concepts in clear language, and I return to them when revising. The website is helpful because it gives me structure before I explore more specialised sources. I would recommend it to students, provided they use it thoughtfully and follow the references when they need evidence for an important claim.","reviewed":false},"part3Questions":[{"id":"useful-learning-website-part3-01","type":"part3-question","part":3,"q":"How can people judge whether online information is reliable?","reviewed":false,"aid":{"idea":["Kiểm tra tác giả, ngày đăng và bằng chứng","So sánh với nguồn độc lập có chuyên môn"],"vocab":[{"en":"check the original source","vi":"kiểm tra nguồn gốc ban đầu"},{"en":"identify the author","vi":"xác định tác giả"},{"en":"look for supporting evidence","vi":"tìm bằng chứng hỗ trợ"},{"en":"cross-check a claim","vi":"đối chiếu một nhận định"},{"en":"an independent source","vi":"nguồn độc lập"},{"en":"recognise a sponsored post","vi":"nhận ra bài đăng tài trợ"}],"grammar":"Dùng before sharing để nhấn mạnh bước xác minh trước hành động lan truyền.","sample":"People should check who wrote a page, when it was published and whether it provides evidence for its claims. A useful habit is to cross-check an important detail with an independent source rather than rely on a headline. Readers should also notice when a page is sponsored or trying to sell something. These checks cannot guarantee accuracy, but they reduce the risk of sharing misleading information.","reviewed":false}},{"id":"useful-learning-website-part3-02","type":"part3-question","part":3,"q":"What are the advantages and disadvantages of online education?","reviewed":false,"aid":{"idea":["Học trực tuyến linh hoạt về nơi và giờ","Thiếu trao đổi trực tiếp có thể làm giảm tập trung"],"vocab":[{"en":"learn from any location","vi":"học từ bất kỳ nơi nào"},{"en":"study at a flexible time","vi":"học vào thời gian linh hoạt"},{"en":"a self-paced course","vi":"khóa học theo tốc độ riêng"},{"en":"ask for immediate help","vi":"yêu cầu trợ giúp ngay"},{"en":"maintain motivation","vi":"duy trì động lực"},{"en":"reliable internet access","vi":"kết nối mạng ổn định"}],"grammar":"Dùng while để đặt lợi thế cạnh hạn chế trong cùng một lập luận.","sample":"Online education lets learners study from different locations and revisit a lesson at a flexible time. A self-paced course can suit people balancing work and study. However, some learners find it difficult to maintain motivation without classmates or immediate help from a teacher. Reliable internet access is another requirement. Online learning works best when the course includes interaction and clear ways to ask questions.","reviewed":false}},{"id":"useful-learning-website-part3-03","type":"part3-question","part":3,"q":"Should schools teach students how to use social media responsibly?","reviewed":false,"aid":{"idea":["Dạy bảo vệ thông tin cá nhân và giao tiếp tôn trọng","Giúp nhận diện nội dung sai lệch hoặc gây áp lực"],"vocab":[{"en":"protect personal details","vi":"bảo vệ thông tin cá nhân"},{"en":"think before posting","vi":"suy nghĩ trước khi đăng"},{"en":"respond respectfully","vi":"phản hồi tôn trọng"},{"en":"spot misleading content","vi":"nhận diện nội dung gây hiểu lầm"},{"en":"manage online pressure","vi":"quản lý áp lực trực tuyến"},{"en":"digital citizenship","vi":"trách nhiệm công dân số"}],"grammar":"Dùng should teach learners to để nêu mục tiêu giáo dục cụ thể.","sample":"Schools should teach learners to protect personal details, think before posting and respond respectfully to disagreement. Students also need strategies for spotting misleading content and managing online pressure. Simply banning every platform may not prepare young people for decisions they will make later. Lessons on digital citizenship can give them practical principles while encouraging parents and teachers to discuss real situations.","reviewed":false}},{"id":"useful-learning-website-part3-04","type":"part3-question","part":3,"q":"Will teachers remain important if students can learn online?","reviewed":false,"aid":{"idea":["Tài nguyên số cung cấp kiến thức nhưng không cá nhân hóa hoàn toàn","Giáo viên chẩn đoán khó khăn và tạo trao đổi"],"vocab":[{"en":"curate learning materials","vi":"chọn lọc tài liệu học"},{"en":"notice a learner's difficulty","vi":"nhận ra khó khăn của người học"},{"en":"give individual guidance","vi":"hướng dẫn riêng cho từng người"},{"en":"discuss ideas in depth","vi":"thảo luận ý tưởng sâu hơn"},{"en":"keep a group motivated","vi":"duy trì động lực nhóm"},{"en":"complement digital tools","vi":"bổ trợ công cụ số"}],"grammar":"Dùng are likely to remain để dự đoán và by helping to để nêu vai trò cụ thể.","sample":"Teachers are likely to remain important because access to information is not the same as understanding it. A teacher can notice where a learner is confused, curate useful materials and give individual guidance. Group discussion also lets students test ideas and learn from different perspectives. Online tools can complement this work, but a human teacher helps keep a group motivated and adapts when a lesson is not working.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A site I use to learn"},{"id":"meal-with-friends","topic":"A meal you enjoyed with other people","task":"Describe a meal that you enjoyed with other people.","bullets":["what you ate","where and when you had the meal","who you shared it with","what made the meal enjoyable"],"conclusion":"and explain whether you would like to have a similar meal again.","reviewed":false,"aid":{"idea":["Chọn bữa ăn gắn với một dịp hoặc buổi gặp cụ thể","Miêu tả món ăn và không khí","Nêu cuộc trò chuyện khiến bữa ăn vui hơn"],"vocab":[{"en":"a shared table","vi":"bàn ăn chung"},{"en":"a freshly prepared dish","vi":"món ăn vừa được chuẩn bị"},{"en":"pass food around","vi":"chuyền món ăn quanh bàn"},{"en":"catch up over dinner","vi":"hỏi thăm nhau trong bữa tối"},{"en":"a relaxed conversation","vi":"cuộc trò chuyện thoải mái"},{"en":"leave feeling satisfied","vi":"ra về với cảm giác hài lòng"}],"grammar":"Dùng quá khứ đơn kể bữa ăn và while để mô tả món ăn cùng cuộc trò chuyện diễn ra song song.","sample":"One meal I really enjoyed was a weekend dinner with two close friends at a small family-run restaurant. We had not seen one another for several months, so we chose a quiet table and ordered several dishes to share. There was grilled fish, fresh vegetables and a bowl of rice that had just been cooked. Passing food around made the meal feel informal, and nobody had to choose only one thing. We spent most of the evening catching up on work, family news and small plans for the coming months. One friend had recently started a new job, so we asked about the first weeks and shared a few suggestions. The restaurant was busy, but the staff did not rush us, and the conversation could continue between courses. I remember laughing when we realised that we had all made the same mistake while trying to follow a recipe at home. The food was tasty, but the company made the meal special. It was also reasonably priced, which allowed us to stay longer without worrying about the bill. I would happily have a similar dinner again because it gave us a chance to reconnect in person. It reminded me that sharing a meal can turn an ordinary weekend into a warm memory.","reviewed":false},"part3Questions":[{"id":"meal-with-friends-part3-01","type":"part3-question","part":3,"q":"Why do meals play an important role in many cultures?","reviewed":false,"aid":{"idea":["Bữa ăn tạo dịp gặp gỡ và trò chuyện","Món ăn lưu giữ tập quán và ký ức gia đình"],"vocab":[{"en":"bring people together","vi":"gắn kết mọi người"},{"en":"a shared food tradition","vi":"truyền thống ẩm thực chung"},{"en":"pass recipes down","vi":"truyền lại công thức"},{"en":"mark a special occasion","vi":"đánh dấu dịp đặc biệt"},{"en":"show hospitality","vi":"thể hiện lòng hiếu khách"},{"en":"create a sense of belonging","vi":"tạo cảm giác thuộc về"}],"grammar":"Dùng both A and B để nêu hai vai trò của bữa ăn.","sample":"Meals bring people together and give them time to talk without another activity competing for attention. Food can also carry family and regional traditions, because recipes are passed down and prepared for special occasions. Offering a meal is a common way to show hospitality. Customs vary between places, but eating together can create a sense of belonging and help people mark events in a meaningful way.","reviewed":false}},{"id":"meal-with-friends-part3-02","type":"part3-question","part":3,"q":"Are home-cooked meals better than meals from restaurants?","reviewed":false,"aid":{"idea":["Ở nhà dễ chọn nguyên liệu và khẩu phần","Nhà hàng tiện và giúp thử món mới"],"vocab":[{"en":"control the ingredients","vi":"kiểm soát nguyên liệu"},{"en":"adjust the portion size","vi":"điều chỉnh khẩu phần"},{"en":"save preparation time","vi":"tiết kiệm thời gian chuẩn bị"},{"en":"try unfamiliar dishes","vi":"thử món chưa quen"},{"en":"eat out occasionally","vi":"thỉnh thoảng ăn ngoài"},{"en":"depend on the situation","vi":"tùy vào hoàn cảnh"}],"grammar":"Mở đầu bằng it depends on và so sánh hai lựa chọn bằng whereas.","sample":"Neither option is always better; it depends on the situation. Home cooking lets people control ingredients and portion sizes, and it can be less expensive. Restaurants save preparation time and offer dishes that someone may not know how to make. A balanced routine could include both: home meals on ordinary days and eating out occasionally for convenience or a social event.","reviewed":false}},{"id":"meal-with-friends-part3-03","type":"part3-question","part":3,"q":"Should schools teach children about nutrition and cooking?","reviewed":false,"aid":{"idea":["Kỹ năng chọn thực phẩm hỗ trợ quyết định hằng ngày","Nấu món đơn giản giúp trẻ tự lập hơn"],"vocab":[{"en":"read a food label","vi":"đọc nhãn thực phẩm"},{"en":"prepare a simple dish","vi":"chuẩn bị món ăn đơn giản"},{"en":"understand balanced meals","vi":"hiểu bữa ăn cân bằng"},{"en":"make informed choices","vi":"đưa ra lựa chọn có hiểu biết"},{"en":"build practical confidence","vi":"xây dựng sự tự tin thực tế"},{"en":"use basic kitchen skills","vi":"dùng kỹ năng bếp cơ bản"}],"grammar":"Dùng should include và so that để nêu nội dung học và mục đích.","sample":"Schools should include basic nutrition and cooking lessons so children can make informed choices later. Learning to read a food label or prepare a simple dish is practical, regardless of a student's future job. Such lessons can also explain balanced meals without making food choices feel like a test. Families remain important, but school can ensure that every child gets some basic guidance.","reviewed":false}},{"id":"meal-with-friends-part3-04","type":"part3-question","part":3,"q":"What can restaurants do to reduce food waste?","reviewed":false,"aid":{"idea":["Điều chỉnh khẩu phần và cho chọn lượng ăn","Quyên góp thực phẩm an toàn còn dư"],"vocab":[{"en":"offer different portion sizes","vi":"cung cấp nhiều cỡ phần ăn"},{"en":"plan stock carefully","vi":"lên kế hoạch hàng tồn cẩn thận"},{"en":"track kitchen waste","vi":"theo dõi thức ăn thừa trong bếp"},{"en":"donate safe surplus food","vi":"quyên góp thực phẩm dư còn an toàn"},{"en":"store ingredients properly","vi":"bảo quản nguyên liệu đúng cách"},{"en":"avoid over-ordering","vi":"tránh gọi quá nhiều"}],"grammar":"Dùng can reduce waste by + V-ing để nêu giải pháp có thể thực hiện.","sample":"Restaurants can reduce waste by tracking which ingredients are often left unused and planning stock more carefully. Offering different portion sizes may prevent customers from ordering more than they can eat. Where local rules allow it, safe surplus food can be donated. Staff training on storage and preparation is also useful, because preventing waste at the start is usually better than dealing with it later.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"Dinner with people I enjoy"},{"id":"journey-delay","topic":"A journey that took longer than expected","task":"Describe a journey that took longer than you expected.","bullets":["where you were going","how you travelled","what caused the delay","what you did while waiting"],"conclusion":"and explain how you felt about the experience afterwards.","reviewed":false,"aid":{"idea":["Chọn chuyến đi có nguyên nhân trễ rõ ràng","Kể bạn xử lý việc chờ đợi thế nào","Nêu điều bạn chuẩn bị khác đi sau trải nghiệm"],"vocab":[{"en":"a traffic bottleneck","vi":"điểm nghẽn giao thông"},{"en":"miss a connection","vi":"lỡ chuyến nối tiếp"},{"en":"check an updated route","vi":"kiểm tra lộ trình cập nhật"},{"en":"keep someone informed","vi":"cập nhật tình hình cho ai đó"},{"en":"an unexpected delay","vi":"sự chậm trễ ngoài dự kiến"},{"en":"allow extra travel time","vi":"dự trù thêm thời gian di chuyển"}],"grammar":"Dùng quá khứ đơn kể sự việc, past continuous mô tả việc đang diễn ra khi có thông báo.","sample":"A journey that took longer than I expected was a bus trip to a nearby coastal town. I travelled with a friend during a holiday weekend, when we thought leaving early would help us avoid crowds. About an hour into the trip, traffic stopped near a road construction site. We were moving only a few metres at a time, and the driver later explained that one lane had been closed. I checked an updated route on my phone and sent a message to the person meeting us. While we waited, my friend and I shared snacks and listened to a podcast. The bus eventually moved again, but we missed the time we had planned for lunch. I felt impatient at first because I had expected the trip to be simple. After a while, I accepted that the delay was beyond our control and focused on keeping the rest of the day flexible. We still enjoyed the visit and took a walk by the water before it got dark. Since then, I have tried to allow extra travel time on busy weekends and carry water or a book. The experience was inconvenient, but it taught me to plan with a little more room for surprises.","reviewed":false},"part3Questions":[{"id":"journey-delay-part3-01","type":"part3-question","part":3,"q":"What transport problems do people commonly face in large cities?","reviewed":false,"aid":{"idea":["Tắc nghẽn vào giờ cao điểm","Gián đoạn dịch vụ và thiếu kết nối giữa các tuyến"],"vocab":[{"en":"peak-hour congestion","vi":"tắc nghẽn giờ cao điểm"},{"en":"an overcrowded service","vi":"dịch vụ quá đông"},{"en":"a delayed connection","vi":"chuyến nối tiếp bị trễ"},{"en":"road maintenance work","vi":"việc bảo trì đường"},{"en":"unreliable arrival times","vi":"giờ đến không ổn định"},{"en":"a lack of route options","vi":"thiếu lựa chọn lộ trình"}],"grammar":"Dùng may face để nêu vấn đề thường gặp và especially when để chỉ hoàn cảnh.","sample":"People in large cities may face peak-hour congestion, overcrowded public transport and unreliable arrival times. Road maintenance or an accident can affect several routes at once. In some areas, passengers also have limited alternatives if one service is delayed. Better coordination between transport providers and clear real-time updates can help people adjust their journeys, even when the underlying problem cannot be removed immediately.","reviewed":false}},{"id":"journey-delay-part3-02","type":"part3-question","part":3,"q":"How can governments encourage people to use public transport?","reviewed":false,"aid":{"idea":["Tăng độ tin cậy, tần suất và kết nối tuyến","Làm việc đi lại dễ dự đoán và thuận tiện"],"vocab":[{"en":"frequent services","vi":"dịch vụ chạy thường xuyên"},{"en":"reliable schedules","vi":"lịch trình đáng tin cậy"},{"en":"connect residential areas","vi":"kết nối khu dân cư"},{"en":"integrated ticketing","vi":"hệ thống vé tích hợp"},{"en":"safe and clean stations","vi":"nhà ga an toàn và sạch sẽ"},{"en":"a practical alternative","vi":"lựa chọn thay thế thực tế"}],"grammar":"Dùng by improving + danh từ để nêu chính sách cụ thể và so that để giải thích kết quả.","sample":"Governments can encourage public transport by making services frequent, reliable and easy to connect. Clean, safe stations and simple ticketing reduce the small frustrations that discourage passengers. Routes should link residential areas with workplaces and essential services, so travelling without a car is a practical alternative. Fares matter too, but reliability is important because people need to trust that they will arrive on time.","reviewed":false}},{"id":"journey-delay-part3-03","type":"part3-question","part":3,"q":"What effects can tourism have on small communities?","reviewed":false,"aid":{"idea":["Du lịch tạo việc làm và hỗ trợ cửa hàng địa phương","Lượng khách lớn gây áp lực lên giao thông, nhà ở và môi trường"],"vocab":[{"en":"support local businesses","vi":"hỗ trợ doanh nghiệp địa phương"},{"en":"seasonal employment","vi":"việc làm theo mùa"},{"en":"put pressure on housing","vi":"gây áp lực lên nhà ở"},{"en":"protect local character","vi":"bảo vệ bản sắc địa phương"},{"en":"manage visitor numbers","vi":"quản lý số lượng khách"},{"en":"share the economic benefit","vi":"chia sẻ lợi ích kinh tế"}],"grammar":"Dùng while để nêu lợi ích và tác động trái chiều trong cùng lập luận.","sample":"Tourism can support local businesses and create seasonal jobs, especially where visitors buy food, crafts or accommodation. At the same time, a sudden increase in visitor numbers may put pressure on housing, transport and public spaces. Communities can benefit more if planning protects local character and shares economic gains fairly. The impact depends on how tourism is managed and whether residents have a voice in decisions.","reviewed":false}},{"id":"journey-delay-part3-04","type":"part3-question","part":3,"q":"How can travellers prepare for unexpected delays?","reviewed":false,"aid":{"idea":["Kiểm tra cập nhật và dự trù khoảng thời gian linh hoạt","Mang theo vật dụng cơ bản và thông tin liên lạc"],"vocab":[{"en":"check service alerts","vi":"kiểm tra thông báo dịch vụ"},{"en":"keep a backup route","vi":"chuẩn bị lộ trình dự phòng"},{"en":"carry essential items","vi":"mang theo vật dụng thiết yếu"},{"en":"share an estimated arrival","vi":"chia sẻ giờ đến dự kiến"},{"en":"build a time buffer","vi":"dự phòng khoảng thời gian"},{"en":"stay calm and flexible","vi":"giữ bình tĩnh và linh hoạt"}],"grammar":"Dùng before travelling để tổ chức lời khuyên thành bước chuẩn bị.","sample":"Before travelling, people can check service alerts, save a backup route and build a time buffer into important plans. Carrying water, a charger and necessary contact details is sensible for a longer trip. If a delay happens, sharing an updated arrival time helps others adjust. Preparation cannot prevent every disruption, but it can make the experience less stressful and help travellers stay flexible.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A journey with an unexpected delay"},{"id":"local-public-event","topic":"A public event you enjoyed","task":"Describe a public event that you enjoyed attending.","bullets":["what the event was","where and when it took place","what people could see or do","who you attended with"],"conclusion":"and explain what made the event enjoyable for you.","reviewed":false,"aid":{"idea":["Chọn hội sách, buổi biểu diễn hoặc sự kiện cộng đồng","Miêu tả một hoạt động bạn tham gia","Nêu điều khiến đám đông tạo cảm giác vui"],"vocab":[{"en":"an open-air performance","vi":"buổi biểu diễn ngoài trời"},{"en":"a local arts group","vi":"nhóm nghệ thuật địa phương"},{"en":"browse the stalls","vi":"xem các gian hàng"},{"en":"a lively crowd","vi":"đám đông sôi nổi"},{"en":"a well-organised programme","vi":"chương trình được tổ chức tốt"},{"en":"a shared experience","vi":"trải nghiệm chung"}],"grammar":"Dùng quá khứ đơn kể hoạt động và which made để nối chi tiết với cảm nhận.","sample":"A public event I enjoyed was a small open-air arts festival held in a central park last spring. I went with my cousin after seeing a notice at the library. Several local groups performed short music and dance pieces, and there were stalls selling handmade items and snacks. We arrived before sunset, so we had time to browse the stalls and find a place to sit. My favourite part was a performance that combined traditional instruments with a modern rhythm. The musicians explained where the melodies came from, which made the show more meaningful. The crowd was lively but not too large, and families could move around without blocking the paths. Between performances, my cousin and I tried a local dessert and talked to one of the artists about how she made her prints. The event felt well organised, with signs showing the programme and volunteers helping visitors find the different areas. I enjoyed it because it offered a shared experience without feeling formal. I also learned something about the local arts scene that I would not have discovered by staying at home. I would like to attend again if the festival returns next year.","reviewed":false},"part3Questions":[{"id":"local-public-event-part3-01","type":"part3-question","part":3,"q":"Why do cities organise public events?","reviewed":false,"aid":{"idea":["Tạo cơ hội giao lưu và giới thiệu văn hóa địa phương","Hỗ trợ nghệ sĩ, cửa hàng và hoạt động du lịch"],"vocab":[{"en":"bring residents together","vi":"kết nối cư dân"},{"en":"showcase local talent","vi":"giới thiệu tài năng địa phương"},{"en":"attract visitors","vi":"thu hút khách tham quan"},{"en":"create a lively atmosphere","vi":"tạo không khí sôi động"},{"en":"support cultural participation","vi":"hỗ trợ tham gia văn hóa"},{"en":"strengthen community identity","vi":"củng cố bản sắc cộng đồng"}],"grammar":"Dùng serve as a way to để trình bày nhiều mục đích của sự kiện.","sample":"Public events serve as a way to bring residents together and showcase local talent. Festivals can also attract visitors, support nearby businesses and create a lively atmosphere in public spaces. For residents, they provide an accessible chance to take part in cultural activities. The best events strengthen community identity while remaining welcoming to people who may not normally attend formal performances.","reviewed":false}},{"id":"local-public-event-part3-02","type":"part3-question","part":3,"q":"Should governments spend public money on arts and festivals?","reviewed":false,"aid":{"idea":["Sự kiện có thể đem lại lợi ích cộng đồng rộng","Ngân sách cần minh bạch và cân bằng với dịch vụ thiết yếu"],"vocab":[{"en":"public cultural funding","vi":"kinh phí văn hóa công"},{"en":"demonstrate community value","vi":"chứng minh giá trị cộng đồng"},{"en":"transparent budgeting","vi":"lập ngân sách minh bạch"},{"en":"accessible ticket prices","vi":"giá vé dễ tiếp cận"},{"en":"compete with essential services","vi":"cạnh tranh ngân sách dịch vụ thiết yếu"},{"en":"measure public benefit","vi":"đánh giá lợi ích công cộng"}],"grammar":"Dùng can be justified when để nêu điều kiện cho quyết định ngân sách.","sample":"Public cultural funding can be justified when an event is accessible and demonstrates community value. Arts programmes offer opportunities that may not be available through commercial entertainment alone. However, budgets must be transparent and balanced with essential services such as transport and health care. Officials should consider attendance, local participation and long-term impact rather than fund an event simply because it attracts publicity.","reviewed":false}},{"id":"local-public-event-part3-03","type":"part3-question","part":3,"q":"How can organisers make public events more accessible?","reviewed":false,"aid":{"idea":["Cung cấp thông tin di chuyển, giờ giấc và lối tiếp cận","Thiết kế giá vé cùng khu vực nghỉ phù hợp nhiều nhóm"],"vocab":[{"en":"step-free access","vi":"lối đi không bậc"},{"en":"clear travel information","vi":"thông tin đi lại rõ ràng"},{"en":"affordable admission","vi":"vé vào cửa hợp túi tiền"},{"en":"quiet rest areas","vi":"khu nghỉ yên tĩnh"},{"en":"accessible facilities","vi":"cơ sở vật chất dễ tiếp cận"},{"en":"plan for different needs","vi":"lên kế hoạch cho nhu cầu khác nhau"}],"grammar":"Dùng organisers can improve access by + V-ing để trình bày giải pháp cụ thể.","sample":"Organisers can improve access by providing step-free routes, clear travel information and affordable admission options. Quiet rest areas and accessible facilities can make an event more comfortable for visitors with different needs. They should ask community groups for feedback before finalising the layout. Accessibility is easier to build into the plan from the beginning than to add after people discover a barrier.","reviewed":false}},{"id":"local-public-event-part3-04","type":"part3-question","part":3,"q":"What role do local traditions play in modern festivals?","reviewed":false,"aid":{"idea":["Truyền thống tạo sự liên tục giữa thế hệ","Có thể kết hợp hình thức mới nhưng cần tôn trọng nguồn gốc"],"vocab":[{"en":"pass customs to younger people","vi":"truyền phong tục cho người trẻ"},{"en":"adapt an old tradition","vi":"điều chỉnh truyền thống cũ"},{"en":"preserve its meaning","vi":"giữ gìn ý nghĩa"},{"en":"a modern presentation","vi":"cách thể hiện hiện đại"},{"en":"learn the story behind","vi":"tìm hiểu câu chuyện phía sau"},{"en":"respect cultural origins","vi":"tôn trọng nguồn gốc văn hóa"}],"grammar":"Dùng can be adapted while still để nói truyền thống thay đổi nhưng vẫn giữ giá trị.","sample":"Local traditions can give a modern festival a connection to its history and community. They also create a way for older residents to pass customs to younger people. Organisers may adapt the music or presentation to attract new audiences, while still explaining the tradition's meaning. That balance matters: a festival can change with time without turning cultural elements into decoration with no context.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A community event"},{"id":"solved-a-practical-problem","topic":"A problem you solved","task":"Describe a practical problem that you solved.","bullets":["what the problem was","when it happened","what steps you took","who or what helped you"],"conclusion":"and explain what you learned from solving it.","reviewed":false,"aid":{"idea":["Chọn vấn đề vừa sức như sửa bài thuyết trình hoặc sắp lịch nhóm","Kể cách chia vấn đề thành bước nhỏ","Nêu kết quả và điều bạn làm tốt hơn lần sau"],"vocab":[{"en":"identify the main issue","vi":"xác định vấn đề chính"},{"en":"break it into steps","vi":"chia thành từng bước"},{"en":"ask for specific help","vi":"xin trợ giúp cụ thể"},{"en":"test a simple solution","vi":"thử giải pháp đơn giản"},{"en":"work against a deadline","vi":"làm việc với hạn chót"},{"en":"learn from the outcome","vi":"rút kinh nghiệm từ kết quả"}],"grammar":"Dùng first, then, finally để sắp xếp các bước và quá khứ đơn cho hành động đã hoàn tất.","sample":"A practical problem I solved happened while I was preparing a group presentation for class. Two days before the deadline, we discovered that the slides had different formats and some important information was missing. Everyone had edited a separate copy, so it was difficult to see which version was current. I suggested that we create one shared file and list the missing points before making more changes. First, we agreed on a simple design. Then each person checked one section against the notes from our research. I asked a classmate who knew the presentation software to help me fix the layout, while another group member checked the references. We set a short time limit for each task so the work would not expand unnecessarily. By the evening, the main content was complete and we had time to rehearse together. The final presentation was not perfect, but it was clear and consistent. I learned that we should decide how to share files at the start of a project, rather than wait until a problem appears. I also realised that asking for specific help is more useful than trying to manage every detail alone. Solving the issue felt satisfying because the group stayed calm and everyone contributed to the result.","reviewed":false},"part3Questions":[{"id":"solved-a-practical-problem-part3-01","type":"part3-question","part":3,"q":"Should children be taught problem-solving skills at school?","reviewed":false,"aid":{"idea":["Bài tập mở khuyến khích thử nhiều cách","Kỹ năng phân tích có ích ngoài lớp học"],"vocab":[{"en":"analyse a situation","vi":"phân tích tình huống"},{"en":"consider several options","vi":"cân nhắc nhiều lựa chọn"},{"en":"explain a decision","vi":"giải thích quyết định"},{"en":"learn from mistakes","vi":"học từ sai lầm"},{"en":"work through a challenge","vi":"xử lý thử thách từng bước"},{"en":"apply knowledge in practice","vi":"áp dụng kiến thức vào thực tế"}],"grammar":"Dùng should be taught through để giải thích cách tổ chức hoạt động học.","sample":"Children should be taught to analyse a situation, consider several options and explain why they chose one. Open-ended tasks let them practise these steps without requiring a single perfect answer. Learning from mistakes is also important, because real problems often need adjustment. These skills are useful beyond school, helping young people apply knowledge in practical decisions and cooperate with others.","reviewed":false}},{"id":"solved-a-practical-problem-part3-02","type":"part3-question","part":3,"q":"Is it better to solve difficult problems alone or with a team?","reviewed":false,"aid":{"idea":["Làm một mình nhanh khi vấn đề có phạm vi rõ","Nhóm có thêm góc nhìn nhưng cần phối hợp"],"vocab":[{"en":"a well-defined task","vi":"nhiệm vụ có phạm vi rõ"},{"en":"bring different perspectives","vi":"đưa ra góc nhìn khác nhau"},{"en":"divide the workload","vi":"chia khối lượng công việc"},{"en":"coordinate responsibilities","vi":"phối hợp trách nhiệm"},{"en":"reach a shared decision","vi":"đạt quyết định chung"},{"en":"match the method to the problem","vi":"chọn cách làm phù hợp vấn đề"}],"grammar":"Dùng whereas để so sánh và kết luận bằng the best method depends on.","sample":"Working alone can be efficient when a problem is well defined and one person has the necessary information. A team can bring different perspectives and divide the workload when the challenge is larger. The difficulty is coordinating responsibilities and reaching a shared decision. The best method depends on the problem, so people should choose a team only when collaboration adds value rather than complexity.","reviewed":false}},{"id":"solved-a-practical-problem-part3-03","type":"part3-question","part":3,"q":"How can digital tools help people solve everyday problems?","reviewed":false,"aid":{"idea":["Công cụ giúp tìm thông tin và phối hợp nhanh","Người dùng cần kiểm tra độ chính xác và bảo mật"],"vocab":[{"en":"compare available options","vi":"so sánh các lựa chọn"},{"en":"share information quickly","vi":"chia sẻ thông tin nhanh"},{"en":"automate a routine task","vi":"tự động hóa việc thường lệ"},{"en":"verify the information","vi":"xác minh thông tin"},{"en":"protect sensitive data","vi":"bảo vệ dữ liệu nhạy cảm"},{"en":"use the tool appropriately","vi":"dùng công cụ đúng mục đích"}],"grammar":"Dùng can help people + động từ và thêm provided that để nêu điều kiện sử dụng cẩn trọng.","sample":"Digital tools can help people find information, compare options and coordinate with others quickly. A map app may suggest another route, while a shared document can keep a team's notes in one place. Users still need to verify important information and protect sensitive data. Technology is most useful when people choose an appropriate tool and understand its limits instead of relying on every result automatically.","reviewed":false}},{"id":"solved-a-practical-problem-part3-04","type":"part3-question","part":3,"q":"Why do some people find it difficult to ask for help?","reviewed":false,"aid":{"idea":["Ngại bị xem là thiếu khả năng","Không biết cần hỏi ai hoặc chưa diễn đạt rõ vấn đề"],"vocab":[{"en":"feel embarrassed","vi":"cảm thấy ngượng"},{"en":"fear being judged","vi":"sợ bị đánh giá"},{"en":"describe the difficulty clearly","vi":"mô tả khó khăn rõ ràng"},{"en":"approach a trusted person","vi":"tìm đến người đáng tin"},{"en":"offer practical support","vi":"đưa ra hỗ trợ thiết thực"},{"en":"normalise asking questions","vi":"coi việc đặt câu hỏi là bình thường"}],"grammar":"Dùng may hesitate because để nêu lý do và managers can make it easier by để đưa giải pháp.","sample":"People may hesitate because they fear being judged or want to appear independent. Sometimes they are unsure who has the right knowledge, or they cannot describe the difficulty clearly. Schools and workplaces can make it easier by normalising questions and giving people a trusted contact. Asking for help can be a responsible step, especially when it prevents a small issue from becoming much harder to solve.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A problem I worked through"},{"id":"goal-i-worked-towards","topic":"A goal you worked towards","task":"Describe a goal that you worked hard to achieve.","bullets":["what the goal was","why it mattered to you","what steps you took","what was difficult along the way"],"conclusion":"and explain how you felt when you made progress or reached it.","reviewed":false,"aid":{"idea":["Chọn mục tiêu có bước thực hiện cụ thể","Nêu trở ngại và cách bạn điều chỉnh kế hoạch","Đánh giá điều bạn học được, kể cả khi mục tiêu còn tiếp diễn"],"vocab":[{"en":"set a clear milestone","vi":"đặt cột mốc rõ ràng"},{"en":"keep track of progress","vi":"theo dõi tiến độ"},{"en":"stay committed","vi":"duy trì cam kết"},{"en":"adjust my approach","vi":"điều chỉnh cách làm"},{"en":"a realistic timetable","vi":"thời gian biểu thực tế"},{"en":"feel a sense of achievement","vi":"cảm thấy đạt được thành tựu"}],"grammar":"Dùng quá khứ đơn kể các bước, then để nối trình tự và hiện tại đơn nói về bài học hiện tại.","sample":"A goal I worked hard towards was completing a long English presentation without reading every sentence from my notes. I wanted to speak more naturally in front of my class, but at first I lost my place whenever I felt nervous. I set a clear milestone: explain one section using only a few keywords. I practised at home, recorded short versions on my phone and listened for places where my ideas were unclear. A friend also asked me questions after each practice, which helped me prepare for interruptions. The hardest part was finding a realistic timetable around other assignments. I adjusted my approach by practising for ten minutes several times a week instead of waiting for one long session. On presentation day, I still felt nervous, but I managed to finish and answer two questions from the audience. I did not speak perfectly, yet I relied on my outline rather than reading a script. I felt a real sense of achievement because the result came from steady practice. The experience taught me to divide a large goal into manageable steps and keep track of progress. I still use that method whenever a task seems too demanding at the beginning.","reviewed":false},"part3Questions":[{"id":"goal-i-worked-towards-part3-01","type":"part3-question","part":3,"q":"Why is it useful for people to set personal goals?","reviewed":false,"aid":{"idea":["Mục tiêu giúp ưu tiên thời gian và công sức","Cột mốc nhỏ làm tiến bộ dễ nhận thấy"],"vocab":[{"en":"give direction to effort","vi":"định hướng nỗ lực"},{"en":"prioritise important tasks","vi":"ưu tiên nhiệm vụ quan trọng"},{"en":"measure small progress","vi":"đo lường tiến bộ nhỏ"},{"en":"stay motivated over time","vi":"duy trì động lực lâu dài"},{"en":"adjust a target","vi":"điều chỉnh mục tiêu"},{"en":"avoid unrealistic pressure","vi":"tránh áp lực không thực tế"}],"grammar":"Dùng can help people to để nêu lợi ích, kèm điều kiện mục tiêu cần vừa sức.","sample":"Personal goals can give direction to effort and help people decide which tasks deserve attention first. Smaller milestones make progress easier to notice, which can support motivation over time. Goals should remain flexible, though; someone may need to adjust a target when circumstances change. A realistic goal can provide structure without creating unnecessary pressure or making people feel that every delay is a failure.","reviewed":false}},{"id":"goal-i-worked-towards-part3-02","type":"part3-question","part":3,"q":"How can people stay motivated when progress is slow?","reviewed":false,"aid":{"idea":["Chia mục tiêu thành bước ngắn có thể hoàn thành","Theo dõi nỗ lực chứ không chỉ kết quả cuối"],"vocab":[{"en":"break a target down","vi":"chia nhỏ mục tiêu"},{"en":"celebrate a small win","vi":"ghi nhận thành công nhỏ"},{"en":"review what is working","vi":"xem lại điều gì đang hiệu quả"},{"en":"ask for encouragement","vi":"xin lời động viên"},{"en":"keep a progress record","vi":"ghi lại tiến độ"},{"en":"take a planned rest","vi":"nghỉ ngơi có kế hoạch"}],"grammar":"Dùng one way is to và another is to để đưa ra hai cách song song.","sample":"One way is to break a large target down and celebrate a small win at each stage. Keeping a progress record shows effort that may not be obvious from the final result. Another option is to review what is working and ask for encouragement from someone supportive. Rest also matters; a planned break can protect motivation better than pushing until a person becomes exhausted.","reviewed":false}},{"id":"goal-i-worked-towards-part3-03","type":"part3-question","part":3,"q":"Do people today feel more pressure to achieve than in the past?","reviewed":false,"aid":{"idea":["Mạng xã hội làm thành tựu của người khác dễ thấy","Áp lực còn phụ thuộc gia đình, nghề nghiệp và hoàn cảnh"],"vocab":[{"en":"compare themselves with others","vi":"so sánh bản thân với người khác"},{"en":"visible success stories","vi":"câu chuyện thành công dễ thấy"},{"en":"social expectations","vi":"kỳ vọng xã hội"},{"en":"career milestones","vi":"cột mốc nghề nghiệp"},{"en":"different life circumstances","vi":"hoàn cảnh sống khác nhau"},{"en":"define success personally","vi":"tự định nghĩa thành công"}],"grammar":"Dùng may feel more pressure, although để tránh kết luận tuyệt đối về mọi thế hệ.","sample":"Some people may feel more pressure because social media makes visible success stories easy to compare with everyday life. Career and educational milestones are also discussed widely. However, pressure has existed in different forms in the past, and it varies by family, community and economic circumstances. People can protect their well-being by defining success personally rather than treating another person's timeline as a universal standard.","reviewed":false}},{"id":"goal-i-worked-towards-part3-04","type":"part3-question","part":3,"q":"Can failure help someone achieve a long-term goal?","reviewed":false,"aid":{"idea":["Thất bại cung cấp thông tin về kế hoạch còn yếu","Cần xem xét nguyên nhân thay vì lặp lại cùng cách làm"],"vocab":[{"en":"learn from a setback","vi":"học từ trở ngại"},{"en":"identify a weak point","vi":"xác định điểm yếu"},{"en":"change the strategy","vi":"thay đổi chiến lược"},{"en":"try a revised approach","vi":"thử cách đã điều chỉnh"},{"en":"build resilience","vi":"xây dựng khả năng phục hồi"},{"en":"avoid repeating the same mistake","vi":"tránh lặp lại cùng sai lầm"}],"grammar":"Dùng can be useful if để nêu điều kiện giúp thất bại trở thành kinh nghiệm.","sample":"A setback can help if someone examines what caused it and changes the strategy. It may reveal that a timetable was unrealistic or that a skill needs more practice. Simply repeating the same approach is unlikely to improve the result. With useful feedback, people can try a revised plan and build resilience. Failure is not automatically valuable; reflection and action make the experience useful.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A goal that took steady effort"},{"id":"new-activity-i-tried","topic":"A new activity you tried","task":"Describe a new activity that you tried for the first time.","bullets":["what the activity was","when and where you tried it","who was with you","what you thought of it"],"conclusion":"and explain whether you would do it again.","reviewed":false,"aid":{"idea":["Chọn hoạt động mới như làm gốm, leo trong nhà hoặc lớp nhảy","Kể cảm giác ban đầu và điều bạn học","Nêu muốn tiếp tục hay thử lại vào dịp khác"],"vocab":[{"en":"step outside my comfort zone","vi":"bước ra khỏi vùng an toàn"},{"en":"learn the basic movements","vi":"học các động tác cơ bản"},{"en":"feel awkward at first","vi":"ban đầu cảm thấy vụng về"},{"en":"follow the instructor's guidance","vi":"làm theo hướng dẫn của giáo viên"},{"en":"get the hang of it","vi":"dần nắm được cách làm"},{"en":"give it another go","vi":"thử lại lần nữa"}],"grammar":"Dùng quá khứ đơn thuật lại buổi thử, rồi would like to để nêu ý định tương lai.","sample":"A new activity I tried was a beginner pottery class at a community studio. My friend invited me because she had already attended one session. I expected the class to be relaxing, but I quickly learned that shaping clay takes more control than it appears to. The instructor showed us how to centre the clay and keep our hands steady. At first, I felt awkward and made the sides of my small bowl uneven. Instead of fixing it for me, the instructor gave a simple tip and let me try again. After a few attempts, I began to get the hang of it. The room was quiet except for people asking questions and the wheel turning. I enjoyed seeing how everyone's pieces looked different, even though we followed the same steps. My bowl was not perfect, but I felt proud when it was ready to dry. The class helped me step outside my comfort zone and be patient with a process I could not control immediately. I would like to give it another go, perhaps with a longer session so I can learn how to glaze the finished piece. It was a hands-on experience that made an ordinary afternoon feel creative.","reviewed":false},"part3Questions":[{"id":"new-activity-i-tried-part3-01","type":"part3-question","part":3,"q":"Why is it important for adults to keep learning new things?","reviewed":false,"aid":{"idea":["Học mới giúp thích nghi với thay đổi công việc và đời sống","Hoạt động mới giữ trí tò mò và kết nối xã hội"],"vocab":[{"en":"adapt to change","vi":"thích nghi với thay đổi"},{"en":"keep the mind active","vi":"duy trì đầu óc linh hoạt"},{"en":"develop transferable skills","vi":"phát triển kỹ năng có thể áp dụng nhiều nơi"},{"en":"meet people with similar interests","vi":"gặp người có sở thích tương tự"},{"en":"stay curious","vi":"duy trì sự tò mò"},{"en":"gain a fresh perspective","vi":"có góc nhìn mới"}],"grammar":"Dùng even after để nhấn mạnh việc học tiếp tục ở nhiều giai đoạn cuộc đời.","sample":"Learning new things helps adults adapt to changes in work and daily life. It can also keep the mind active and provide a fresh perspective on familiar problems. A class or hobby may introduce people to others with similar interests, so the benefit is social as well. Adults do not need to pursue every new trend, but staying curious can make life more flexible and rewarding.","reviewed":false}},{"id":"new-activity-i-tried-part3-02","type":"part3-question","part":3,"q":"What makes people reluctant to try unfamiliar activities?","reviewed":false,"aid":{"idea":["Lo tốn tiền hoặc thiếu thời gian","Sợ làm sai trước người khác hoặc không biết bắt đầu từ đâu"],"vocab":[{"en":"worry about the cost","vi":"lo lắng về chi phí"},{"en":"feel out of place","vi":"cảm thấy lạc lõng"},{"en":"fear looking inexperienced","vi":"sợ trông thiếu kinh nghiệm"},{"en":"not know where to start","vi":"không biết bắt đầu từ đâu"},{"en":"a low-pressure introduction","vi":"buổi giới thiệu ít áp lực"},{"en":"try it with a friend","vi":"thử cùng một người bạn"}],"grammar":"Dùng may be put off by để nêu các rào cản thường gặp.","sample":"People may be put off by cost, lack of time or fear of looking inexperienced. They might also feel out of place if an activity seems designed for experts. A low-pressure introduction, clear information about equipment and the option to try it with a friend can reduce these concerns. Once people understand what to expect, they can decide whether the activity genuinely interests them.","reviewed":false}},{"id":"new-activity-i-tried-part3-03","type":"part3-question","part":3,"q":"Are hobbies better when people practise alone or in groups?","reviewed":false,"aid":{"idea":["Tập một mình linh hoạt và tự điều chỉnh tốc độ","Nhóm tạo động lực và cơ hội trao đổi"],"vocab":[{"en":"practise at my own pace","vi":"luyện theo nhịp riêng"},{"en":"exchange useful feedback","vi":"trao đổi góp ý hữu ích"},{"en":"stay accountable","vi":"duy trì trách nhiệm với kế hoạch"},{"en":"learn from peers","vi":"học từ người cùng nhóm"},{"en":"choose a quiet setting","vi":"chọn không gian yên tĩnh"},{"en":"depend on the activity","vi":"tùy thuộc hoạt động"}],"grammar":"Dùng it depends on the person and activity để mở kết luận cân bằng.","sample":"It depends on the person and the activity. Practising alone lets someone work at their own pace and choose a quiet setting. Group activities provide encouragement, peer feedback and a reason to keep attending. A person learning an instrument may want both individual practice and lessons, while a team sport naturally requires other people. The best arrangement is often the one that keeps enjoyment and progress balanced.","reviewed":false}},{"id":"new-activity-i-tried-part3-04","type":"part3-question","part":3,"q":"How can community centres attract more people to their classes?","reviewed":false,"aid":{"idea":["Lịch học linh hoạt và mô tả rõ trình độ phù hợp","Buổi trải nghiệm ngắn giúp người mới giảm e ngại"],"vocab":[{"en":"offer a trial session","vi":"mở buổi học thử"},{"en":"publish a clear schedule","vi":"công bố lịch rõ ràng"},{"en":"welcome complete beginners","vi":"chào đón người hoàn toàn mới"},{"en":"keep fees affordable","vi":"giữ học phí vừa phải"},{"en":"use local noticeboards","vi":"dùng bảng tin địa phương"},{"en":"ask participants for feedback","vi":"xin phản hồi từ người tham gia"}],"grammar":"Dùng could attract people by và liệt kê các hành động song song.","sample":"Community centres could attract more people by offering trial sessions and clearly stating which classes welcome complete beginners. Flexible schedules and affordable fees matter to people balancing work or family. Organisers can advertise through local noticeboards and neighbourhood groups, then ask participants what would make the class easier to attend. A welcoming first session is important because a friendly experience encourages people to return.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"Trying something unfamiliar"},{"id":"helped-someone","topic":"A time you helped someone","task":"Describe a time when you helped another person.","bullets":["who the person was","what they needed help with","what you did","how the person responded"],"conclusion":"and explain how you felt about helping them.","reviewed":false,"aid":{"idea":["Chọn lần hỗ trợ thiết thực như chỉ đường hoặc cùng ôn bài","Kể cách bạn hiểu nhu cầu trước khi giúp","Nêu kết quả với cảm xúc của cả hai"],"vocab":[{"en":"offer a helping hand","vi":"đưa tay giúp đỡ"},{"en":"listen to what they need","vi":"lắng nghe điều họ cần"},{"en":"work through a task","vi":"cùng xử lý một nhiệm vụ"},{"en":"give clear directions","vi":"chỉ dẫn rõ ràng"},{"en":"feel more confident","vi":"cảm thấy tự tin hơn"},{"en":"a small act of support","vi":"một hành động hỗ trợ nhỏ"}],"grammar":"Dùng quá khứ đơn cho hành động và so that để giải thích mục đích của sự giúp đỡ.","sample":"I remember helping a younger student prepare for a short class presentation. We met through a school club, and she told me she understood her topic but was nervous about speaking in front of the group. I listened first so I would not give advice she did not need. Then we organised her ideas into three clear points and practised the opening sentence several times. I also showed her how to use a small card with keywords rather than write a full script. During practice, I asked a few questions as if I were a listener, so she could get used to pausing and answering. At first she spoke very quietly, but after a few rounds she sounded more confident and looked up from her notes. Her presentation the next day went smoothly, and she later told me the practice had helped her feel prepared. I was pleased because the support was small and specific, yet it made a difference to her experience. I did not need to be an expert; I only needed to listen and help her organise what she already knew. That moment reminded me that practical encouragement can be more useful than simply telling someone not to worry.","reviewed":false},"part3Questions":[{"id":"helped-someone-part3-01","type":"part3-question","part":3,"q":"Why do people volunteer to help others?","reviewed":false,"aid":{"idea":["Muốn đóng góp cho cộng đồng hoặc đáp lại sự hỗ trợ","Hoạt động tình nguyện tạo kỹ năng và kết nối"],"vocab":[{"en":"contribute to the community","vi":"đóng góp cho cộng đồng"},{"en":"a shared responsibility","vi":"trách nhiệm chung"},{"en":"give time to a cause","vi":"dành thời gian cho một mục tiêu"},{"en":"build social connections","vi":"xây dựng kết nối xã hội"},{"en":"develop practical skills","vi":"phát triển kỹ năng thực tế"},{"en":"see a direct impact","vi":"thấy tác động trực tiếp"}],"grammar":"Dùng may volunteer because để nêu động lực đa dạng, tránh quy tất cả về một lý do.","sample":"People may volunteer because they care about a cause, want to contribute to their community or have received support themselves. Volunteering can also build social connections and practical skills. Seeing a direct impact often makes the work satisfying. Motivation varies, but organisations should make sure volunteers understand their roles and receive suitable support so the experience benefits both them and the people they serve.","reviewed":false}},{"id":"helped-someone-part3-02","type":"part3-question","part":3,"q":"Should people help others without expecting anything in return?","reviewed":false,"aid":{"idea":["Lòng tốt không nên chỉ dựa trên phần thưởng","Sự ghi nhận và hỗ trợ qua lại vẫn có ích"],"vocab":[{"en":"offer help sincerely","vi":"giúp đỡ chân thành"},{"en":"expect a direct reward","vi":"mong phần thưởng trực tiếp"},{"en":"recognise people's effort","vi":"ghi nhận nỗ lực của mọi người"},{"en":"mutual support","vi":"sự hỗ trợ qua lại"},{"en":"set healthy boundaries","vi":"đặt giới hạn lành mạnh"},{"en":"help when it is practical","vi":"giúp khi có thể làm được"}],"grammar":"Dùng ideally để nêu nguyên tắc, rồi although để công nhận giới hạn thực tế.","sample":"Ideally, people offer help sincerely rather than treating every kind act as a transaction. That can build trust and make communities more supportive. However, recognition matters, especially when someone gives a great deal of time, and people need healthy boundaries. It is reasonable to help when practical while also being clear about what support is possible. Generosity should be encouraged without making anyone feel exploited.","reviewed":false}},{"id":"helped-someone-part3-03","type":"part3-question","part":3,"q":"What can communities do to support people who feel isolated?","reviewed":false,"aid":{"idea":["Tổ chức hoạt động dễ tham gia và gần nơi ở","Kết nối cư dân với dịch vụ và nhóm hỗ trợ"],"vocab":[{"en":"a welcoming local group","vi":"nhóm địa phương thân thiện"},{"en":"low-cost activities","vi":"hoạt động chi phí thấp"},{"en":"make the first contact","vi":"chủ động liên hệ lần đầu"},{"en":"connect people with services","vi":"kết nối mọi người với dịch vụ"},{"en":"a regular social opportunity","vi":"cơ hội giao lưu đều đặn"},{"en":"reach out respectfully","vi":"chủ động tiếp cận một cách tôn trọng"}],"grammar":"Dùng communities can provide để nêu hỗ trợ và without pressuring them để nhấn cách tiếp cận phù hợp.","sample":"Communities can provide low-cost activities, welcoming local groups and places where people can meet regularly. A library or community centre might help someone make a first contact without requiring a large commitment. Local organisations can also connect residents with appropriate services. It is important to reach out respectfully, because isolated people may prefer different kinds of support and should not feel pressured to join every activity.","reviewed":false}},{"id":"helped-someone-part3-04","type":"part3-question","part":3,"q":"Can helping someone make the helper feel better too?","reviewed":false,"aid":{"idea":["Thấy được tác động có thể tạo cảm giác ý nghĩa","Cảm xúc không phải lúc nào cũng tích cực nếu việc giúp quá sức"],"vocab":[{"en":"feel useful and connected","vi":"cảm thấy có ích và gắn kết"},{"en":"a sense of purpose","vi":"cảm giác có mục tiêu"},{"en":"notice a positive change","vi":"nhận thấy thay đổi tích cực"},{"en":"emotional energy","vi":"năng lượng cảm xúc"},{"en":"avoid taking on too much","vi":"tránh nhận quá nhiều việc"},{"en":"keep support sustainable","vi":"duy trì sự hỗ trợ bền vững"}],"grammar":"Dùng can make the helper feel và thêm if để nêu điều kiện việc hỗ trợ lành mạnh.","sample":"Helping can make the helper feel useful, connected and more aware of other people's needs. Seeing a positive change may give a sense of purpose. At the same time, support takes emotional energy, and taking on too much can lead to stress. A sustainable approach includes clear limits and shared responsibility, so helping remains a positive relationship rather than a burden for one person.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A time I offered support"},{"id":"meaningful-photograph","topic":"A photograph that is important to you","task":"Describe a photograph that is important to you.","bullets":["what is shown in the photograph","when and where it was taken","who took it or kept it","why it is important to you"],"conclusion":"and explain how you feel when you look at it.","reviewed":false,"aid":{"idea":["Chọn ảnh nhóm bạn hoặc khoảnh khắc gia đình","Mô tả bối cảnh và điều xảy ra ngay trước lúc chụp","Nêu ký ức ảnh gợi lại"],"vocab":[{"en":"capture a candid moment","vi":"ghi lại khoảnh khắc tự nhiên"},{"en":"keep a digital copy","vi":"giữ bản sao kỹ thuật số"},{"en":"a familiar expression","vi":"nét mặt quen thuộc"},{"en":"bring back a memory","vi":"gợi lại kỷ niệm"},{"en":"look at it from time to time","vi":"thỉnh thoảng xem lại"},{"en":"a meaningful snapshot","vi":"bức ảnh chụp có ý nghĩa"}],"grammar":"Dùng mệnh đề quan hệ which để liên kết chi tiết trong ảnh với kỷ niệm mà nó gợi lại.","sample":"A photograph that is important to me shows my family sitting together in the courtyard of my grandparents' house. It was taken at a small gathering a few years ago, just before everyone went home. My cousin captured the moment while we were talking, so nobody was looking directly at the camera. I like the relaxed expressions and the ordinary details in the background, such as cups on the table and a plant my grandmother had grown. The photograph is stored on my phone, and I also have a printed copy in a notebook. Whenever I look at it, I remember how much conversation happened that afternoon and how my grandparents told stories about the neighbourhood. It brings back a feeling of being surrounded by people who know me well. The image is not professionally composed, but that is part of its appeal. It records a real moment rather than a planned pose. I look at it from time to time, especially when I am busy and have not visited for a while. The photograph reminds me to make room for family visits and small gatherings. I feel calm and grateful when I see it because it preserves a day that might otherwise have faded into an ordinary memory.","reviewed":false},"part3Questions":[{"id":"meaningful-photograph-part3-01","type":"part3-question","part":3,"q":"How has smartphone photography changed people's habits?","reviewed":false,"aid":{"idea":["Chụp ảnh thường xuyên và chia sẻ nhanh hơn","Số lượng lớn khiến người ta ít chọn lọc ảnh để lưu"],"vocab":[{"en":"take pictures instantly","vi":"chụp ảnh ngay lập tức"},{"en":"share an image online","vi":"chia sẻ ảnh trực tuyến"},{"en":"store thousands of photos","vi":"lưu hàng nghìn bức ảnh"},{"en":"capture everyday moments","vi":"ghi lại khoảnh khắc thường ngày"},{"en":"sort a photo collection","vi":"sắp xếp bộ sưu tập ảnh"},{"en":"be present in the moment","vi":"hiện diện trong khoảnh khắc"}],"grammar":"Dùng has made it easier to để nêu sự thay đổi và although để nói về mặt hạn chế.","sample":"Smartphones have made it easier to take pictures instantly and share them with people who are far away. As a result, photographs now record ordinary moments as well as major events. The large number of images can make it harder to organise or choose which ones to keep. People may also focus on taking pictures instead of being present, so balance matters.","reviewed":false}},{"id":"meaningful-photograph-part3-02","type":"part3-question","part":3,"q":"Do photographs preserve memories accurately?","reviewed":false,"aid":{"idea":["Ảnh giữ lại chi tiết hình ảnh nhưng chỉ ghi một khoảnh khắc","Cách nhớ và bối cảnh có thể thay đổi theo thời gian"],"vocab":[{"en":"freeze one moment","vi":"đóng băng một khoảnh khắc"},{"en":"leave out the context","vi":"bỏ sót bối cảnh"},{"en":"shape a personal memory","vi":"định hình ký ức cá nhân"},{"en":"remember an event differently","vi":"nhớ sự kiện theo cách khác"},{"en":"a visual record","vi":"bản ghi hình ảnh"},{"en":"interpret a scene","vi":"diễn giải một cảnh"}],"grammar":"Dùng can preserve some details, but để nêu cả khả năng và giới hạn của ảnh.","sample":"Photographs preserve visual details, such as who was present or what a place looked like. However, one image freezes a single moment and may leave out the context before or after it. People can also remember an event differently as time passes. A photograph is a useful record, but it does not provide a complete or neutral account of everything that happened.","reviewed":false}},{"id":"meaningful-photograph-part3-03","type":"part3-question","part":3,"q":"Should people ask permission before posting another person's photo online?","reviewed":false,"aid":{"idea":["Ảnh có thể tiết lộ danh tính hoặc vị trí","Xin phép thể hiện tôn trọng quyền riêng tư"],"vocab":[{"en":"ask for clear permission","vi":"xin phép rõ ràng"},{"en":"protect someone's privacy","vi":"bảo vệ quyền riêng tư"},{"en":"share without consent","vi":"chia sẻ khi chưa đồng ý"},{"en":"identify a location","vi":"xác định vị trí"},{"en":"remove an image on request","vi":"gỡ ảnh khi được yêu cầu"},{"en":"think about the audience","vi":"cân nhắc người xem"}],"grammar":"Dùng should ask before posting để nêu nguyên tắc, rồi giải thích bằng since.","sample":"People should usually ask before posting a photograph that clearly shows someone else. An image can reveal a person's identity, activities or location, so consent is part of respecting privacy. This is particularly important for children or sensitive situations. If someone changes their mind, removing the image is a reasonable response. Thinking about the audience and purpose before sharing can prevent avoidable harm.","reviewed":false}},{"id":"meaningful-photograph-part3-04","type":"part3-question","part":3,"q":"Are professional photographers still needed when phones have good cameras?","reviewed":false,"aid":{"idea":["Điện thoại tiện cho ảnh đời thường","Nhiếp ảnh gia chuyên nghiệp có kỹ thuật, thiết bị và khả năng chỉ đạo"],"vocab":[{"en":"convenient everyday photography","vi":"chụp ảnh thường ngày tiện lợi"},{"en":"control lighting conditions","vi":"kiểm soát điều kiện ánh sáng"},{"en":"direct a group portrait","vi":"chỉ đạo chụp ảnh nhóm"},{"en":"specialist equipment","vi":"thiết bị chuyên dụng"},{"en":"meet a client's needs","vi":"đáp ứng nhu cầu khách hàng"},{"en":"professional judgement","vi":"đánh giá chuyên môn"}],"grammar":"Dùng while để phân biệt ảnh chụp tiện lợi với công việc chuyên môn.","sample":"Phones are excellent for convenient everyday photography, but professional photographers still offer skills beyond operating a camera. They can control lighting, direct a group portrait and adapt to difficult conditions. Clients may also need reliable results for a wedding, product or publication. The choice depends on purpose: a quick personal picture is easy to take on a phone, while specialist work can benefit from professional judgement and equipment.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"An image linked to a memory"},{"id":"memorable-conversation","topic":"A conversation you remember","task":"Describe a conversation that you remember clearly.","bullets":["who you spoke with","where and when the conversation happened","what you talked about","why you remember it"],"conclusion":"and explain how the conversation affected you.","reviewed":false,"aid":{"idea":["Chọn cuộc trò chuyện giúp bạn hiểu một người hoặc quyết định","Nêu chủ đề mở đầu và lúc câu chuyện trở nên đáng nhớ","Kết nối điều bạn nghĩ khác đi sau đó"],"vocab":[{"en":"listen without interrupting","vi":"lắng nghe không ngắt lời"},{"en":"share an honest opinion","vi":"chia sẻ ý kiến chân thật"},{"en":"a thoughtful question","vi":"câu hỏi gợi suy nghĩ"},{"en":"see the situation differently","vi":"nhìn tình huống theo cách khác"},{"en":"a calm conversation","vi":"cuộc trò chuyện bình tĩnh"},{"en":"stay with me afterwards","vi":"còn đọng lại với tôi sau đó"}],"grammar":"Dùng quá khứ đơn kể cuộc nói chuyện và since then để nêu ảnh hưởng kéo dài.","sample":"A conversation I remember clearly was with my older cousin during a walk after dinner. I had been worrying about choosing between two study options and kept asking other people which one was better. My cousin listened without interrupting and then asked what kind of daily work I could imagine enjoying. That thoughtful question changed the direction of the conversation. We talked about my strengths, the subjects I liked and the practical differences between the programmes. My cousin did not tell me which option to choose. Instead, he shared how he had made a similar decision and explained that it was useful to consider both interest and realistic opportunities. I realised I had been focusing too much on what other people might approve of. The conversation was calm, and we did not need to reach a final answer that evening. Afterward, I wrote down a few questions to research and spoke with someone studying each subject. I remember the conversation because it helped me think independently rather than expect someone else to decide for me. Since then, I have tried to ask myself what matters before requesting advice. It was a simple discussion, but its effect stayed with me and made a stressful choice feel more manageable.","reviewed":false},"part3Questions":[{"id":"memorable-conversation-part3-01","type":"part3-question","part":3,"q":"What makes someone a good listener?","reviewed":false,"aid":{"idea":["Tập trung vào người nói và hỏi để làm rõ","Không vội phán xét hay đưa lời khuyên"],"vocab":[{"en":"give someone full attention","vi":"dành sự chú ý đầy đủ"},{"en":"ask a follow-up question","vi":"đặt câu hỏi tiếp nối"},{"en":"show genuine interest","vi":"thể hiện sự quan tâm chân thành"},{"en":"avoid jumping to conclusions","vi":"tránh vội đi đến kết luận"},{"en":"notice the speaker's feelings","vi":"nhận ra cảm xúc người nói"},{"en":"respond thoughtfully","vi":"phản hồi có suy nghĩ"}],"grammar":"Dùng rather than để phân biệt lắng nghe với việc lập tức đưa lời khuyên.","sample":"A good listener gives someone full attention and avoids checking a phone or planning a reply while the other person is speaking. Asking a thoughtful follow-up question shows genuine interest. It also helps to notice the speaker's feelings instead of judging immediately. Good listening does not always require advice; sometimes a calm response and a chance to explain are more useful.","reviewed":false}},{"id":"memorable-conversation-part3-02","type":"part3-question","part":3,"q":"Do people communicate differently online and face to face?","reviewed":false,"aid":{"idea":["Tin nhắn cho thời gian suy nghĩ nhưng thiếu sắc thái","Gặp trực tiếp giúp nhận ra ngôn ngữ cơ thể"],"vocab":[{"en":"read facial expressions","vi":"đọc nét mặt"},{"en":"choose words carefully","vi":"chọn từ ngữ cẩn thận"},{"en":"miss a subtle tone","vi":"bỏ lỡ sắc thái tinh tế"},{"en":"reply at a convenient time","vi":"trả lời vào lúc thuận tiện"},{"en":"a real-time exchange","vi":"cuộc trao đổi tức thời"},{"en":"avoid misunderstandings","vi":"tránh hiểu lầm"}],"grammar":"Dùng whereas để đối chiếu tin nhắn với cuộc trao đổi trực tiếp.","sample":"Online messages give people time to choose words and reply at a convenient time. However, it can be difficult to read tone or facial expressions, which may lead to misunderstandings. Face-to-face communication offers a real-time exchange and more non-verbal information, but it requires people to be available at the same moment. Many people choose the channel based on the topic and urgency.","reviewed":false}},{"id":"memorable-conversation-part3-03","type":"part3-question","part":3,"q":"How can people handle disagreements in a conversation?","reviewed":false,"aid":{"idea":["Tập trung vào vấn đề thay vì công kích cá nhân","Tóm tắt quan điểm đối phương trước khi phản hồi"],"vocab":[{"en":"keep a respectful tone","vi":"giữ giọng điệu tôn trọng"},{"en":"focus on the issue","vi":"tập trung vào vấn đề"},{"en":"acknowledge another viewpoint","vi":"ghi nhận góc nhìn khác"},{"en":"ask for clarification","vi":"xin làm rõ"},{"en":"find common ground","vi":"tìm điểm chung"},{"en":"pause before responding","vi":"dừng lại trước khi phản hồi"}],"grammar":"Dùng instead of + V-ing để khuyên tập trung nội dung thay vì công kích người nói.","sample":"People can handle disagreement better by keeping a respectful tone and asking for clarification before responding. It helps to summarise the other person's point, so they know it has been heard. Focusing on the issue instead of attacking someone's character makes a solution more likely. If emotions rise, a short pause can give both people time to think and find common ground.","reviewed":false}},{"id":"memorable-conversation-part3-04","type":"part3-question","part":3,"q":"Are conversations between older and younger people valuable?","reviewed":false,"aid":{"idea":["Hai thế hệ chia sẻ kinh nghiệm và cách nhìn mới","Cần tôn trọng khác biệt về hoàn cảnh và công nghệ"],"vocab":[{"en":"exchange life experience","vi":"trao đổi kinh nghiệm sống"},{"en":"understand another generation","vi":"hiểu một thế hệ khác"},{"en":"challenge an assumption","vi":"thách thức một giả định"},{"en":"share practical knowledge","vi":"chia sẻ kiến thức thực tế"},{"en":"respect different backgrounds","vi":"tôn trọng nền tảng khác nhau"},{"en":"learn from each other","vi":"học hỏi lẫn nhau"}],"grammar":"Dùng both generations can để nhấn mạnh sự học hỏi hai chiều.","sample":"Conversations between generations can help people exchange experience and understand how daily life has changed. Older people may share practical knowledge, while younger people can introduce new perspectives or technology. Both generations can challenge assumptions, provided that they respect different backgrounds. These conversations are most valuable when people ask questions with curiosity rather than assume that one age group has all the answers.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A conversation that changed my view"},{"id":"purchase-i-am-considering","topic":"Something you would like to buy","task":"Describe something that you would like to buy in the future.","bullets":["what you would like to buy","why you want it","how you would save or pay for it","how you would use it"],"conclusion":"and explain why you have not bought it yet.","reviewed":false,"aid":{"idea":["Chọn món đồ thực dụng bạn đang cân nhắc","Nêu cách bạn so sánh giá và tính năng","Giải thích vì sao sẽ chờ trước khi mua"],"vocab":[{"en":"save up for a purchase","vi":"tiết kiệm để mua món đồ"},{"en":"compare different models","vi":"so sánh các mẫu khác nhau"},{"en":"a dependable bicycle","vi":"chiếc xe đạp đáng tin cậy"},{"en":"make the daily commute easier","vi":"giúp việc đi lại hằng ngày dễ hơn"},{"en":"set a spending limit","vi":"đặt giới hạn chi tiêu"},{"en":"buy only when I need it","vi":"chỉ mua khi thực sự cần"}],"grammar":"Dùng would like to cho dự định, câu điều kiện để nêu cách tiết kiệm và hiện tại đơn giải thích vì sao chờ.","sample":"Something I would like to buy is a dependable bicycle for short trips around my area. At the moment, I usually take a bus or ask a family member for a ride, even when the destination is not very far. A bicycle would make my daily commute easier and give me more flexibility. I have not chosen a model yet because I want to compare safety features, frame size and repair costs rather than buy the first one I see. I am setting a spending limit and putting aside a small amount each month. If I find a good second-hand bicycle in safe condition, I would consider that as well. I would use it for local errands and perhaps ride to a nearby park at weekends. Before buying, I would check that there is a secure place to store it and that the main routes are suitable for cycling. I do not want to spend money on something that will be inconvenient to use. The purchase is not urgent, so waiting gives me time to make a practical choice. I think it would be useful for several years and might encourage me to be more active, but I will buy it only when the cost and safety both make sense.","reviewed":false},"part3Questions":[{"id":"purchase-i-am-considering-part3-01","type":"part3-question","part":3,"q":"What influences people's decisions when they buy expensive items?","reviewed":false,"aid":{"idea":["Giá cả, độ bền và nhu cầu sử dụng","Đánh giá, bảo hành và tư vấn từ người đáng tin"],"vocab":[{"en":"compare the total cost","vi":"so sánh tổng chi phí"},{"en":"check the warranty","vi":"kiểm tra bảo hành"},{"en":"read independent reviews","vi":"đọc đánh giá độc lập"},{"en":"consider long-term use","vi":"cân nhắc sử dụng lâu dài"},{"en":"seek trusted advice","vi":"tìm lời khuyên đáng tin"},{"en":"avoid an impulse purchase","vi":"tránh mua bốc đồng"}],"grammar":"Dùng often depend on và liệt kê yếu tố bằng along with.","sample":"Expensive purchases often depend on price, durability and how frequently a person will use the item. Buyers may compare the total cost, read independent reviews and check the warranty. Advice from a trusted person can help, although individual needs differ. Taking time to compare options reduces impulse decisions and makes it more likely that the product will remain useful after the excitement of buying has passed.","reviewed":false}},{"id":"purchase-i-am-considering-part3-02","type":"part3-question","part":3,"q":"How can cities make cycling safer and more attractive?","reviewed":false,"aid":{"idea":["Làn xe đạp liên tục và giao lộ an toàn","Bãi đỗ chắc chắn cùng kết nối giao thông công cộng"],"vocab":[{"en":"protected cycle lanes","vi":"làn xe đạp có bảo vệ"},{"en":"safe road crossings","vi":"điểm qua đường an toàn"},{"en":"secure bicycle parking","vi":"bãi đỗ xe đạp an toàn"},{"en":"connect to public transport","vi":"kết nối với giao thông công cộng"},{"en":"maintain road surfaces","vi":"bảo trì mặt đường"},{"en":"encourage short trips","vi":"khuyến khích chuyến đi ngắn"}],"grammar":"Dùng cities can encourage cycling by để nêu biện pháp cụ thể.","sample":"Cities can encourage cycling by building protected lanes that connect useful destinations instead of stopping suddenly at busy roads. Safe crossings and secure bicycle parking also matter. If cyclists can combine a ride with public transport, longer journeys become more practical. Regular maintenance is important too, because broken surfaces can make a route unsafe. These changes may encourage people to use bicycles for short everyday trips.","reviewed":false}},{"id":"purchase-i-am-considering-part3-03","type":"part3-question","part":3,"q":"Is it important for consumers to save money before buying something?","reviewed":false,"aid":{"idea":["Tiết kiệm giảm áp lực vay và khuyến khích cân nhắc","Một số vật dụng thiết yếu có thể cần mua ngay"],"vocab":[{"en":"plan a monthly budget","vi":"lập ngân sách hằng tháng"},{"en":"avoid unnecessary debt","vi":"tránh nợ không cần thiết"},{"en":"save gradually","vi":"tiết kiệm dần dần"},{"en":"cover an essential need","vi":"đáp ứng nhu cầu thiết yếu"},{"en":"weigh the urgency","vi":"cân nhắc mức độ cấp thiết"},{"en":"make a planned purchase","vi":"mua theo kế hoạch"}],"grammar":"Dùng it is sensible to save when để nêu nguyên tắc và ngoại lệ.","sample":"Saving before a purchase is sensible when an item is expensive or not urgently needed. It helps people plan a budget and avoid unnecessary debt. However, essential needs such as a broken refrigerator may require a quicker decision, depending on a person's circumstances. The key is to weigh urgency against cost and make a planned purchase where possible, rather than spend impulsively under pressure.","reviewed":false}},{"id":"purchase-i-am-considering-part3-04","type":"part3-question","part":3,"q":"How can people reduce the environmental impact of what they buy?","reviewed":false,"aid":{"idea":["Mua món bền, sửa được và thật sự cần","Cân nhắc đồ cũ, bao bì và khả năng tái sử dụng"],"vocab":[{"en":"choose a durable product","vi":"chọn sản phẩm bền"},{"en":"repair before replacing","vi":"sửa trước khi thay"},{"en":"buy second-hand","vi":"mua đồ đã qua sử dụng"},{"en":"avoid excess packaging","vi":"tránh bao bì dư thừa"},{"en":"reuse an item","vi":"dùng lại một món đồ"},{"en":"consider the product's lifespan","vi":"cân nhắc tuổi thọ sản phẩm"}],"grammar":"Dùng by choosing và by repairing để liệt kê hành động giảm tác động.","sample":"Consumers can reduce their impact by choosing durable goods and repairing them before replacement. Buying second-hand is another option when an item is still safe and useful. People can also avoid excess packaging and reuse products for as long as practical. These choices do not remove every environmental cost, but considering a product's lifespan can help people buy less often and waste fewer materials.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A practical purchase"},{"id":"useful-rule","topic":"A rule that is useful","task":"Describe a rule that you think is useful.","bullets":["what the rule is","where people are expected to follow it","why the rule exists","how it affects people's behaviour"],"conclusion":"and explain whether you think the rule should stay in place.","reviewed":false,"aid":{"idea":["Chọn quy định giữ nơi chung sạch hoặc yên tĩnh","Mô tả lợi ích cho nhiều người","Nêu cách nhắc nhở công bằng thay vì chỉ phạt"],"vocab":[{"en":"keep shared areas tidy","vi":"giữ khu vực chung ngăn nắp"},{"en":"respect other people's space","vi":"tôn trọng không gian người khác"},{"en":"a reasonable expectation","vi":"kỳ vọng hợp lý"},{"en":"apply the rule consistently","vi":"áp dụng quy định nhất quán"},{"en":"prevent avoidable conflict","vi":"ngăn xung đột có thể tránh"},{"en":"review it from time to time","vi":"xem xét lại định kỳ"}],"grammar":"Dùng the rule requires people to để nêu nội dung, sau đó because để giải thích mục đích.","sample":"A useful rule at my local library is that visitors should keep conversations quiet in the study area. The library also has a separate space where people can talk in a normal voice. I think the rule is reasonable because students, readers and people working online need different levels of concentration. A sign explains the quiet area near the entrance, so visitors know what to expect before they sit down. Most people follow it without being reminded. If someone forgets, a staff member usually gives a polite request rather than immediately treating the situation as a serious offence. This approach keeps the space comfortable and prevents avoidable conflict. I have used the library to prepare for exams, and the quiet atmosphere helped me finish tasks more efficiently. The rule also shows respect for people who may have travelled there specifically to study. It should stay in place, but the library needs to make sure the quiet zone is clearly separated from the social area. Rules work better when they are understandable and applied consistently. In this case, one simple expectation allows many people to share the same building for different purposes, and that is why I consider it useful.","reviewed":false},"part3Questions":[{"id":"useful-rule-part3-01","type":"part3-question","part":3,"q":"Why do communities need rules?","reviewed":false,"aid":{"idea":["Quy định giúp mọi người biết giới hạn và trách nhiệm","Quy tắc chung giảm tranh chấp khi nhu cầu va chạm"],"vocab":[{"en":"set clear expectations","vi":"đặt kỳ vọng rõ ràng"},{"en":"protect public safety","vi":"bảo vệ an toàn công cộng"},{"en":"balance competing needs","vi":"cân bằng nhu cầu xung đột"},{"en":"reduce avoidable disputes","vi":"giảm tranh chấp có thể tránh"},{"en":"understand shared responsibilities","vi":"hiểu trách nhiệm chung"},{"en":"apply to everyone fairly","vi":"áp dụng công bằng với mọi người"}],"grammar":"Dùng help people to và so that để nối quy tắc với lợi ích cộng đồng.","sample":"Communities need rules to set clear expectations and protect public safety. Shared spaces involve people with different needs, so agreed limits can reduce avoidable disputes. Rules are more likely to be accepted when they apply fairly and are explained in plain language. They should also be reviewed when circumstances change, because a rule that once solved a problem may later create unnecessary barriers.","reviewed":false}},{"id":"useful-rule-part3-02","type":"part3-question","part":3,"q":"How should schools respond when students break a rule?","reviewed":false,"aid":{"idea":["Tìm hiểu lý do và mức độ ảnh hưởng","Dùng hậu quả có tính giáo dục và nhất quán"],"vocab":[{"en":"understand the circumstances","vi":"hiểu hoàn cảnh"},{"en":"explain the expected behaviour","vi":"giải thích hành vi được mong đợi"},{"en":"a proportionate consequence","vi":"hậu quả tương xứng"},{"en":"repair any harm","vi":"khắc phục tổn hại"},{"en":"apply expectations consistently","vi":"áp dụng kỳ vọng nhất quán"},{"en":"support better choices","vi":"hỗ trợ lựa chọn tốt hơn"}],"grammar":"Dùng should consider before deciding để nhấn mạnh cần tìm hiểu trước khi xử lý.","sample":"Schools should first understand the circumstances and explain which behaviour caused a problem. A proportionate consequence can help students recognise the impact and repair any harm. Expectations should be consistent, while staff consider whether a student needs additional support. Punishment alone may stop an action briefly, but guidance is more likely to help young people make better choices in future situations.","reviewed":false}},{"id":"useful-rule-part3-03","type":"part3-question","part":3,"q":"Do laws always change people's behaviour?","reviewed":false,"aid":{"idea":["Luật có thể răn đe và thiết lập chuẩn chung","Giáo dục, khả năng thực thi và thái độ xã hội cũng ảnh hưởng"],"vocab":[{"en":"create a legal boundary","vi":"tạo ranh giới pháp lý"},{"en":"discourage harmful conduct","vi":"ngăn hành vi gây hại"},{"en":"enforce a regulation","vi":"thực thi quy định"},{"en":"understand the reason behind","vi":"hiểu lý do phía sau"},{"en":"change a social norm","vi":"thay đổi chuẩn mực xã hội"},{"en":"compliance over time","vi":"việc tuân thủ theo thời gian"}],"grammar":"Dùng may influence nhưng not always để hạn chế khái quát; then nêu các yếu tố bổ sung.","sample":"Laws may influence behaviour by creating a boundary and discouraging harmful actions, but they do not always change attitudes immediately. People are more likely to comply when regulations are understandable, consistently enforced and supported by public education. Social norms also matter. A lasting change often requires several approaches, because a legal rule alone may not address the reasons people behave in a particular way.","reviewed":false}},{"id":"useful-rule-part3-04","type":"part3-question","part":3,"q":"When should a rule be reviewed or changed?","reviewed":false,"aid":{"idea":["Khi mục đích ban đầu không còn hoặc tác động trở nên bất công","Lấy ý kiến người chịu ảnh hưởng và xem dữ liệu"],"vocab":[{"en":"assess the original purpose","vi":"đánh giá mục đích ban đầu"},{"en":"collect feedback from users","vi":"thu thập phản hồi từ người sử dụng"},{"en":"produce an unfair outcome","vi":"tạo ra kết quả bất công"},{"en":"check current evidence","vi":"kiểm tra bằng chứng hiện tại"},{"en":"update the wording","vi":"cập nhật cách diễn đạt"},{"en":"keep the rule practical","vi":"giữ quy định thiết thực"}],"grammar":"Dùng when evidence shows that để nêu điều kiện cần rà soát quy định.","sample":"A rule should be reviewed when its original purpose is no longer clear or evidence shows that it creates an unfair outcome. Authorities can collect feedback from the people affected and check whether the rule is still practical. Sometimes the wording needs clarification rather than complete removal. Regular review helps rules respond to new circumstances while preserving the protection or benefit they were designed to provide.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A rule that helps people share space"},{"id":"peaceful-place","topic":"A peaceful place you like","task":"Describe a place where you can relax and feel peaceful.","bullets":["where the place is","how you found it","what it is like","what you do there"],"conclusion":"and explain why the place helps you feel peaceful.","reviewed":false,"aid":{"idea":["Chọn vườn thực vật hoặc khu ven hồ ít đông","Miêu tả âm thanh, ánh sáng và lối đi","Kể hoạt động giúp bạn chậm lại"],"vocab":[{"en":"a botanical garden","vi":"vườn thực vật"},{"en":"a quiet path","vi":"lối đi yên tĩnh"},{"en":"listen to the water","vi":"lắng nghe tiếng nước"},{"en":"take a slow walk","vi":"đi bộ thong thả"},{"en":"step away from traffic","vi":"tạm rời xa giao thông"},{"en":"clear my head","vi":"làm đầu óc thư thái"}],"grammar":"Dùng hiện tại đơn mô tả nơi và hoạt động thường làm; thêm which makes để giải thích cảm giác.","sample":"A peaceful place I like is a botanical garden on the edge of my city. I found it when a friend suggested somewhere quiet to walk after a busy week. The garden has several shaded paths, a small pond and signs that identify different plants. It is usually calmer on weekday mornings, when there are fewer visitors and the sounds of traffic are distant. I like walking slowly around the pond and stopping to read the signs. Sometimes I sit on a bench and listen to the water moving through a narrow channel. The place does not have dramatic scenery, but it feels carefully looked after and gives me space to think without being interrupted. I leave my phone in my bag for a while, which makes the visit feel like a real break. The garden helps me clear my head because I can focus on small details rather than a long list of tasks. I usually stay for less than an hour, so it is easy to include in an ordinary day. I value this place because it is open to the public and offers a calm alternative to busy shopping streets. If I have visitors from out of town, I would take them there for a gentle walk and a quiet conversation.","reviewed":false},"part3Questions":[{"id":"peaceful-place-part3-01","type":"part3-question","part":3,"q":"Why are green spaces valuable in cities?","reviewed":false,"aid":{"idea":["Cây xanh tạo nơi nghỉ và vận động","Không gian công cộng xanh hỗ trợ sức khỏe và kết nối"],"vocab":[{"en":"provide a place to unwind","vi":"tạo nơi thư giãn"},{"en":"improve urban air quality","vi":"cải thiện chất lượng không khí đô thị"},{"en":"encourage outdoor activity","vi":"khuyến khích hoạt động ngoài trời"},{"en":"support local wildlife","vi":"hỗ trợ động vật địa phương"},{"en":"offer shade in hot weather","vi":"tạo bóng mát khi trời nóng"},{"en":"make a neighbourhood more liveable","vi":"làm khu dân cư đáng sống hơn"}],"grammar":"Dùng can provide và can also để nêu các lợi ích bổ sung.","sample":"Green spaces provide a place to unwind, exercise and meet neighbours without needing to buy anything. Trees offer shade and can support local wildlife, while parks may improve the feel of a dense neighbourhood. Their value depends on access and maintenance; a locked or neglected park serves fewer people. Well-planned green areas can make a city healthier and more liveable.","reviewed":false}},{"id":"peaceful-place-part3-02","type":"part3-question","part":3,"q":"How can city planners reduce noise in residential areas?","reviewed":false,"aid":{"idea":["Điều tiết giờ hoạt động gây tiếng ồn","Tạo vùng cây xanh và thiết kế đường giảm tốc"],"vocab":[{"en":"set reasonable quiet hours","vi":"đặt giờ yên tĩnh hợp lý"},{"en":"manage construction noise","vi":"quản lý tiếng ồn xây dựng"},{"en":"slow traffic down","vi":"giảm tốc độ giao thông"},{"en":"install sound barriers","vi":"lắp vách chắn âm"},{"en":"create green buffers","vi":"tạo dải cây xanh đệm"},{"en":"consult local residents","vi":"tham khảo cư dân địa phương"}],"grammar":"Dùng planners could combine để nêu nhiều giải pháp phối hợp thay vì một biện pháp đơn lẻ.","sample":"Planners could combine reasonable construction hours with measures that reduce traffic noise. Slower streets, sound barriers and green buffers can make busy roads less disruptive. Residents should be consulted because noise sources differ between neighbourhoods. Planting mature trees can help, although benefits take time to appear. Rules need to protect rest without preventing essential work or normal community activity, so enforcement should focus on repeated and avoidable disturbance.","reviewed":false}},{"id":"peaceful-place-part3-03","type":"part3-question","part":3,"q":"Should access to parks and gardens be free?","reviewed":false,"aid":{"idea":["Không gian công cộng miễn phí tăng khả năng tiếp cận","Phí nhỏ có thể hỗ trợ khu vườn chuyên biệt nếu có miễn giảm"],"vocab":[{"en":"open to the public","vi":"mở cửa cho công chúng"},{"en":"remove a financial barrier","vi":"xóa rào cản tài chính"},{"en":"fund regular maintenance","vi":"tài trợ bảo trì thường xuyên"},{"en":"offer reduced admission","vi":"cung cấp vé giảm giá"},{"en":"a specialised attraction","vi":"điểm tham quan chuyên biệt"},{"en":"protect equal access","vi":"bảo vệ khả năng tiếp cận bình đẳng"}],"grammar":"Dùng should generally be free rồi phân biệt với một số khu chuyên biệt bằng while.","sample":"Public parks should generally be free because they provide shared space for exercise and rest, regardless of income. A specialised botanical garden may charge a small fee to support maintenance, but reduced admission or free community days can protect access. The important point is that people should have nearby green space that does not require payment for ordinary use by everyone.","reviewed":false}},{"id":"peaceful-place-part3-04","type":"part3-question","part":3,"q":"How can communities protect natural places while welcoming visitors?","reviewed":false,"aid":{"idea":["Giới hạn khách ở khu vực nhạy cảm","Dùng lối đi, biển hướng dẫn và giáo dục môi trường"],"vocab":[{"en":"protect sensitive habitats","vi":"bảo vệ môi trường sống nhạy cảm"},{"en":"mark designated paths","vi":"đánh dấu lối đi quy định"},{"en":"limit visitor numbers","vi":"giới hạn số khách"},{"en":"explain local guidelines","vi":"giải thích quy định địa phương"},{"en":"monitor the environmental impact","vi":"theo dõi tác động môi trường"},{"en":"balance conservation with access","vi":"cân bằng bảo tồn với tiếp cận"}],"grammar":"Dùng can welcome visitors while protecting để cân bằng hai mục tiêu.","sample":"Communities can welcome visitors while protecting sensitive habitats through marked paths, clear guidance and limits in fragile areas. Local signs can explain why certain rules matter rather than list prohibitions alone. Monitoring visitor numbers and environmental impact helps managers adjust their approach. Conservation and access can coexist when people understand how to enjoy a place without damaging the plants, wildlife or facilities that make it valuable.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"Somewhere I go to slow down"},{"id":"technology-that-saves-time","topic":"A piece of technology that saves time","task":"Describe a piece of technology that saves you time.","bullets":["what the technology is","when you started using it","what you use it for","how it saves time"],"conclusion":"and explain whether you could manage without it.","reviewed":false,"aid":{"idea":["Chọn thiết bị dùng để tập trung hoặc xử lý công việc thường ngày","Nêu tình huống trước và sau khi có thiết bị","Cân nhắc lợi ích với thời gian dùng màn hình"],"vocab":[{"en":"noise-cancelling headphones","vi":"tai nghe chống ồn"},{"en":"block out background noise","vi":"chặn tiếng ồn xung quanh"},{"en":"switch between devices","vi":"chuyển giữa các thiết bị"},{"en":"focus on a task","vi":"tập trung vào nhiệm vụ"},{"en":"save repeated effort","vi":"tiết kiệm công sức lặp lại"},{"en":"use it in moderation","vi":"sử dụng ở mức vừa phải"}],"grammar":"Dùng present perfect kể từ khi bắt đầu sử dụng, rồi hiện tại đơn mô tả lợi ích thường xuyên.","sample":"A piece of technology that saves me time is a pair of noise-cancelling headphones. I started using them when I began studying more often in shared spaces. Before that, I sometimes had to move seats or wait for a quiet moment whenever people were talking nearby. Now I can block out much of the background noise and focus on reading or listening practice. The headphones connect to my phone and laptop, so I can switch between devices without setting everything up again. I also use them on public transport, which makes it easier to listen to a lesson while travelling. They do not remove every sound, and I keep the volume at a comfortable level. I would not wear them constantly because I still need to notice announcements and people around me. The main benefit is that I can start a task sooner instead of spending time searching for a perfectly quiet place. I could manage without them, but I would probably need more breaks or a different study location. They are a convenience rather than a necessity, and I try to use them in moderation. Overall, they help me protect focused time in a busy environment and make short study sessions more productive.","reviewed":false},"part3Questions":[{"id":"technology-that-saves-time-part3-01","type":"part3-question","part":3,"q":"How has technology changed the way people work?","reviewed":false,"aid":{"idea":["Công cụ số tăng tốc trao đổi và xử lý dữ liệu","Làm việc từ xa tạo linh hoạt nhưng có thể kéo dài giờ trực tuyến"],"vocab":[{"en":"automate routine tasks","vi":"tự động hóa công việc thường lệ"},{"en":"collaborate remotely","vi":"hợp tác từ xa"},{"en":"share information quickly","vi":"chia sẻ thông tin nhanh"},{"en":"stay connected after hours","vi":"giữ kết nối ngoài giờ"},{"en":"adapt to new tools","vi":"thích nghi với công cụ mới"},{"en":"set clear boundaries","vi":"đặt giới hạn rõ ràng"}],"grammar":"Dùng while để nêu lợi ích và thách thức của công nghệ tại nơi làm việc.","sample":"Technology has made it easier to automate routine tasks, share information and collaborate with colleagues in different locations. Remote tools can give workers more flexibility. However, being constantly connected may make it harder to separate work from personal time. Employers need to provide training and set clear boundaries, so technology supports productivity without creating an expectation that staff respond at every hour.","reviewed":false}},{"id":"technology-that-saves-time-part3-02","type":"part3-question","part":3,"q":"Can technology make people less independent?","reviewed":false,"aid":{"idea":["Dựa quá nhiều vào gợi ý có thể làm giảm thực hành kỹ năng","Công cụ cũng mở rộng khả năng tự giải quyết vấn đề"],"vocab":[{"en":"rely on automated suggestions","vi":"dựa vào gợi ý tự động"},{"en":"keep basic skills sharp","vi":"duy trì kỹ năng cơ bản"},{"en":"solve a problem independently","vi":"tự giải quyết vấn đề"},{"en":"use a tool as support","vi":"dùng công cụ để hỗ trợ"},{"en":"understand the limitations","vi":"hiểu các giới hạn"},{"en":"make a considered choice","vi":"đưa ra lựa chọn cân nhắc"}],"grammar":"Dùng can support independence, provided that để nêu điều kiện sử dụng hợp lý.","sample":"Technology can make people less independent if they rely on automated suggestions without understanding them. At the same time, a map, translation tool or accessible device can help someone solve a problem on their own. The effect depends on how the tool is used. People should keep basic skills sharp and understand limitations, treating technology as support rather than handing every decision to it.","reviewed":false}},{"id":"technology-that-saves-time-part3-03","type":"part3-question","part":3,"q":"How can technology be designed to help people with disabilities?","reviewed":false,"aid":{"idea":["Tùy chọn chữ, âm thanh và điều khiển giúp tiếp cận","Tham khảo người dùng khuyết tật trong quá trình thiết kế"],"vocab":[{"en":"adjustable text size","vi":"cỡ chữ có thể điều chỉnh"},{"en":"screen-reader support","vi":"hỗ trợ trình đọc màn hình"},{"en":"voice control","vi":"điều khiển bằng giọng nói"},{"en":"design with users","vi":"thiết kế cùng người dùng"},{"en":"remove an access barrier","vi":"loại bỏ rào cản tiếp cận"},{"en":"work across devices","vi":"hoạt động trên nhiều thiết bị"}],"grammar":"Dùng designers should involve để nhấn vai trò tham gia của người dùng trong thiết kế.","sample":"Designers should involve people with disabilities throughout testing, rather than guess what support they need. Adjustable text, screen-reader compatibility, captions and voice control can remove different access barriers. Features should also work across common devices and be easy to find. Accessibility is most effective when it is part of the original design, because retrofitting a product later can be expensive and incomplete.","reviewed":false}},{"id":"technology-that-saves-time-part3-04","type":"part3-question","part":3,"q":"Should people replace electronic devices as soon as a newer model appears?","reviewed":false,"aid":{"idea":["Thiết bị cũ vẫn đủ dùng thì không cần thay ngay","Cân nhắc sửa chữa, an ninh và tuổi thọ hỗ trợ"],"vocab":[{"en":"a newer model","vi":"mẫu mới hơn"},{"en":"still meet basic needs","vi":"vẫn đáp ứng nhu cầu cơ bản"},{"en":"security updates","vi":"bản cập nhật bảo mật"},{"en":"repair the existing device","vi":"sửa thiết bị hiện có"},{"en":"electronic waste","vi":"rác thải điện tử"},{"en":"consider the full lifespan","vi":"cân nhắc toàn bộ tuổi thọ"}],"grammar":"Dùng there is little reason to replace khi thiết bị hiện tại vẫn đáp ứng mục đích.","sample":"There is little reason to replace a device simply because a newer model appears, if the current one still meets basic needs. People should consider security updates, repair options and the product's remaining lifespan. Replacing useful electronics too often contributes to waste and extra expense. A newer model may be worthwhile when it improves safety or accessibility, but the decision should be based on need rather than marketing alone.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A device that helps me focus"},{"id":"person-i-admire","topic":"A person you admire","task":"Describe a person you admire.","bullets":["who the person is","how you know about them","what qualities you admire","what you have learned from them"],"conclusion":"and explain how this person has influenced you.","reviewed":false,"aid":{"idea":["Chọn người thân hoặc người trong cộng đồng bạn quan sát được","Nêu hành động cụ thể thể hiện phẩm chất","Liên hệ một thói quen bạn muốn học theo"],"vocab":[{"en":"lead by example","vi":"làm gương bằng hành động"},{"en":"make time for others","vi":"dành thời gian cho người khác"},{"en":"follow through on a promise","vi":"thực hiện đúng lời hứa"},{"en":"a quiet determination","vi":"sự quyết tâm âm thầm"},{"en":"earn people's trust","vi":"chiếm được lòng tin của mọi người"},{"en":"influence me in a positive way","vi":"ảnh hưởng đến tôi theo hướng tích cực"}],"grammar":"Dùng hiện tại đơn mô tả phẩm chất, quá khứ đơn kể ví dụ và hiện tại hoàn thành nói ảnh hưởng đến nay.","sample":"A person I admire is my aunt, who helps organise a small reading group at a community centre. I have known her all my life, but I began to appreciate her more when I saw how consistently she gives her time to other people. She is not a public figure or someone who talks about success. Instead, she follows through on small promises, such as bringing books for children or checking that older visitors have a way to get home. When a planned session was cancelled because the room was unavailable, she found another local space and contacted everyone before they arrived. Her quiet determination earned the trust of the group. I admire her because she makes practical contributions without expecting attention. She also listens carefully when people suggest a change, which helps the activities feel welcoming. Watching her has influenced me to be more reliable in my own commitments. I now try to confirm plans early and offer specific help instead of saying vaguely that I am available. I do not think I can copy everything she does, but I have learned that kindness is often shown through repeated actions. Her example has reminded me that a person can make a positive difference within a small community, even without a formal title or a large audience.","reviewed":false},"part3Questions":[{"id":"person-i-admire-part3-01","type":"part3-question","part":3,"q":"What qualities make a person a good role model?","reviewed":false,"aid":{"idea":["Hành động nhất quán tạo sự tin cậy","Biết thừa nhận sai và tôn trọng người khác"],"vocab":[{"en":"act with integrity","vi":"hành động chính trực"},{"en":"treat people fairly","vi":"đối xử công bằng"},{"en":"admit a mistake","vi":"thừa nhận sai lầm"},{"en":"keep commitments","vi":"giữ cam kết"},{"en":"show respect in practice","vi":"thể hiện sự tôn trọng qua hành động"},{"en":"set a realistic example","vi":"làm gương thực tế"}],"grammar":"Dùng should be someone who để định nghĩa hình mẫu bằng hành vi cụ thể.","sample":"A good role model should act with integrity and treat people fairly, including when no reward is involved. Keeping commitments and admitting mistakes make someone more trustworthy. It is also important that their example is realistic rather than perfect, because people learn from seeing how challenges are handled. Admiration is healthiest when it encourages others to develop their own values instead of copying every choice.","reviewed":false}},{"id":"person-i-admire-part3-02","type":"part3-question","part":3,"q":"How can public figures influence young people?","reviewed":false,"aid":{"idea":["Thành tựu có thể truyền cảm hứng và làm lộ trình nghề nghiệp dễ thấy","Hành vi công khai cũng có thể tạo kỳ vọng thiếu thực tế"],"vocab":[{"en":"shape public attitudes","vi":"định hình thái độ công chúng"},{"en":"promote a positive habit","vi":"khuyến khích thói quen tích cực"},{"en":"an unrealistic image","vi":"hình ảnh thiếu thực tế"},{"en":"use a platform responsibly","vi":"sử dụng tầm ảnh hưởng có trách nhiệm"},{"en":"inspire a career interest","vi":"khơi gợi hứng thú nghề nghiệp"},{"en":"think critically about messages","vi":"suy nghĩ phản biện về thông điệp"}],"grammar":"Dùng can shape để nêu ảnh hưởng tới thái độ; thêm however khi muốn trình bày mặt trái.","sample":"Public figures can shape attitudes by talking about work, education, health or social issues. Their achievements may inspire a young person to explore a new career. However, constant promotion of wealth or appearance can create unrealistic expectations. Public figures should use their platform responsibly, and schools and families can help young people think critically about messages rather than accept every image as a complete picture.","reviewed":false}},{"id":"person-i-admire-part3-03","type":"part3-question","part":3,"q":"Do children need famous people as role models?","reviewed":false,"aid":{"idea":["Người nổi tiếng có thể mở rộng hình dung về khả năng","Người gần gũi cho ví dụ thực tế trong đời sống"],"vocab":[{"en":"look up to someone","vi":"ngưỡng mộ ai đó"},{"en":"show what is possible","vi":"cho thấy điều gì có thể làm được"},{"en":"a relatable example","vi":"tấm gương gần gũi"},{"en":"influence everyday behaviour","vi":"ảnh hưởng hành vi hằng ngày"},{"en":"learn from different people","vi":"học hỏi từ nhiều người"},{"en":"balance public and personal examples","vi":"cân bằng hình mẫu công chúng và cá nhân"}],"grammar":"Dùng children can learn from several types of people để tránh lựa chọn nhị nguyên.","sample":"Famous people can show children what is possible in sport, science or the arts, but they are not the only useful role models. Parents, teachers and neighbours demonstrate everyday responsibility and kindness. Children can learn from several types of people, especially when adults help them discuss both strengths and mistakes. A balance of public and personal examples gives a more complete picture of success.","reviewed":false}},{"id":"person-i-admire-part3-04","type":"part3-question","part":3,"q":"Why do some people admire actions more than achievements?","reviewed":false,"aid":{"idea":["Thành tựu cho thấy kết quả nhưng không giải thích cách đạt được","Hành vi hằng ngày thể hiện giá trị và cách đối xử"],"vocab":[{"en":"the process behind success","vi":"quá trình phía sau thành công"},{"en":"everyday acts of kindness","vi":"hành động tử tế hằng ngày"},{"en":"show personal values","vi":"thể hiện giá trị cá nhân"},{"en":"treat others with care","vi":"đối xử ân cần với người khác"},{"en":"look beyond public recognition","vi":"nhìn xa hơn sự công nhận công khai"},{"en":"leave a meaningful impact","vi":"để lại ảnh hưởng ý nghĩa"}],"grammar":"Dùng whereas để phân biệt kết quả nổi bật với hành động thường ngày.","sample":"Achievements are visible, but they may not show how a person reached them or treated others along the way. Everyday actions can reveal values more directly, such as whether someone keeps a promise or offers help without attention. People may admire both, but consistent behaviour often feels more relatable. It suggests that a meaningful impact is possible without public recognition or an exceptional career.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"Someone who contributes quietly"},{"id":"future-job","topic":"A job you would like to do","task":"Describe a job that you would like to do in the future.","bullets":["what the job would be","what kind of work it involves","what skills it requires","why it interests you"],"conclusion":"and explain what you might do to prepare for this job.","reviewed":false,"aid":{"idea":["Chọn nghề có nhiệm vụ bạn muốn làm hằng ngày","Nêu kỹ năng cần học và phần khó có thể gặp","Mô tả bước chuẩn bị thực tế"],"vocab":[{"en":"a career in urban planning","vi":"nghề quy hoạch đô thị"},{"en":"design liveable neighbourhoods","vi":"thiết kế khu dân cư đáng sống"},{"en":"balance different priorities","vi":"cân bằng các ưu tiên khác nhau"},{"en":"work with local communities","vi":"làm việc với cộng đồng địa phương"},{"en":"develop technical knowledge","vi":"phát triển kiến thức chuyên môn"},{"en":"gain relevant experience","vi":"tích lũy kinh nghiệm phù hợp"}],"grammar":"Dùng would be interested in + V-ing để nêu sở thích nghề và would need to để nói yêu cầu.","sample":"A job I would like to do in the future is urban planning. I am interested in how streets, parks, housing and public transport fit together and affect daily life. The work involves studying maps and local information, discussing proposals with residents and helping design liveable neighbourhoods. A planner needs technical knowledge, clear communication and the ability to balance different priorities. For example, a road project may improve travel times but affect nearby homes or trees. I like the idea of finding practical solutions that serve several groups rather than focusing on one feature. I know the work can involve regulations, long meetings and difficult trade-offs, so it would not be creative every day. To prepare, I would study geography or planning, improve my data skills and learn how public consultations work. I would also look for an internship or volunteer project connected to community design. I have not decided that this will definitely be my career, but researching it has made me more curious about how neighbourhoods develop. I would find the job meaningful if I could combine evidence with local knowledge and see a plan improve people's everyday experience over time.","reviewed":false},"part3Questions":[{"id":"future-job-part3-01","type":"part3-question","part":3,"q":"What factors should young people consider when choosing a career?","reviewed":false,"aid":{"idea":["Cân nhắc sở thích và kỹ năng hiện tại","Xem xét cơ hội, thu nhập, môi trường và khả năng đổi hướng"],"vocab":[{"en":"match personal strengths","vi":"phù hợp thế mạnh cá nhân"},{"en":"research employment options","vi":"tìm hiểu lựa chọn việc làm"},{"en":"consider working conditions","vi":"cân nhắc điều kiện làm việc"},{"en":"develop transferable skills","vi":"phát triển kỹ năng dùng ở nhiều nghề"},{"en":"allow room to change direction","vi":"chừa khả năng đổi hướng"},{"en":"make an informed decision","vi":"đưa ra quyết định có đủ thông tin"}],"grammar":"Dùng should consider both để nhóm ưu tiên cá nhân và điều kiện thực tế.","sample":"Young people should consider both personal interests and practical conditions such as job availability, training and working hours. Matching a career to current strengths can make learning more engaging, while transferable skills keep future options open. Income matters, but it is not the only factor. Talking to people in a field and trying a short placement can help someone make a more informed decision.","reviewed":false}},{"id":"future-job-part3-02","type":"part3-question","part":3,"q":"How might automation affect jobs in the future?","reviewed":false,"aid":{"idea":["Một số nhiệm vụ lặp lại có thể tự động hóa","Nhu cầu kỹ năng mới và vai trò giám sát có thể tăng"],"vocab":[{"en":"automate repetitive work","vi":"tự động hóa việc lặp lại"},{"en":"change the task mix","vi":"thay đổi cơ cấu nhiệm vụ"},{"en":"create new roles","vi":"tạo vai trò mới"},{"en":"reskill the workforce","vi":"đào tạo lại lực lượng lao động"},{"en":"human judgement","vi":"đánh giá của con người"},{"en":"share productivity gains","vi":"chia sẻ lợi ích năng suất"}],"grammar":"Dùng may change rather than eliminate all jobs để dự báo có điều kiện.","sample":"Automation may change the task mix in many jobs rather than eliminate every role. Repetitive work can be handled by software or machines, while people may focus more on judgement, communication and oversight. Some new roles will emerge, and workers may need retraining. The effects will vary by industry, so employers and governments should help people reskill and share productivity gains fairly.","reviewed":false}},{"id":"future-job-part3-03","type":"part3-question","part":3,"q":"Is job satisfaction more important than a high salary?","reviewed":false,"aid":{"idea":["Cả thu nhập ổn định và sự hài lòng đều quan trọng","Mức ưu tiên tùy trách nhiệm và giai đoạn cuộc sống"],"vocab":[{"en":"meet basic expenses","vi":"đáp ứng chi phí cơ bản"},{"en":"feel engaged at work","vi":"cảm thấy gắn kết với công việc"},{"en":"a fair salary","vi":"mức lương công bằng"},{"en":"long-term well-being","vi":"hạnh phúc lâu dài"},{"en":"financial responsibilities","vi":"trách nhiệm tài chính"},{"en":"find a workable balance","vi":"tìm sự cân bằng khả thi"}],"grammar":"Dùng neither factor should be ignored để mở câu trả lời cân bằng.","sample":"Neither job satisfaction nor salary should be ignored. A fair income helps people meet expenses and manage responsibilities, while meaningful work can support motivation and long-term well-being. The balance depends on a person's stage of life and financial situation. Someone with dependants may prioritise stability for a time, whereas another person might accept a lower salary for a role that offers valuable learning or healthier conditions.","reviewed":false}},{"id":"future-job-part3-04","type":"part3-question","part":3,"q":"What can schools do to prepare students for working life?","reviewed":false,"aid":{"idea":["Kết hợp môn học với dự án và kỹ năng giao tiếp","Giúp học sinh khám phá nghề qua trải nghiệm ngắn"],"vocab":[{"en":"practise clear communication","vi":"luyện giao tiếp rõ ràng"},{"en":"complete a team project","vi":"hoàn thành dự án nhóm"},{"en":"understand workplace expectations","vi":"hiểu kỳ vọng nơi làm việc"},{"en":"explore different professions","vi":"khám phá nhiều nghề"},{"en":"learn from a short placement","vi":"học qua đợt trải nghiệm ngắn"},{"en":"connect lessons to real tasks","vi":"kết nối bài học với nhiệm vụ thực tế"}],"grammar":"Dùng schools can prepare students by combining để đề xuất nhiều hình thức học.","sample":"Schools can prepare students by combining subject knowledge with communication, teamwork and practical projects. Short workplace visits or placements can help learners understand different professions before they choose a path. Teachers can also connect lessons to real tasks, such as planning a budget or presenting a proposal. Career preparation should inform students without forcing them to make a permanent decision too early.","reviewed":false}}],"type":"part2-cue-card","part":2,"title":"A career I am exploring"}],"readOnly":true};
})(window);
